select * from (values
  ('active', '一毛不拔', 'ㄧ ㄇㄠˊ ㄅㄨˋ ㄅㄚˊ', '成語', 3, '一根毫毛也不願意拔取。比喻自私自利，不肯貢獻出些微的力量。語本《孟子．盡心上》。後亦用「一毛不拔」形容人非常吝嗇。', '一根毫毛也不願意拔取。比喻自私自利，不肯貢獻出些微的力量。語本《孟子．盡心上》。後亦用「一毛不拔」形容人非常吝嗇。 △「愛財如命」、「摩頂放踵」', '形容人非常吝嗇。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他就像隻鐵公雞，一毛不拔。', '他就像隻鐵公雞，一毛不拔。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"1"}'::jsonb)
  ,('active', '掩耳盜鈴', 'ㄧㄢˇ ㄦˇ ㄉㄠˋ ㄌㄧㄥˊ', '成語', 3, '「掩耳盜鈴」之「鈴」，典源作「鍾」。「鍾」同「鐘」。小偷盜鐘時，怕鐘所發出的聲音會引他人前來搶奪，因而急忙掩住自己的耳朵。典出《呂氏春秋．不苟論．自知》。後用「掩耳盜鈴」比喻妄想瞞騙他人，結果卻只是欺騙自己而已。', '「掩耳盜鈴」之「鈴」，典源作「鍾」。「鍾」同「鐘」。小偷盜鐘時，怕鐘所發出的聲音會引他人前來搶奪，因而急忙掩住自己的耳朵。典出《呂氏春秋．不苟論．自知》。後用「掩耳盜鈴」比喻妄想瞞騙他人，結果卻只是欺騙自己而已。 △「自欺欺人」。', '比喻妄想瞞騙他人，結果卻只是欺騙自己而已。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '如果不去努力，只會用謊言自欺，就是掩耳盜鈴。', '如果不去努力，只會用謊言自欺，就是掩耳盜鈴。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"2"}'::jsonb)
  ,('active', '囫圇吞棗', 'ㄏㄨˊ ㄌㄨㄣˊ ㄊㄨㄣ ㄗㄠˇ', '成語', 3, '「囫圇吞棗」之「囫圇」，典源作「渾崙」。「渾崙」同「囫圇」。囫圇，整個。「囫圇吞棗」指吃棗子時不加咀嚼，把整個都吞下去。＃語本《佛果圜悟禪師碧巖錄．卷三．趙州大蘿蔔頭》。後用「囫圇吞棗」比喻理解事物籠統含糊，或為學不求甚解。', '「囫圇吞棗」之「囫圇」，典源作「渾崙」。「渾崙」同「囫圇」。囫圇，整個。「囫圇吞棗」指吃棗子時不加咀嚼，把整個都吞下去。＃語本《佛果圜悟禪師碧巖錄．卷三．趙州大蘿蔔頭》。後用「囫圇吞棗」比喻理解事物籠統含糊，或為學不求甚解。 △「生吞活剝」', '比喻理解事物籠統含糊，或為學不求甚解。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '許多基本概念的學習是不能囫圇吞棗的。', '許多基本概念的學習是不能囫圇吞棗的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"3"}'::jsonb)
  ,('active', '朝三暮四', 'ㄓㄠ ㄙㄢ ㄇㄨˋ ㄙˋ', '成語', 3, '餵養猴子時，早晨給三升橡樹果實，晚上給四升，但亦可改變為「朝四暮三」。本為養猴人詐騙猴子的故事。典出《莊子．齊物論》。原用以比喻只變名目，不改實質。後用「朝三暮四」比喻人心意不定、反覆無常。亦可用於比喻事物變化無定。', '餵養猴子時，早晨給三升橡樹果實，晚上給四升，但亦可改變為「朝四暮三」。本為養猴人詐騙猴子的故事。典出《莊子．齊物論》。原用以比喻只變名目，不改實質。後用「朝三暮四」比喻人心意不定、反覆無常。亦可用於比喻事物變化無定。 △「反覆無常」、「出爾反爾」、「朝秦暮楚」', '比喻心意不定、反覆無常。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他老是朝三暮四地換工作，怎會有成就？', '他老是朝三暮四地換工作，怎會有成就？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"4"}'::jsonb)
  ,('active', '竭澤而漁', 'ㄐㄧㄝˊ ㄗㄜˊ ㄦˊ ㄩˊ', '成語', 3, '澤，水流匯聚的地方。「竭澤而漁」指排盡澤水捕魚。比喻取盡所有，不留餘地。＃語出《呂氏春秋．孝行覽．義賞》。', '澤，水流匯聚的地方。「竭澤而漁」指排盡澤水捕魚。比喻取盡所有，不留餘地。＃語出《呂氏春秋．孝行覽．義賞》。 △「殺雞取卵」', '比喻盡其所有，不留餘地。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '用流刺網捕魚，就是在竭澤而漁！', '用流刺網捕魚，就是在竭澤而漁！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"5"}'::jsonb)
  ,('active', '舉一反三', 'ㄐㄩˇ ㄧ ㄈㄢˇ ㄙㄢ', '成語', 3, '反，推論。「舉一反三」指從一件事情類推，而知道其他同類的事情。語本《論語．述而》。後用「舉一反三」形容人於學習中善於觸類旁通。', '反，推論。「舉一反三」指從一件事情類推，而知道其他同類的事情。語本《論語．述而》。後用「舉一反三」形容人於學習中善於觸類旁通。 △「聞一知十」', '形容人於學習中善於觸類旁通。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '凡事能舉一反三，正是他學習快速的原因。', '凡事能舉一反三，正是他學習快速的原因。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"6"}'::jsonb)
  ,('active', '青出於藍', 'ㄑㄧㄥ ㄔㄨ ㄩˊ ㄌㄢˊ', '成語', 3, '藍，蓼（ㄌㄧㄠˇ）藍，可以提取靛（ㄉㄧㄢˋ）青染料的植物。「青出於藍」指青色是從蓼藍裡提煉出來的，但是顏色比蓼藍還深。比喻求學能使人進步。＃語本《荀子．勸學》。後用「青出於藍」比喻弟子勝過老師，或後輩優於前輩。', '藍，蓼（ㄌㄧㄠˇ）藍，可以提取靛（ㄉㄧㄢˋ）青染料的植物。「青出於藍」指青色是從蓼藍裡提煉出來的，但是顏色比蓼藍還深。比喻求學能使人進步。＃語本《荀子．勸學》。後用「青出於藍」比喻弟子勝過老師，或後輩優於前輩。 △「冰寒於水」、「後來居上」', '比喻弟子勝過老師，或後輩優於前輩。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '徒弟能青出於藍，正是老師最大的安慰。', '徒弟能青出於藍，正是老師最大的安慰。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"7"}'::jsonb)
  ,('active', '含沙射影', 'ㄏㄢˊ ㄕㄚ ㄕㄜˋ ㄧㄥˇ', '成語', 3, '「含沙射影」本作「含沙射人」。相傳古代有一種水中怪物叫「蜮」，會把口中所含的沙粒射到人身上或影子上，使人生病甚至死亡。＃語本晉．干寶《搜神記》卷一二。後以「含沙射影」比喻間接地詆毀、陷害別人。', '「含沙射影」本作「含沙射人」。相傳古代有一種水中怪物叫「蜮」，會把口中所含的沙粒射到人身上或影子上，使人生病甚至死亡。＃語本晉．干寶《搜神記》卷一二。後以「含沙射影」比喻間接地詆毀、陷害別人。 △「含血噴人」、「暗箭傷人」', '比喻間接地詆毀、陷害別人。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這番話含沙射影，真是卑劣。', '他這番話含沙射影，真是卑劣。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"8"}'::jsonb)
  ,('active', '草木皆兵', 'ㄘㄠˇ ㄇㄨˋ ㄐㄧㄝ ㄅㄧㄥ', '成語', 3, '見到風吹草動，都以為是敵兵。語本《晉書．卷一一四．苻堅載記下》。後用「草木皆兵」形容疑神疑鬼、驚恐不安。', '見到風吹草動，都以為是敵兵。語本《晉書．卷一一四．苻堅載記下》。後用「草木皆兵」形容疑神疑鬼、驚恐不安。 △「杯弓蛇影」、「風聲鶴唳」、「風聲鶴唳，草木皆兵」', '形容疑神疑鬼、驚恐不安。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '每天躲警報，真是心驚膽戰，草木皆兵。', '每天躲警報，真是心驚膽戰，草木皆兵。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"9"}'::jsonb)
  ,('active', '東窗事發', 'ㄉㄨㄥ ㄔㄨㄤ ㄕˋ ㄈㄚ', '成語', 3, '在東窗下的密謀已經被揭發。＃語出元．劉一清《錢塘遺事．卷二．東窗事發》。後用「東窗事發」指陰謀或非法勾當敗露。', '在東窗下的密謀已經被揭發。＃語出元．劉一清《錢塘遺事．卷二．東窗事發》。後用「東窗事發」指陰謀或非法勾當敗露。 △「露出馬腳」', '指陰謀或非法勾當敗漏。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你們幹盡這般醜事，如今東窗事發，法律難容！', '你們幹盡這般醜事，如今東窗事發，法律難容！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"10"}'::jsonb)
  ,('active', '勢如破竹', 'ㄕˋ ㄖㄨˊ ㄆㄛˋ ㄓㄨˊ', '成語', 3, '形勢如同劈竹子一般，只要劈開上端，底下自然就會隨著刀勢分開。比喻戰事進展順利，毫無阻礙。語本《晉書．卷三四．杜預列傳》。後亦用「勢如破竹」來比喻事情進展順利，毫無阻礙。', '形勢如同劈竹子一般，只要劈開上端，底下自然就會隨著刀勢分開。比喻戰事進展順利，毫無阻礙。語本《晉書．卷三四．杜預列傳》。後亦用「勢如破竹」來比喻事情進展順利，毫無阻礙。 △「銳不可當」、「勢不可當」', '比喻戰事進展順利。＆比喻事情進展順利。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '國軍一路挺進，勢如破竹。', '國軍一路挺進，勢如破竹。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"11"}'::jsonb)
  ,('active', '滄海桑田', 'ㄘㄤ ㄏㄞˇ ㄙㄤ ㄊㄧㄢˊ', '成語', 3, '滄海，指大海。桑田，植桑之田，指陸地。「滄海桑田」指大海變為陸地，陸地淪為大海。比喻環境改變很大。語本晉．葛洪《神仙傳》。後亦用「滄海桑田」比喻世事無常，變化很快。', '滄海，指大海。桑田，植桑之田，指陸地。「滄海桑田」指大海變為陸地，陸地淪為大海。比喻環境改變很大。語本晉．葛洪《神仙傳》。後亦用「滄海桑田」比喻世事無常，變化很快。 △「白雲蒼狗」、「滄海揚塵」', '大海變為陸地，陸地淪為大海。比喻環境變化很大。＆比喻世事無常，變化很快。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '管它滄海成桑田，真情永遠不變。', '管它滄海成桑田，真情永遠不變。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"12"}'::jsonb)
  ,('active', '夜郎自大', 'ㄧㄝˋ ㄌㄤˊ ㄗˋ ㄉㄚˋ', '成語', 3, '夜郎，漢代西南邊境的一個小國。「夜郎自大」指夜郎國王妄自尊大。＃典出《史記．卷一一六．西南夷列傳》。後用「夜郎自大」比喻人見識短淺，狂妄自大。', '夜郎，漢代西南邊境的一個小國。「夜郎自大」指夜郎國王妄自尊大。＃典出《史記．卷一一六．西南夷列傳》。後用「夜郎自大」比喻人見識短淺，狂妄自大。 △「妄自尊大」', '比喻人見識短淺，狂妄自大。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '夜郎自大的人，讓人感到既可笑又可憐。', '夜郎自大的人，讓人感到既可笑又可憐。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"13"}'::jsonb)
  ,('active', '信口雌黃', 'ㄒㄧㄣˋ ㄎㄡˇ ㄘ ㄏㄨㄤˊ', '成語', 3, '雌黃，橙黃色礦物，成分是三硫化二砷，可作退色劑，古代用於塗改文字。本指有如口中含著雌黃，能隨時改正不合意的語句。＃語本晉．孫盛《晉陽秋》。後用「信口雌黃」比喻不顧事實真相，隨口亂說或妄加批評。', '雌黃，橙黃色礦物，成分是三硫化二砷，可作退色劑，古代用於塗改文字。本指有如口中含著雌黃，能隨時改正不合意的語句。＃語本晉．孫盛《晉陽秋》。後用「信口雌黃」比喻不顧事實真相，隨口亂說或妄加批評。 △「妄下雌黃」、「信口開河」', '比喻不顧事實真相，隨口亂說或妄加批評。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '一個人要是老信口雌黃，怎會受到歡迎？', '一個人要是老信口雌黃，怎會受到歡迎？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"14"}'::jsonb)
  ,('active', '作法自斃', 'ㄗㄨㄛˋ ㄈㄚˇ ㄗˋ ㄅㄧˋ', '成語', 3, '「作法自斃」之「斃」，典源作「敝」。「敝」，義同「斃」。自己訂立的法規，反而使自己受害。比喻自作自受。語本《史記．卷六八．商君列傳》。', '「作法自斃」之「斃」，典源作「敝」。「敝」，義同「斃」。自己訂立的法規，反而使自己受害。比喻自作自受。語本《史記．卷六八．商君列傳》。 △「作繭自縛」', '比喻自作自受。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這件事他是作法自斃，怨天尤人有何用？', '這件事他是作法自斃，怨天尤人有何用？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"15"}'::jsonb)
  ,('active', '杞人憂天', 'ㄑㄧˇ ㄖㄣˊ ㄧㄡ ㄊㄧㄢ', '成語', 3, '古時杞國有個人，因為擔心天會塌下來而憂慮不安。典出《列子．天瑞》。後用「杞人憂天」比喻缺乏根據且不必要的憂慮。', '古時杞國有個人，因為擔心天會塌下來而憂慮不安。典出《列子．天瑞》。後用「杞人憂天」比喻缺乏根據且不必要的憂慮。 △「庸人自擾」', '比喻缺乏根據且不必要的憂慮。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '事情狀況未明，大家先別杞人憂天，亂了陣腳！', '事情狀況未明，大家先別杞人憂天，亂了陣腳！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"16"}'::jsonb)
  ,('active', '不學無術', 'ㄅㄨˋ ㄒㄩㄝˊ ㄨˊ ㄕㄨˋ', '成語', 3, '「不學無術」之「無」，典源作「亡」。「亡」通「無」。指不知研習經典，並從中獲取經驗與知識，以致行為處事有所偏頗或錯誤。語出《漢書．卷六八．霍光金日磾傳．霍光》。後用「不學無術」泛指人未經學習而沒有學問才幹。', '「不學無術」之「無」，典源作「亡」。「亡」通「無」。指不知研習經典，並從中獲取經驗與知識，以致行為處事有所偏頗或錯誤。語出《漢書．卷六八．霍光金日磾傳．霍光》。後用「不學無術」泛指人未經學習而沒有學問才幹。 △「目不識丁」、「胸無點墨」', '人未經學習而沒有學問才幹。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他的心地雖然不壞，卻因不學無術而不能獲得大家的認同。', '他的心地雖然不壞，卻因不學無術而不能獲得大家的認同。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"17"}'::jsonb)
  ,('active', '走馬看花', 'ㄗㄡˇ ㄇㄚˇ ㄎㄢˋ ㄏㄨㄚ', '成語', 3, '（一）騎馬快走以觀賞花景，形容抱負實現或遊賞時得意愉快的心情。語本唐．孟郊〈登科後〉詩。', '（一）騎馬快走以觀賞花景，形容抱負實現或遊賞時得意愉快的心情。語本唐．孟郊〈登科後〉詩。 △「走馬探花」、「春風得意」 （二）比喻粗略、匆促地觀看，不能仔細深入了解事物。※語或出清．吳喬《圍爐詩話》卷三。 △「走馬看錦」、「浮光掠影」', '比喻粗略、匆促地觀看，不能仔細深入。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '讀書如走馬看花，結果當然是了無心得。', '讀書如走馬看花，結果當然是了無心得。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"18"}'::jsonb)
  ,('active', '杯弓蛇影', 'ㄅㄟ ㄍㄨㄥ ㄕㄜˊ ㄧㄥˇ', '成語', 3, '將酒杯裡的弓影，誤以為是蛇，以致喝下後心生疑懼。＃典出漢．應劭《風俗通義．卷九．世間多有見怪驚怖以自傷者》。後用「杯弓蛇影」比喻為不存在的事情枉自驚擾。', '將酒杯裡的弓影，誤以為是蛇，以致喝下後心生疑懼。＃典出漢．應劭《風俗通義．卷九．世間多有見怪驚怖以自傷者》。後用「杯弓蛇影」比喻為不存在的事情枉自驚擾。 △「風聲鶴唳」、「草木皆兵」', '比喻為不存在的事情枉自驚疑恐懼。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你別嚇他，小心他杯弓蛇影會真以為喝了髒水。', '你別嚇他，小心他杯弓蛇影會真以為喝了髒水。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"19"}'::jsonb)
  ,('active', '東山再起', 'ㄉㄨㄥ ㄕㄢ ㄗㄞˋ ㄑㄧˇ', '成語', 3, '指晉朝人謝安退職隱居東山，後來又再度入朝擔任要職。＃典出南朝宋．劉義慶《世說新語．排調》。後用「東山再起」比喻官員退隱後，再度出任官職。亦用於比喻失敗後重新崛起。', '指晉朝人謝安退職隱居東山，後來又再度入朝擔任要職。＃典出南朝宋．劉義慶《世說新語．排調》。後用「東山再起」比喻官員退隱後，再度出任官職。亦用於比喻失敗後重新崛起。 △「捲土重來」', '比喻官員退隱後，再度出任官職。＆比喻失敗後重新崛起。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '睽違政壇多年後，他東山再起，高票當選立委。', '睽違政壇多年後，他東山再起，高票當選立委。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"20"}'::jsonb)
  ,('active', '樂不思蜀', 'ㄌㄜˋ ㄅㄨˋ ㄙ ㄕㄨˇ', '成語', 3, '快樂到一點也不想回去蜀國。典出晉．習鑿齒《漢晉春秋》。後用「樂不思蜀」比喻人因留戀異地而不想返回故鄉。或形容快樂得忘了歸去。', '快樂到一點也不想回去蜀國。典出晉．習鑿齒《漢晉春秋》。後用「樂不思蜀」比喻人因留戀異地而不想返回故鄉。或形容快樂得忘了歸去。 △「流遯忘反」、「樂而忘返」', '比喻人因留戀異地而不想返回故鄉。＆形容快樂得忘了歸去。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你到了國外，可別樂不思蜀，忘了我們。', '你到了國外，可別樂不思蜀，忘了我們。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"21"}'::jsonb)
  ,('active', '濫竽充數', 'ㄌㄢˋ ㄩˊ ㄔㄨㄥ ㄕㄨˋ', '成語', 3, '竽，古代一種吹奏樂器。「濫竽充數」意謂不會吹竽的人，混雜於眾多樂工中湊數。典出《韓非子．內儲說上》。後用「濫竽充數」比喻沒有真才實學的人，混在行家中充數。亦用於比喻拿不好的東西充場面。亦用於自謙，比喻自己才德不足。', '竽，古代一種吹奏樂器。「濫竽充數」意謂不會吹竽的人，混雜於眾多樂工中湊數。典出《韓非子．內儲說上》。後用「濫竽充數」比喻沒有真才實學的人，混在行家中充數。亦用於比喻拿不好的東西充場面。亦用於自謙，比喻自己才德不足。 △「魚目混珠」', '比喻沒有真才實學的人，混在行家中充數。貶義。＆比喻拿不好的東西充場面。貶義。＆作為自謙之詞，比喻自己才德不足。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '不怕你笑，我們團裡濫竽充數者大有人在。', '不怕你笑，我們團裡濫竽充數者大有人在。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"22"}'::jsonb)
  ,('active', '功虧一簣', 'ㄍㄨㄥ ㄎㄨㄟ ㄧ ㄎㄨㄟˋ', '成語', 3, '堆土成山，已至九仞，卻因差最後一簣而不能成功。比喻事情只差最後一步，卻因未能堅持到底而前功盡棄。語出《書經．旅獒》。', '堆土成山，已至九仞，卻因差最後一簣而不能成功。比喻事情只差最後一步，卻因未能堅持到底而前功盡棄。語出《書經．旅獒》。 △「功敗垂成」、「前功盡棄」', '比喻事情只差最後一步，卻因未能堅持到底而前功盡棄。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這件事情所以功虧一簣，都因我最後的輕忽。', '這件事情所以功虧一簣，都因我最後的輕忽。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"23"}'::jsonb)
  ,('active', '入木三分', 'ㄖㄨˋ ㄇㄨˋ ㄙㄢ ㄈㄣ', '成語', 3, '指墨跡深透木板三分，形容筆力遒勁。＃語出南朝宋．羊欣《筆陣圖》。後用「入木三分」比喻評論深刻中肯或描寫生動逼真。', '指墨跡深透木板三分，形容筆力遒勁。＃語出南朝宋．羊欣《筆陣圖》。後用「入木三分」比喻評論深刻中肯或描寫生動逼真。 △「鞭辟入裡」', '形容筆力遒勁。＆比喻評論深刻中肯或描寫生動逼真。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '看他揮毫力透紙背，真可謂入木三分。', '看他揮毫力透紙背，真可謂入木三分。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"24"}'::jsonb)
  ,('active', '螳臂當車', 'ㄊㄤˊ ㄅㄧˋ ㄉㄤ ㄔㄜ', '成語', 3, '當車，音ㄉㄤ ㄔㄜ，立於車道中，後世或將「當」解為「擋」之假借，讀作ㄉㄤˇ。「螳臂當車」指螳螂立於車道中，舉起雙臂，妄想要阻擋車子前進。比喻不自量力。＃語本《莊子．人間世》。', '當車，音ㄉㄤ ㄔㄜ，立於車道中，後世或將「當」解為「擋」之假借，讀作ㄉㄤˇ。「螳臂當車」指螳螂立於車道中，舉起雙臂，妄想要阻擋車子前進。比喻不自量力。＃語本《莊子．人間世》。 △「蚍蜉撼樹」', '比喻不自量力。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這種螳臂當車的作法十分不智。', '他這種螳臂當車的作法十分不智。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"25"}'::jsonb)
  ,('active', '咄咄逼人', 'ㄉㄨㄛˋ ㄉㄨㄛˋ ㄅㄧ ㄖㄣˊ', '成語', 3, '（一）咄咄，本為驚嘆之聲。逼人，情勢逼人。「咄咄逼人」本形容情勢險惡逼人，使人畏懼的意思。語出南朝宋．劉義慶《世說新語．排調》。後用「咄咄逼人」形容言語凌厲，氣勢逼人。', '（一）咄咄，本為驚嘆之聲。逼人，情勢逼人。「咄咄逼人」本形容情勢險惡逼人，使人畏懼的意思。語出南朝宋．劉義慶《世說新語．排調》。後用「咄咄逼人」形容言語凌厲，氣勢逼人。 △「盲人瞎馬」、「盛氣凌人」 （二）形容詩文字畫等的氣勢逼近或超越前人的作品，令人敬畏。※＃語或出晉．衛鑠〈與釋某書〉。', '形容言語凌厲，氣勢迫人。 ＆形容詩文字畫等的氣勢逼近或超越前人的作品，令人敬畏。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位年輕人言辭犀利，咄咄逼人。', '這位年輕人言辭犀利，咄咄逼人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"26"}'::jsonb)
  ,('active', '出類拔萃', 'ㄔㄨ ㄌㄟˋ ㄅㄚˊ ㄘㄨㄟˋ', '成語', 3, '遠超出同類之上，高出同群。形容才能特出，超越眾人。語本《孟子．公孫丑上》。', '遠超出同類之上，高出同群。形容才能特出，超越眾人。語本《孟子．公孫丑上》。 △「出人頭地」、「超群絕倫」', '形容才能特出，超越眾人。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他的能力絕對是同行中出類拔萃的！', '他的能力絕對是同行中出類拔萃的！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"27"}'::jsonb)
  ,('active', '一竅不通', 'ㄧ ㄑㄧㄠˋ ㄅㄨˋ ㄊㄨㄥ', '成語', 3, '一個心竅都沒有通。語本《呂氏春秋．貴直論．過理》。後用「一竅不通」比喻人昏昧不明事理，或對某事完全不懂。', '一個心竅都沒有通。語本《呂氏春秋．貴直論．過理》。後用「一竅不通」比喻人昏昧不明事理，或對某事完全不懂。 △「一無所知」。', '比喻人昏昧不明事理。貶義。＆比喻人對某事完全不懂。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他固執到一竅不通，簡直勸不了他。', '他固執到一竅不通，簡直勸不了他。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"28"}'::jsonb)
  ,('active', '吹毛求疵', 'ㄔㄨㄟ ㄇㄠˊ ㄑㄧㄡˊ ㄘ', '成語', 3, '吹開細毛，仔細尋找皮上的小毛病。比喻刻意挑剔過失或缺點。＃語本《韓非子．大體》。', '吹開細毛，仔細尋找皮上的小毛病。比喻刻意挑剔過失或缺點。＃語本《韓非子．大體》。 △「求全責備」', '比喻刻意挑剔過失或缺點。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這個人事事吹毛求疵，很難相處。', '這個人事事吹毛求疵，很難相處。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"29"}'::jsonb)
  ,('active', '孤注一擲', 'ㄍㄨ ㄓㄨˋ ㄧ ㄓˊ', '成語', 3, '「孤注」，賭博時將所有資本下注。＃語出宋．司馬光《涑水記聞》卷六。「一擲」，擲一次骰子來決定勝負。※語或出《晉書．卷八五．何無忌列傳》。後以「孤注一擲」指賭博時，傾其所有而下注，並以一擲決定勝負。比喻危急時，投入全部力量，作最後的冒險。', '「孤注」，賭博時將所有資本下注。＃語出宋．司馬光《涑水記聞》卷六。「一擲」，擲一次骰子來決定勝負。※語或出《晉書．卷八五．何無忌列傳》。後以「孤注一擲」指賭博時，傾其所有而下注，並以一擲決定勝負。比喻危急時，投入全部力量，作最後的冒險。 △「背水一戰」', '比喻危急時，投入全部力量，作最後的冒險。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這種孤注一擲的做法，太冒險了。', '他這種孤注一擲的做法，太冒險了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"30"}'::jsonb)
  ,('active', '滄海一粟', 'ㄘㄤ ㄏㄞˇ ㄧ ㄙㄨˋ', '成語', 3, '大海中的一粒粟米。比喻渺小而微不足道。語本宋．蘇軾〈赤壁賦〉。', '大海中的一粒粟米。比喻渺小而微不足道。語本宋．蘇軾〈赤壁賦〉。 △「九牛一毛」', '比喻渺小而微不足道。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '每個人在天地間都如滄海一粟，怎能驕傲自大？', '每個人在天地間都如滄海一粟，怎能驕傲自大？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"31"}'::jsonb)
  ,('active', '痛心疾首', 'ㄊㄨㄥˋ ㄒㄧㄣ ㄐㄧˊ ㄕㄡˇ', '成語', 3, '疾首，頭痛。心中痛恨到頭都痛了。比喻痛恨到極點。語出《左傳．成公十三年》。', '疾首，頭痛。心中痛恨到頭都痛了。比喻痛恨到極點。語出《左傳．成公十三年》。 △「咬牙切齒」、「深惡痛絕」', '指痛恨到極點。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些痛心疾首的往事，不提也罷！', '這些痛心疾首的往事，不提也罷！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"32"}'::jsonb)
  ,('active', '扶搖直上', 'ㄈㄨˊ ㄧㄠˊ ㄓˊ ㄕㄤˋ', '成語', 3, '扶搖，自下盤旋而上的暴風。「扶搖直上」指隨急遽的旋風，盤旋而上。語本《莊子．逍遙遊》。後用「扶搖直上」比喻快速上升，亦用來比喻仕途得意。', '扶搖，自下盤旋而上的暴風。「扶搖直上」指隨急遽的旋風，盤旋而上。語本《莊子．逍遙遊》。後用「扶搖直上」比喻快速上升，亦用來比喻仕途得意。 △「青雲直上」', '比喻快速上升。＆比喻仕途得志。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '那部電影叫好又叫座，票房因此扶搖直上。', '那部電影叫好又叫座，票房因此扶搖直上。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"33"}'::jsonb)
  ,('active', '風聲鶴唳', 'ㄈㄥ ㄕㄥ ㄏㄜˋ ㄌㄧˋ', '成語', 3, '聽到風聲和鶴鳴，都以為是敵兵。語出《晉書．卷七九．謝安列傳》。後用「風聲鶴唳」形容驚慌疑懼，自相侵擾。', '聽到風聲和鶴鳴，都以為是敵兵。語出《晉書．卷七九．謝安列傳》。後用「風聲鶴唳」形容驚慌疑懼，自相侵擾。 △「杯弓蛇影」、「風聲鶴唳，草木皆兵」、「草木皆兵」、「草行露宿」', '形容驚慌疑懼，自相侵擾。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這一路奔逃下來，風聲鶴唳，人人驚惶。', '這一路奔逃下來，風聲鶴唳，人人驚惶。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"34"}'::jsonb)
  ,('active', '老當益壯', 'ㄌㄠˇ ㄉㄤ ㄧˋ ㄓㄨㄤˋ', '成語', 3, '指年紀雖大但身體仍然強健，且志氣豪壯。語出《後漢書．卷二四．馬援列傳》。', '指年紀雖大但身體仍然強健，且志氣豪壯。語出《後漢書．卷二四．馬援列傳》。 △「老驥伏櫪」', '年紀雖大但身體仍強健，且志氣豪壯。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '讓我們這些爺爺奶奶用歌聲唱出老當益壯的豪情。', '讓我們這些爺爺奶奶用歌聲唱出老當益壯的豪情。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"35"}'::jsonb)
  ,('active', '未雨綢繆', 'ㄨㄟˋ ㄩˇ ㄔㄡˊ ㄇㄡˊ', '成語', 3, '還沒有下雨之前，就先把門窗修好。語本《詩經．豳風．鴟鴞》。後用「未雨綢繆」比喻事先預備以防患未然。', '還沒有下雨之前，就先把門窗修好。語本《詩經．豳風．鴟鴞》。後用「未雨綢繆」比喻事先預備以防患未然。 △「防患未然」、「防微杜漸」', '比喻事先預備以防患未然。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '豐年儲糧可防災，這就叫未雨綢繆。', '豐年儲糧可防災，這就叫未雨綢繆。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"36"}'::jsonb)
  ,('active', '不共戴天', 'ㄅㄨˋ ㄍㄨㄥˋ ㄉㄞˋ ㄊㄧㄢ', '成語', 3, '不與殺父的仇人共存於世間。◎語本《禮記．曲禮上》。後用「不共戴天」比喻仇恨極深。', '不與殺父的仇人共存於世間。◎語本《禮記．曲禮上》。後用「不共戴天」比喻仇恨極深。 △「勢不兩立」', '比喻仇恨極深。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '父仇不共戴天，非報不可。', '父仇不共戴天，非報不可。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"37"}'::jsonb)
  ,('active', '剛愎自用', 'ㄍㄤ ㄅㄧˋ ㄗˋ ㄩㄥˋ', '成語', 3, '愎，任性、固執。「剛愎自用」指性情倔強，自以為是。＃語本《左傳．宣公十二年》。', '愎，任性、固執。「剛愎自用」指性情倔強，自以為是。＃語本《左傳．宣公十二年》。 △「師心自用」', '形容性情倔強，固執己見。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '想不到他如此剛愎自用，怎麼勸都沒用。', '想不到他如此剛愎自用，怎麼勸都沒用。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"38"}'::jsonb)
  ,('active', '出爾反爾', 'ㄔㄨ ㄦˇ ㄈㄢˇ ㄦˇ', '成語', 3, '你怎麼對待別人，別人也會怎麼待你。語本《孟子．梁惠王下》。後用「出爾反爾」比喻人的言行前後反覆，自相矛盾。', '你怎麼對待別人，別人也會怎麼待你。語本《孟子．梁惠王下》。後用「出爾反爾」比喻人的言行前後反覆，自相矛盾。 △「反覆無常」、「朝三暮四」、「朝秦暮楚」', '比喻人的言行前後反覆，自相矛盾。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你放心，我說了算數，絕不會出爾反爾。', '你放心，我說了算數，絕不會出爾反爾。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"39"}'::jsonb)
  ,('active', '目不識丁', 'ㄇㄨˋ ㄅㄨˋ ㄕˋ ㄉㄧㄥ', '成語', 3, '連「丁」字都不認識。比喻不識字或毫無學問。＃語本《舊唐書．卷一二九．張延賞列傳》。', '連「丁」字都不認識。比喻不識字或毫無學問。＃語本《舊唐書．卷一二九．張延賞列傳》。 △「不學無術」、「胸無點墨」', '比喻不識字或毫無學問。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他目不識丁，你寫字條給他有什麼用？', '他目不識丁，你寫字條給他有什麼用？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"40"}'::jsonb)
  ,('active', '百折不撓', 'ㄅㄞˇ ㄓㄜˊ ㄅㄨˋ ㄋㄠˊ', '成語', 3, '意志剛強，即使受到很多挫折，仍不屈服。語出漢．蔡邕〈太尉橋公碑〉。', '意志剛強，即使受到很多挫折，仍不屈服。語出漢．蔡邕〈太尉橋公碑〉。 △「不屈不撓」', '意志剛強，即使受到許多挫折，仍不屈服。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '要登世界高峰，得有百折不撓的毅力。', '要登世界高峰，得有百折不撓的毅力。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"41"}'::jsonb)
  ,('active', '拾人牙慧', 'ㄕˊ ㄖㄣˊ ㄧㄚˊ ㄏㄨㄟˋ', '成語', 3, '牙慧，言談間流露出的智慧。語本南朝宋．劉義慶《世說新語．文學》。後用「拾人牙慧」比喻蹈襲他人的言論或主張。', '牙慧，言談間流露出的智慧。語本南朝宋．劉義慶《世說新語．文學》。後用「拾人牙慧」比喻蹈襲他人的言論或主張。 △「人云亦云」、「拾人涕唾」', '比喻蹈襲他人的言論或主張。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這是拾人牙慧的看法，缺乏創意。', '這是拾人牙慧的看法，缺乏創意。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"42"}'::jsonb)
  ,('active', '耳濡目染', 'ㄦˇ ㄖㄨˊ ㄇㄨˋ ㄖㄢˇ', '成語', 3, '「耳濡目染」之「濡」，典源作「擩」。「擩」義同「濡」。濡，習染、感染。「耳濡目染」指經常聽到、看到而深受影響。語本唐．韓愈〈清河郡公房公墓碣銘〉。', '「耳濡目染」之「濡」，典源作「擩」。「擩」義同「濡」。濡，習染、感染。「耳濡目染」指經常聽到、看到而深受影響。語本唐．韓愈〈清河郡公房公墓碣銘〉。 △「潛移默化」', '經常聽到、看到而深受影響。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '大人都不學好，小孩每天耳濡目染，怎麼不變壞？', '大人都不學好，小孩每天耳濡目染，怎麼不變壞？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"43"}'::jsonb)
  ,('active', '杯水車薪', 'ㄅㄟ ㄕㄨㄟˇ ㄐㄩ ㄒㄧㄣ', '成語', 3, '以一杯水去撲滅一車木柴所燃起的火。比喻力量太小，無濟於事。＃語本《孟子．告子上》。', '以一杯水去撲滅一車木柴所燃起的火。比喻力量太小，無濟於事。＃語本《孟子．告子上》。 △「無濟於事」', '比喻力量太小，無濟於事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '久旱成災，今午下這場雷雨只是杯水車薪，無濟於事。', '久旱成災，今午下這場雷雨只是杯水車薪，無濟於事。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"44"}'::jsonb)
  ,('active', '車載斗量', 'ㄔㄜ ㄗㄞˋ ㄉㄡˇ ㄌㄧㄤˊ', '成語', 3, '用車裝，拿斗量。形容數量很多，不可勝數。語出《吳書》。', '用車裝，拿斗量。形容數量很多，不可勝數。語出《吳書》。 △「汗牛充棟」', '形容數量很多，不可勝數。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '網路資訊，車載斗量，多到難以應付。', '網路資訊，車載斗量，多到難以應付。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"45"}'::jsonb)
  ,('active', '燃眉之急', 'ㄖㄢˊ ㄇㄟˊ ㄓ ㄐㄧˊ', '成語', 3, '像火燒眉毛般緊迫。形容事態嚴重，情況危急。※語或出明．李開先〈亡妹盧氏婦墓志銘〉。', '像火燒眉毛般緊迫。形容事態嚴重，情況危急。※語或出明．李開先〈亡妹盧氏婦墓志銘〉。 △「當務之急」', '形容事態嚴重，情況危急。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '久旱成災，抗旱已成燃眉之急。', '久旱成災，抗旱已成燃眉之急。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"46"}'::jsonb)
  ,('active', '言不由衷', 'ㄧㄢˊ ㄅㄨˋ ㄧㄡˊ ㄓㄨㄥ', '成語', 3, '「言不由衷」之「衷」，典源作「中」。「中」同「衷」，指內心。「言不由衷」則指所說的話不是發自於內心。形容言詞與心意相違背。語本《左傳．隱公三年》。後用「言不由衷」泛指心口不一，虛應敷衍。', '「言不由衷」之「衷」，典源作「中」。「中」同「衷」，指內心。「言不由衷」則指所說的話不是發自於內心。形容言詞與心意相違背。語本《左傳．隱公三年》。後用「言不由衷」泛指心口不一，虛應敷衍。 △「口是心非」、「言由衷發」', '心口不一，虛應敷衍。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他的話言不由衷，聽起來真不舒服。', '他的話言不由衷，聽起來真不舒服。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"47"}'::jsonb)
  ,('active', '不倫不類', 'ㄅㄨˋ ㄌㄨㄣˊ ㄅㄨˋ ㄌㄟˋ', '成語', 3, '「不倫不類」有兩種解，一是不合道理、法式，二是不像樣。語本唐．劉知幾《史通．卷一六．雜說上》。後用「不倫不類」形容事物不成體統。', '「不倫不類」有兩種解，一是不合道理、法式，二是不像樣。語本唐．劉知幾《史通．卷一六．雜說上》。後用「不倫不類」形容事物不成體統。 △「不三不四」', '形容事物不成體統。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他聽對方話說得不倫不類，就藉口離開了。', '他聽對方話說得不倫不類，就藉口離開了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"48"}'::jsonb)
  ,('active', '虎頭蛇尾', 'ㄏㄨˇ ㄊㄡˊ ㄕㄜˊ ㄨㄟˇ', '成語', 3, '虎頭形大，蛇尾體小。做事起初聲勢浩大，後來卻無聲息。比喻做事有始無終。※語或出元．康進之《李逵負荊》第二折。', '虎頭形大，蛇尾體小。做事起初聲勢浩大，後來卻無聲息。比喻做事有始無終。※語或出元．康進之《李逵負荊》第二折。 △「有始無終」、「龍頭蛇尾」', '比喻做事有始無終。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '做事情要貫徹始終，切忌虎頭蛇尾。', '做事情要貫徹始終，切忌虎頭蛇尾。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"49"}'::jsonb)
  ,('active', '空中樓閣', 'ㄎㄨㄥ ㄓㄨㄥ ㄌㄡˊ ㄍㄜˊ', '成語', 3, '空中顯現的樓臺觀閣。※語或本唐．宋之問〈遊法華寺〉詩。後用「空中樓閣」來比喻思想明澈通達。或比喻虛構的事物或不切實際的幻想。', '空中顯現的樓臺觀閣。※語或本唐．宋之問〈遊法華寺〉詩。後用「空中樓閣」來比喻思想明澈通達。或比喻虛構的事物或不切實際的幻想。 △「海市蜃樓」', '比喻虛構的事物或不切實際的幻想。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你提出來的構想就像空中樓閣，不切實際。', '你提出來的構想就像空中樓閣，不切實際。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"50"}'::jsonb)
  ,('active', '天經地義', 'ㄊㄧㄢ ㄐㄧㄥ ㄉㄧˋ ㄧˋ', '成語', 3, '天地間原本如此而不容改變的道理。語本《左傳．昭公二十五年》。', '天地間原本如此而不容改變的道理。語本《左傳．昭公二十五年》。 △「理所當然」', '天地間原本如此而不容改變的道理。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '要有收穫就得耕耘，這是天經地義的事。', '要有收穫就得耕耘，這是天經地義的事。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"51"}'::jsonb)
  ,('active', '心猿意馬', 'ㄒㄧㄣ ㄩㄢˊ ㄧˋ ㄇㄚˇ', '成語', 3, '心思如猿猴不定地跳躍、快馬四處地奔馳而難以控制。比喻心思不專注集中。語本《參同契．卷上．中篇》漢．徐景休箋註。後亦用於比喻心意反覆不定。', '心思如猿猴不定地跳躍、快馬四處地奔馳而難以控制。比喻心思不專注集中。語本《參同契．卷上．中篇》漢．徐景休箋註。後亦用於比喻心意反覆不定。 △「心不在焉」、「見異思遷」', '心意反覆不定。＆心思不專注集中。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '做事要專心，不可心猿意馬，魂不守舍。', '做事要專心，不可心猿意馬，魂不守舍。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"52"}'::jsonb)
  ,('active', '群策群力', 'ㄑㄩㄣˊ ㄘㄜˋ ㄑㄩㄣˊ ㄌㄧˋ', '成語', 3, '聚合眾人的智慧和能力。語本漢．揚雄《法言．重黎》。', '聚合眾人的智慧和能力。語本漢．揚雄《法言．重黎》。 △「同心同德」、「同心協力」、「戮力同心」', '聚合眾人的智慧和能力。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '參加這個遊戲，大家要群策群力才能過關。', '參加這個遊戲，大家要群策群力才能過關。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"53"}'::jsonb)
  ,('active', '有備無患', 'ㄧㄡˇ ㄅㄟˋ ㄨˊ ㄏㄨㄢˋ', '成語', 3, '事先有準備，即可免除後患。＃語出《書經．說命中》。', '事先有準備，即可免除後患。＃語出《書經．說命中》。 △「曲突徙薪」', '事先有準備，即可免除後患。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你出門時得把氣喘藥帶著，好有備無患。', '你出門時得把氣喘藥帶著，好有備無患。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"54"}'::jsonb)
  ,('active', '裹足不前', 'ㄍㄨㄛˇ ㄗㄨˊ ㄅㄨˋ ㄑㄧㄢˊ', '成語', 3, '包纏腳部，不往前行。形容有所顧忌，而停止腳步，不敢向前。＃語本《戰國策．秦策三》。', '包纏腳部，不往前行。形容有所顧忌，而停止腳步，不敢向前。＃語本《戰國策．秦策三》。 △「畏縮不前」', '形容有所顧忌，而停止腳步，不敢向前。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '敵人都已經衝過來了，我們還能裹足不前嗎？', '敵人都已經衝過來了，我們還能裹足不前嗎？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"55"}'::jsonb)
  ,('active', '戰戰兢兢', 'ㄓㄢˋ ㄓㄢˋ ㄐㄧㄥ ㄐㄧㄥ', '成語', 3, '戰，害怕而發抖，通「顫」。兢兢，小心謹慎的樣子。「戰戰兢兢」形容戒慎恐懼的樣子。語出《詩經．小雅．小旻》。', '戰，害怕而發抖，通「顫」。兢兢，小心謹慎的樣子。「戰戰兢兢」形容戒慎恐懼的樣子。語出《詩經．小雅．小旻》。 △「如臨深淵」、「如履薄冰」、「誠惶誠恐」、「暴虎馮河」、「臨深履薄」', '形容戒慎恐懼的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '第一次上臺講課時，自己真是戰戰兢兢，深怕說錯話。', '第一次上臺講課時，自己真是戰戰兢兢，深怕說錯話。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"56"}'::jsonb)
  ,('active', '借花獻佛', 'ㄐㄧㄝˋ ㄏㄨㄚ ㄒㄧㄢˋ ㄈㄛˊ', '成語', 3, '借用別人的花供養佛。典出《過去現在因果經》卷一。後用「借花獻佛」比喻借用他人的東西來作人情。', '借用別人的花供養佛。典出《過去現在因果經》卷一。後用「借花獻佛」比喻借用他人的東西來作人情。 △「慷他人之慨」', '比喻借用他人的東西來作人情。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我就用這杯現成的酒，借花獻佛，祝你步步高升！', '我就用這杯現成的酒，借花獻佛，祝你步步高升！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"57"}'::jsonb)
  ,('active', '故步自封', 'ㄍㄨˋ ㄅㄨˋ ㄗˋ ㄈㄥ', '成語', 3, '「故步」，舊的步法。比喻舊方法。語出《漢書．卷一○○．敘傳上》。「自封」，自我限制。語出晉．庾闡〈斷酒戒〉。「故步自封」指安於現狀，不求進取。', '「故步」，舊的步法。比喻舊方法。語出《漢書．卷一○○．敘傳上》。「自封」，自我限制。語出晉．庾闡〈斷酒戒〉。「故步自封」指安於現狀，不求進取。 △「墨守成規」', '安於現狀，不求進取。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我們要不斷進步，不能故步自封。', '我們要不斷進步，不能故步自封。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"58"}'::jsonb)
  ,('active', '笑裡藏刀', 'ㄒㄧㄠˋ ㄌㄧˇ ㄘㄤˊ ㄉㄠ', '成語', 3, '笑容的後面藏著刀。形容人外貌和善可親，內心卻陰險狠毒。＃語本《舊唐書．卷八二．李義府列傳》。', '笑容的後面藏著刀。形容人外貌和善可親，內心卻陰險狠毒。＃語本《舊唐書．卷八二．李義府列傳》。 △「口蜜腹劍」', '比喻人外貌和善可親，內心卻陰險狠毒。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他是個笑裡藏刀的人，得小心應付。', '他是個笑裡藏刀的人，得小心應付。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"59"}'::jsonb)
  ,('active', '水到渠成', 'ㄕㄨㄟˇ ㄉㄠˋ ㄑㄩˊ ㄔㄥˊ', '成語', 3, '水流過處自然成渠。比喻事情自然發展，結果自成。※＃語或出宋．蘇軾〈答秦太虛書〉其四。後亦用「水到渠成」比喻事情條件完備則自然成功，不須強求。', '水流過處自然成渠。比喻事情自然發展，結果自成。※＃語或出宋．蘇軾〈答秦太虛書〉其四。後亦用「水到渠成」比喻事情條件完備則自然成功，不須強求。 △「水到魚行」、「瓜熟蒂落」', '比喻事情自然發展，結果自成。＆比喻事情條件完備則自然成功，不須強求。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他倆相戀多年，如今水到渠成，步上紅毯。', '他倆相戀多年，如今水到渠成，步上紅毯。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"60"}'::jsonb)
  ,('active', '芒刺在背', 'ㄇㄤˊ ㄘˋ ㄗㄞˋ ㄅㄟˋ', '成語', 3, '像是有許多細小的芒刺沾在背上。比喻因畏忌而極度不安。語出《漢書．卷六八．霍光金日磾傳．霍光》。', '像是有許多細小的芒刺沾在背上。比喻因畏忌而極度不安。語出《漢書．卷六八．霍光金日磾傳．霍光》。 △「如坐針氈」', '比喻因畏忌而極度不安。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '父親威嚴的神情，著實讓我感到芒刺在背般惶恐不安。', '父親威嚴的神情，著實讓我感到芒刺在背般惶恐不安。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"61"}'::jsonb)
  ,('active', '開門見山', 'ㄎㄞ ㄇㄣˊ ㄐㄧㄢˋ ㄕㄢ', '成語', 3, '一開門就見到對門的山巒。比喻說話或寫文章直接了當，一開始就進入正題。※語或出宋．嚴羽《滄浪詩話．詩評》。', '一開門就見到對門的山巒。比喻說話或寫文章直接了當，一開始就進入正題。※語或出宋．嚴羽《滄浪詩話．詩評》。 △「開宗明義」', '一開門就見到山巒。＆比喻說話或寫文章直截了當，一開始就進入正題。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這所房屋，開門見山，開牖見水，環境優美。', '這所房屋，開門見山，開牖見水，環境優美。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"62"}'::jsonb)
  ,('active', '土崩瓦解', 'ㄊㄨˇ ㄅㄥ ㄨㄚˇ ㄐㄧㄝˇ', '成語', 3, '土石崩塌、磚瓦破碎。比喻人民的反抗，及政權內部的爭鬥。語本《史記．卷一一二．主父偃列傳》。後亦用「土崩瓦解」來比喻澈底潰敗，不可收拾。', '土石崩塌、磚瓦破碎。比喻人民的反抗，及政權內部的爭鬥。語本《史記．卷一一二．主父偃列傳》。後亦用「土崩瓦解」來比喻澈底潰敗，不可收拾。 △「分崩離析」', '形容土石崩塌、磚瓦破碎的情景。＆比喻澈底潰敗，不可收拾。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '可怕的土石流讓許多屋舍土崩瓦解。', '可怕的土石流讓許多屋舍土崩瓦解。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"63"}'::jsonb)
  ,('active', '東施效顰', 'ㄉㄨㄥ ㄕ ㄒㄧㄠˋ ㄆㄧㄣˊ', '成語', 3, '春秋越國醜女東施模仿美女西施捧心皺眉，然卻更見其醜。比喻盲目胡亂地模仿他人，結果卻適得其反。典出《莊子．天運》。', '春秋越國醜女東施模仿美女西施捧心皺眉，然卻更見其醜。比喻盲目胡亂地模仿他人，結果卻適得其反。典出《莊子．天運》。 △「邯鄲學步」', '比喻盲目胡亂地模仿他人，結果卻適得其反。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '每個人自有特質，何必如東施效顰般胡亂模仿？', '每個人自有特質，何必如東施效顰般胡亂模仿？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"64"}'::jsonb)
  ,('active', '從善如流', 'ㄘㄨㄥˊ ㄕㄢˋ ㄖㄨˊ ㄌㄧㄡˊ', '成語', 3, '聽從好的意見，就像流水般的自然順暢。比喻樂於接受別人好的意見。◎語出《左傳．成公八年》。', '聽從好的意見，就像流水般的自然順暢。比喻樂於接受別人好的意見。◎語出《左傳．成公八年》。 △「從誨如流」、「從諫如流」', '比喻樂於接受別人好的意見。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他能從善如流，就是他所以成功的原因。', '他能從善如流，就是他所以成功的原因。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"65"}'::jsonb)
  ,('active', '袖手旁觀', 'ㄒㄧㄡˋ ㄕㄡˇ ㄆㄤˊ ㄍㄨㄢ', '成語', 3, '把手縮在袖子裡，在一旁觀看。形容置身事外，不予過問。語本唐．韓愈〈祭柳子厚文〉。', '把手縮在袖子裡，在一旁觀看。形容置身事外，不予過問。語本唐．韓愈〈祭柳子厚文〉。 △「冷眼旁觀」', '形容置身事外，不予過問。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這是他們的家務事，別人只能袖手旁觀。', '這是他們的家務事，別人只能袖手旁觀。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"66"}'::jsonb)
  ,('active', '因勢利導', 'ㄧㄣ ㄕˋ ㄌㄧˋ ㄉㄠˇ', '成語', 3, '順著事物發展的趨勢，朝有利的方向引導。語本《史記．卷六五．孫子吳起傳．孫子》。', '順著事物發展的趨勢，朝有利的方向引導。語本《史記．卷六五．孫子吳起傳．孫子》。 △「順水推舟」', '順著事物發展的趨勢，朝有利的方向引導。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '大禹治水成功就是了解水文，因勢利導。', '大禹治水成功就是了解水文，因勢利導。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"67"}'::jsonb)
  ,('active', '畏首畏尾', 'ㄨㄟˋ ㄕㄡˇ ㄨㄟˋ ㄨㄟˇ', '成語', 3, '前也畏懼，後也畏懼。語出《左傳．文公十七年》。後用「畏首畏尾」形容疑慮顧忌，膽小怕事。', '前也畏懼，後也畏懼。語出《左傳．文公十七年》。後用「畏首畏尾」形容疑慮顧忌，膽小怕事。 △「左顧右盼」、「鹿死不擇音」、「鋌而走險」', '形容疑慮顧忌，膽小怕事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他遇事畏首畏尾，難堪大任。', '他遇事畏首畏尾，難堪大任。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"68"}'::jsonb)
  ,('active', '名不虛傳', 'ㄇㄧㄥˊ ㄅㄨˋ ㄒㄩ ㄔㄨㄢˊ', '成語', 3, '名聲與實際相符，而非徒有虛名。※◎語或本《史記．卷七五．孟嘗君列傳》。', '名聲與實際相符，而非徒有虛名。※◎語或本《史記．卷七五．孟嘗君列傳》。 △「名副其實」', '名聲與實際相符，而非徒有虛名。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '故宮博物院果真是名不虛傳的文化寶庫。', '故宮博物院果真是名不虛傳的文化寶庫。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"69"}'::jsonb)
  ,('active', '喪心病狂', 'ㄙㄤˋ ㄒㄧㄣ ㄅㄧㄥˋ ㄎㄨㄤˊ', '成語', 3, '「喪心」，失掉本心。語出《左傳．昭公二十五年》。「病狂」，瘋狂的病症。語出《漢書．卷七三．韋賢傳》。「喪心病狂」指喪失理性，舉止荒謬、反常。亦用來形容人殘忍可惡到了極點。', '「喪心」，失掉本心。語出《左傳．昭公二十五年》。「病狂」，瘋狂的病症。語出《漢書．卷七三．韋賢傳》。「喪心病狂」指喪失理性，舉止荒謬、反常。亦用來形容人殘忍可惡到了極點。 △「喪盡天良」', '形容人殘忍可惡到了極點。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種喪心病狂的匪徒，天理難容。', '這種喪心病狂的匪徒，天理難容。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"70"}'::jsonb)
  ,('active', '見異思遷', 'ㄐㄧㄢˋ ㄧˋ ㄙ ㄑㄧㄢ', '成語', 3, '見到別的事物就改變心意，比喻意志不堅定。＃語本《管子．小匡》。', '見到別的事物就改變心意，比喻意志不堅定。＃語本《管子．小匡》。 △「心猿意馬」', '比喻意志不堅定。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '一個人不能有見異思遷的念頭，志向才能堅定。', '一個人不能有見異思遷的念頭，志向才能堅定。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"71"}'::jsonb)
  ,('active', '明察秋毫', 'ㄇㄧㄥˊ ㄔㄚˊ ㄑㄧㄡ ㄏㄠˊ', '成語', 3, '目光敏銳，可看見秋天鳥獸新長的毫毛。＃語本《纏子》。後用「明察秋毫」比喻洞察一切，能看到極細微的地方。', '目光敏銳，可看見秋天鳥獸新長的毫毛。＃語本《纏子》。後用「明察秋毫」比喻洞察一切，能看到極細微的地方。 △「洞若觀火」', '比喻人能洞察一切，看到極細微的地方。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '包公辦案明察秋毫，宵小歹徒無所遁形。', '包公辦案明察秋毫，宵小歹徒無所遁形。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"72"}'::jsonb)
  ,('active', '作威作福', 'ㄗㄨㄛˋ ㄨㄟ ㄗㄨㄛˋ ㄈㄨˊ', '成語', 3, '君主獨攬權勢，專行賞罰。語本《書經．洪範》。後用「作威作福」指仗著權勢欺壓別人。', '君主獨攬權勢，專行賞罰。語本《書經．洪範》。後用「作威作福」指仗著權勢欺壓別人。 △「橫行霸道」', '仗著權勢欺壓別人。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這個作威作福的惡賊不會有好下場！', '這個作威作福的惡賊不會有好下場！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"73"}'::jsonb)
  ,('active', '兩袖清風', 'ㄌㄧㄤˇ ㄒㄧㄡˋ ㄑㄧㄥ ㄈㄥ', '成語', 3, '（一）形容喝茶或飲酒後清爽舒暢的感覺。※語或出元．高文秀《遇上皇》第一折。', '（一）形容喝茶或飲酒後清爽舒暢的感覺。※語或出元．高文秀《遇上皇》第一折。 △「兩腋清風」 （二）形容瀟灑飄逸、超脫凡俗的樣子。※語或出元．陳基〈次韻吳江道中〉詩。 （三）除兩袖之清風外，身上別無所有。形容作官廉潔，毫無貪贓枉法之事。＃語本明．田汝成《西湖遊覽志餘．卷八．賢達高風》。 △「囊空如洗」、「兩腋清風」', '形容瀟灑飄逸、超脫凡俗的樣子。＆形容做官廉潔，毫無貪贓枉法之事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他當了一輩子老師，有的就是「桃李春風」和「兩袖清風」這兩種風了。', '他當了一輩子老師，有的就是「桃李春風」和「兩袖清風」這兩種風了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"74"}'::jsonb)
  ,('active', '明目張膽', 'ㄇㄧㄥˊ ㄇㄨˋ ㄓㄤ ㄉㄢˇ', '成語', 3, '張大眼，壯著膽。形容有膽識，無所畏懼。＃語本《史記．卷八九．張耳陳餘列傳》。後用「明目張膽」比喻肆無忌憚地公然做壞事。', '張大眼，壯著膽。形容有膽識，無所畏懼。＃語本《史記．卷八九．張耳陳餘列傳》。後用「明目張膽」比喻肆無忌憚地公然做壞事。 △「明火執仗」', '比喻肆無忌憚地公然做壞事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '考試時，他竟然明目張膽作弊，一點羞恥心都沒有。', '考試時，他竟然明目張膽作弊，一點羞恥心都沒有。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"75"}'::jsonb)
  ,('active', '肝膽相照', 'ㄍㄢ ㄉㄢˇ ㄒㄧㄤ ㄓㄠˋ', '成語', 3, '以肝膽互相照見。比喻赤忱相處。＃語本《史記．卷九二．淮陰侯列傳》。', '以肝膽互相照見。比喻赤忱相處。＃語本《史記．卷九二．淮陰侯列傳》。 △「肝膽照人」、「披肝瀝膽」', '比喻赤忱相處。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他是我肝膽相照的至交，我絕對信得過。', '他是我肝膽相照的至交，我絕對信得過。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"76"}'::jsonb)
  ,('active', '民不聊生', 'ㄇㄧㄣˊ ㄅㄨˋ ㄌㄧㄠˊ ㄕㄥ', '成語', 3, '聊生，賴以維生。「民不聊生」指人民無法生活下去。形容百姓生活非常困苦。＃語本《戰國策．秦策四》。', '聊生，賴以維生。「民不聊生」指人民無法生活下去。形容百姓生活非常困苦。＃語本《戰國策．秦策四》。 △「生靈塗炭」', '形容百姓生活非常困苦。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '君子當道，家給人足；小人當道，民不聊生。', '君子當道，家給人足；小人當道，民不聊生。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"77"}'::jsonb)
  ,('active', '明哲保身', 'ㄇㄧㄥˊ ㄓㄜˊ ㄅㄠˇ ㄕㄣ', '成語', 3, '明達事理、洞見時勢的人，不參與會帶給自己危險的事。語本《詩經．大雅．烝民》。後亦用「明哲保身」指為了個人得失而喪失原則的庸俗處世態度。', '明達事理、洞見時勢的人，不參與會帶給自己危險的事。語本《詩經．大雅．烝民》。後亦用「明哲保身」指為了個人得失而喪失原則的庸俗處世態度。 △「獨善其身」', '明達事理、洞見時勢的人，不參與會帶給自己危險的事。＆為了個人得失而喪失原則的庸俗處世態度。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '事情發生後，大家才對他先知卓見、明哲保身的智慧佩服不已。', '事情發生後，大家才對他先知卓見、明哲保身的智慧佩服不已。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"78"}'::jsonb)
  ,('active', '妄自菲薄', 'ㄨㄤˋ ㄗˋ ㄈㄟˇ ㄅㄛˊ', '成語', 3, '隨意看輕自己，不知自重。＃語出三國蜀．諸葛亮〈出師表〉。', '隨意看輕自己，不知自重。＃語出三國蜀．諸葛亮〈出師表〉。 △「自暴自棄」', '隨意看輕自己，不知自重。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '未戰而降，未免太妄自菲薄了吧！', '未戰而降，未免太妄自菲薄了吧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"79"}'::jsonb)
  ,('active', '泥牛入海', 'ㄋㄧˊ ㄋㄧㄡˊ ㄖㄨˋ ㄏㄞˇ', '成語', 3, '泥塑的牛掉入海中。比喻人種種互相矛盾的思慮被解開。＃語本《祖堂集．卷六．洞山和尚》。後用「泥牛入海」比喻一去不復返。', '泥塑的牛掉入海中。比喻人種種互相矛盾的思慮被解開。＃語本《祖堂集．卷六．洞山和尚》。後用「泥牛入海」比喻一去不復返。 △「杳如黃鶴」', '比喻一去不復返。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '老王退休後，就像泥牛入海般消失了。', '老王退休後，就像泥牛入海般消失了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"80"}'::jsonb)
  ,('active', '休戚相關', 'ㄒㄧㄡ ㄑㄧ ㄒㄧㄤ ㄍㄨㄢ', '成語', 3, '彼此歡樂憂愁、幸福禍患，互相關聯。語本《國語．周語下》。後用「休戚相關」形容彼此間的關係密切，利害一致。', '彼此歡樂憂愁、幸福禍患，互相關聯。語本《國語．周語下》。後用「休戚相關」形容彼此間的關係密切，利害一致。 △「休戚與共」', '形容彼此間的關係密切，利害一致。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我們兩家休戚相關，榮辱與共，難分彼此。', '我們兩家休戚相關，榮辱與共，難分彼此。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"81"}'::jsonb)
  ,('active', '重整旗鼓', 'ㄔㄨㄥˊ ㄓㄥˇ ㄑㄧˊ ㄍㄨˇ', '成語', 3, '重新整頓發號施令的旗幟和戰鼓。比喻失敗後積聚力量，重新行動。※語或本《圓悟佛果禪師語錄》卷一七。', '重新整頓發號施令的旗幟和戰鼓。比喻失敗後積聚力量，重新行動。※語或本《圓悟佛果禪師語錄》卷一七。 △「另起爐灶」', '比喻失敗後積聚力量，重新行動。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '敵人正退到陣線後方去重整旗鼓，準備再次發動攻擊。', '敵人正退到陣線後方去重整旗鼓，準備再次發動攻擊。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"82"}'::jsonb)
  ,('active', '脣亡齒寒', 'ㄔㄨㄣˊ ㄨㄤˊ ㄔˇ ㄏㄢˊ', '成語', 3, '沒有了嘴脣，牙齒就會感到寒冷。比喻關係密切，利害相關。◎語出《左傳．僖公五年》。', '沒有了嘴脣，牙齒就會感到寒冷。比喻關係密切，利害相關。◎語出《左傳．僖公五年》。 △「脣齒相依」、「輔車相依」', '比喻關係密切，利害相關。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '依戰略形勢來看，這兩國有脣亡齒寒的利害關係。', '依戰略形勢來看，這兩國有脣亡齒寒的利害關係。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"83"}'::jsonb)
  ,('active', '文過飾非', 'ㄨㄣˋ ㄍㄨㄛˋ ㄕˋ ㄈㄟ', '成語', 3, '「文過」，掩飾過失。語本《論語．子張》。「飾非」，遮掩過錯。語出《莊子．盜跖》。「文過飾非」指掩飾過失、錯誤。', '「文過」，掩飾過失。語本《論語．子張》。「飾非」，遮掩過錯。語出《莊子．盜跖》。「文過飾非」指掩飾過失、錯誤。 △「諱疾忌醫」', '掩飾過失、錯誤。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '老愛文過飾非的人，漸漸會失掉真實自我。', '老愛文過飾非的人，漸漸會失掉真實自我。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"84"}'::jsonb)
  ,('active', '別出心裁', 'ㄅㄧㄝˊ ㄔㄨ ㄒㄧㄣ ㄘㄞˊ', '成語', 3, '「別出心裁」之「心」，典源作「新」。心裁，心中的設計謀畫。「別出心裁」，形容獨出巧思，不同流俗。※語或本明．李贄〈忠義水滸傳全書發凡〉。', '「別出心裁」之「心」，典源作「新」。心裁，心中的設計謀畫。「別出心裁」，形容獨出巧思，不同流俗。※語或本明．李贄〈忠義水滸傳全書發凡〉。 △「自出機杼」、「別出新意」', '獨出巧思，不同流俗。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這支電視廣告的製作的確別出心裁，十分引人注目。', '這支電視廣告的製作的確別出心裁，十分引人注目。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"85"}'::jsonb)
  ,('active', '大公無私', 'ㄉㄚˋ ㄍㄨㄥ ㄨˊ ㄙ', '成語', 3, '謂秉公處理，毫無偏私。語本《管子．形勢解》。', '謂秉公處理，毫無偏私。語本《管子．形勢解》。 △「鐵面無私」、「鐵面御史」', '秉公處理，毫無偏私。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這樣的判決大公無私，可令大家都信服。', '這樣的判決大公無私，可令大家都信服。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"86"}'::jsonb)
  ,('active', '落井下石', 'ㄌㄨㄛˋ ㄐㄧㄥˇ ㄒㄧㄚˋ ㄕˊ', '成語', 3, '本指別人掉入陷阱或井中，不但不相救，反而向他投擲石塊。比喻乘人危難時，加以陷害。語本唐．韓愈〈柳子厚墓誌銘〉。', '本指別人掉入陷阱或井中，不但不相救，反而向他投擲石塊。比喻乘人危難時，加以陷害。語本唐．韓愈〈柳子厚墓誌銘〉。 △「乘人之危」', '比喻乘人危難時，加以陷害。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種落井下石的勾當非君子所當為。', '這種落井下石的勾當非君子所當為。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"87"}'::jsonb)
  ,('active', '臨渴掘井', 'ㄌㄧㄣˊ ㄎㄜˇ ㄐㄩㄝˊ ㄐㄧㄥˇ', '成語', 3, '等到口渴時才挖井取水。比喻事到臨頭才著手準備，為時已晚。＃語本《黃帝內經素問．卷一．四氣調神大論》。', '等到口渴時才挖井取水。比喻事到臨頭才著手準備，為時已晚。＃語本《黃帝內經素問．卷一．四氣調神大論》。 △「臨陣磨槍」', '比喻事到臨頭才著手準備，為時已晚，無濟於事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種臨渴掘井的作法，怎麼能周全呢？', '這種臨渴掘井的作法，怎麼能周全呢？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"88"}'::jsonb)
  ,('active', '八面玲瓏', 'ㄅㄚ ㄇㄧㄢˋ ㄌㄧㄥˊ ㄌㄨㄥˊ', '成語', 3, '形容屋子四面八方敞亮通明。語本唐．盧綸〈賦得彭祖樓送楊宗德歸徐州幕〉詩。後用「八面玲瓏」形容人言行手段，十分巧妙，處世圓融。', '形容屋子四面八方敞亮通明。語本唐．盧綸〈賦得彭祖樓送楊宗德歸徐州幕〉詩。後用「八面玲瓏」形容人言行手段，十分巧妙，處世圓融。 △「面面俱到」', '形容屋子四面八方敞亮通明。＆形容人言行手段，十分巧妙，處世圓融。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這個樓閣設計最特殊的地方就在於：四方通透，八面玲瓏。', '這個樓閣設計最特殊的地方就在於：四方通透，八面玲瓏。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"89"}'::jsonb)
  ,('active', '一揮而就', 'ㄧ ㄏㄨㄟ ㄦˊ ㄐㄧㄡˋ', '成語', 3, '一動筆，文章就寫成了。形容才思敏捷，落筆成章。語本《摭言》。後用「一揮而就」形容在書畫作文方面的敏捷高超。', '一動筆，文章就寫成了。形容才思敏捷，落筆成章。語本《摭言》。後用「一揮而就」形容在書畫作文方面的敏捷高超。 △「一氣呵成」、「一揮立就」、「下筆成章」、「援筆立成」', '形容在書畫作文方面的敏捷高超。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '寫幾個字有何困難？待我一揮而就！', '寫幾個字有何困難？待我一揮而就！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"90"}'::jsonb)
  ,('active', '一意孤行', 'ㄧ ㄧˋ ㄍㄨ ㄒㄧㄥˊ', '成語', 3, '謝絕一切請託，按照己意獨立處理公事。語本《史記．卷一二二．酷吏列傳．張湯》。後用「一意孤行」形容人固執己見，獨斷獨行。', '謝絕一切請託，按照己意獨立處理公事。語本《史記．卷一二二．酷吏列傳．張湯》。後用「一意孤行」形容人固執己見，獨斷獨行。 △「我行我素」', '形容人固執己見，獨斷獨行。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這種一意孤行的作風，遲早會害慘自己。', '他這種一意孤行的作風，遲早會害慘自己。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"91"}'::jsonb)
  ,('active', '汗牛充棟', 'ㄏㄢˋ ㄋㄧㄡˊ ㄔㄨㄥ ㄉㄨㄥˋ', '成語', 3, '汗牛，指運送書籍時，以牛負載，累得出汗。充棟，指書籍繁多，堆滿整幢房屋。「汗牛充棟」形容書籍極多。語本唐．柳宗元〈唐故給事中皇太子侍讀陸文通先生墓表〉。', '汗牛，指運送書籍時，以牛負載，累得出汗。充棟，指書籍繁多，堆滿整幢房屋。「汗牛充棟」形容書籍極多。語本唐．柳宗元〈唐故給事中皇太子侍讀陸文通先生墓表〉。 △「車載斗量」', '形容書籍極多。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你的藏書這麼多，可說是汗牛充棟了。', '你的藏書這麼多，可說是汗牛充棟了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"92"}'::jsonb)
  ,('active', '仰人鼻息', 'ㄧㄤˇ ㄖㄣˊ ㄅㄧˊ ㄒㄧˊ', '成語', 3, '仰賴別人鼻子裡呼出的氣息而生存。比喻依靠他人生活。＃語本《後漢書．卷七四上．袁紹劉表列傳．袁紹》。後用「仰人鼻息」比喻看別人的臉色行事，不能自主。', '仰賴別人鼻子裡呼出的氣息而生存。比喻依靠他人生活。＃語本《後漢書．卷七四上．袁紹劉表列傳．袁紹》。後用「仰人鼻息」比喻看別人的臉色行事，不能自主。 △「寄人籬下」', '比喻依靠他人生活。＆比喻看別人的臉色行事，不能自主。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '人要自食其力，總不能一輩子仰人鼻息度日吧。', '人要自食其力，總不能一輩子仰人鼻息度日吧。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"93"}'::jsonb)
  ,('active', '乳臭未乾', 'ㄖㄨˇ ㄒㄧㄡˋ ㄨㄟˋ ㄍㄢ', '成語', 3, '嘴裡還有奶腥味。譏諷人年紀輕，沒有經驗與能力。語本《漢書．卷一．高帝紀上》。', '嘴裡還有奶腥味。譏諷人年紀輕，沒有經驗與能力。語本《漢書．卷一．高帝紀上》。 △「羽毛未豐」', '譏諷人年紀輕，沒有經驗與能力。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他還乳臭未乾，對這件事能懂什麼？', '他還乳臭未乾，對這件事能懂什麼？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"94"}'::jsonb)
  ,('active', '開門揖盜', 'ㄎㄞ ㄇㄣˊ ㄧ ㄉㄠˋ', '成語', 3, '揖，請。「開門揖盜」比喻引進壞人，自招禍患。語出《三國志．卷四七．吳書．吳主權傳》。', '揖，請。「開門揖盜」比喻引進壞人，自招禍患。語出《三國志．卷四七．吳書．吳主權傳》。 △「引狼入室」', '比喻引進壞人，自招禍患。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種惡人你竟請來擔任要職，不是等於開門揖盜，自找麻煩嗎？', '這種惡人你竟請來擔任要職，不是等於開門揖盜，自找麻煩嗎？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"95"}'::jsonb)
  ,('active', '危如累卵', 'ㄨㄟˊ ㄖㄨˊ ㄌㄟˇ ㄌㄨㄢˇ', '成語', 3, '重疊起來的蛋，隨時有跌破的可能。比喻情況非常危險。＃語本《韓非子．十過》。', '重疊起來的蛋，隨時有跌破的可能。比喻情況非常危險。＃語本《韓非子．十過》。 △「千鈞一髮」', '比喻情況非常危險。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '國事已危如累卵，有志青年應奮起救國！', '國事已危如累卵，有志青年應奮起救國！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"96"}'::jsonb)
  ,('active', '得意忘形', 'ㄉㄜˊ ㄧˋ ㄨㄤˋ ㄒㄧㄥˊ', '成語', 3, '（一）形，形體。「得意忘形」指因心意志趣獲得滿足而物我兩忘。語本《晉書．卷四九．阮籍列傳》。形容人高興過頭，舉止失去常態。', '（一）形，形體。「得意忘形」指因心意志趣獲得滿足而物我兩忘。語本《晉書．卷四九．阮籍列傳》。形容人高興過頭，舉止失去常態。 △「得意洋洋」 （二）形，形式。「得意忘形」指文學藝術創作上，取其精神而捨其形式。語本宋．歐陽修〈李邕書〉。', '形容人高興過頭，舉止失去常態。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他才升了一個小組長，就得意忘形到這副德性！', '他才升了一個小組長，就得意忘形到這副德性！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"97"}'::jsonb)
  ,('active', '三令五申', 'ㄙㄢ ㄌㄧㄥˋ ㄨˇ ㄕㄣ', '成語', 3, '再三命令告誡。＃語出《史記．卷六五．孫子吳起列傳．孫武》。', '再三命令告誡。＃語出《史記．卷六五．孫子吳起列傳．孫武》。 △「耳提面命」', '再三命令告誡。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '學校三令五申，不准學生抽菸。', '學校三令五申，不准學生抽菸。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"98"}'::jsonb)
  ,('active', '短兵相接', 'ㄉㄨㄢˇ ㄅㄧㄥ ㄒㄧㄤ ㄐㄧㄝ', '成語', 3, '以短小的刀、劍等武器交手搏鬥。語出戰國楚．屈原〈九歌．國殤〉。後用「短兵相接」形容近距離激烈地搏打、爭鬥。', '以短小的刀、劍等武器交手搏鬥。語出戰國楚．屈原〈九歌．國殤〉。後用「短兵相接」形容近距離激烈地搏打、爭鬥。 △「針鋒相對」', '比喻近距離激烈地搏打、爭鬥。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '敵我兩軍在邊境相遇，短兵相接，戰況激烈。', '敵我兩軍在邊境相遇，短兵相接，戰況激烈。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"99"}'::jsonb)
  ,('active', '按部就班', 'ㄢˋ ㄅㄨˋ ㄐㄧㄡˋ ㄅㄢ', '成語', 3, '寫作文章時，依照文義、安排部次，考究詞語，組織章句。語出晉．陸機〈文賦〉。後用「按部就班」比喻做事依照一定的層次、步驟進行。', '寫作文章時，依照文義、安排部次，考究詞語，組織章句。語出晉．陸機〈文賦〉。後用「按部就班」比喻做事依照一定的層次、步驟進行。 △「按部就隊」、「循序漸進」', '比喻做事依照一定的層次、步驟進行。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這部機器只要照著指示，按部就班操作就可以順利完成工作。', '這部機器只要照著指示，按部就班操作就可以順利完成工作。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"100"}'::jsonb)
  ,('active', '錦上添花', 'ㄐㄧㄣˇ ㄕㄤˋ ㄊㄧㄢ ㄏㄨㄚ', '成語', 3, '錦，彩飾的絲織品。「錦上添花」指在有彩色花紋的絲織品上再繡上花朵。比喻美上加美，喜上加喜。※＃語或出宋．黃庭堅〈了了菴頌〉。後亦用「錦上添花」形容花樣繁複、精采。', '錦，彩飾的絲織品。「錦上添花」指在有彩色花紋的絲織品上再繡上花朵。比喻美上加美，喜上加喜。※＃語或出宋．黃庭堅〈了了菴頌〉。後亦用「錦上添花」形容花樣繁複、精采。 △「如虎添翼」', '比喻美上加美，喜上加喜。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我想他的褒譽已多，用不著我去錦上添花了。', '我想他的褒譽已多，用不著我去錦上添花了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"101"}'::jsonb)
  ,('active', '得隴望蜀', 'ㄉㄜˊ ㄌㄨㄥˇ ㄨㄤˋ ㄕㄨˇ', '成語', 3, '隴，地名，位約當今甘肅省。蜀，地名，位約當今四川省。「得隴望蜀」指平定隴西之後，又想進軍蜀地。＃語本《東觀漢記．卷二三．隗囂傳》。後用「得隴望蜀」比喻貪得無厭，不知滿足。', '隴，地名，位約當今甘肅省。蜀，地名，位約當今四川省。「得隴望蜀」指平定隴西之後，又想進軍蜀地。＃語本《東觀漢記．卷二三．隗囂傳》。後用「得隴望蜀」比喻貪得無厭，不知滿足。 △「得寸進尺」', '比喻貪得無厭，不知滿足。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '許多人對名利總不知足，常常得隴望蜀，貪得無厭。', '許多人對名利總不知足，常常得隴望蜀，貪得無厭。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"102"}'::jsonb)
  ,('active', '沾沾自喜', 'ㄓㄢ ㄓㄢ ㄗˋ ㄒㄧˇ', '成語', 3, '形容自得自滿的樣子。語出《史記．卷一○七．魏其武安侯列傳》。', '形容自得自滿的樣子。語出《史記．卷一○七．魏其武安侯列傳》。 △「自鳴得意」', '形容自得自滿的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '得到高分不必沾沾自喜，謙虛才能更進步。', '得到高分不必沾沾自喜，謙虛才能更進步。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"103"}'::jsonb)
  ,('active', '毛遂自薦', 'ㄇㄠˊ ㄙㄨㄟˋ ㄗˋ ㄐㄧㄢˋ', '成語', 3, '戰國時，平原君之門下食客毛遂自薦跟隨前往楚國遊說。典出《史記．卷七六．平原君虞卿列傳．平原君》。後用「毛遂自薦」比喻自告奮勇，自我推薦。', '戰國時，平原君之門下食客毛遂自薦跟隨前往楚國遊說。典出《史記．卷七六．平原君虞卿列傳．平原君》。後用「毛遂自薦」比喻自告奮勇，自我推薦。 △「自告奮勇」、「脫穎而出」', '比喻自告奮勇，自我推薦。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我進公司是毛遂自薦的。', '我進公司是毛遂自薦的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"104"}'::jsonb)
  ,('active', '外強中乾', 'ㄨㄞˋ ㄑㄧㄤˊ ㄓㄨㄥ ㄍㄢ', '成語', 3, '「外強中乾」之「強」，典源作「彊」。「彊」同「強」。形容馬的外表看似強壯，內在卻氣力衰竭。語出《左傳．僖公十五年》。後用「外強中乾」泛喻各種事物外表看似充實強盛，實則空虛衰弱。', '「外強中乾」之「強」，典源作「彊」。「彊」同「強」。形容馬的外表看似強壯，內在卻氣力衰竭。語出《左傳．僖公十五年》。後用「外強中乾」泛喻各種事物外表看似充實強盛，實則空虛衰弱。 △「色厲內荏」', '比喻事物看似充實強盛，實則空虛衰弱。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你別以為他壯得像頭牛，其實外強中乾，常常生病。', '你別以為他壯得像頭牛，其實外強中乾，常常生病。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"105"}'::jsonb)
  ,('active', '井井有條', 'ㄐㄧㄥˇ ㄐㄧㄥˇ ㄧㄡˇ ㄊㄧㄠˊ', '成語', 3, '形容整齊有序，條理分明。語本《荀子．儒效》。', '形容整齊有序，條理分明。語本《荀子．儒效》。 △「有條不紊」', '形容整齊有序，條理分明。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他的藏書很多，而且都分門別類，整理得井井有條。', '他的藏書很多，而且都分門別類，整理得井井有條。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"106"}'::jsonb)
  ,('active', '六神無主', 'ㄌㄧㄡˋ ㄕㄣˊ ㄨˊ ㄓㄨˇ', '成語', 3, '形容心慌意亂，拿不定主意。※語或出《醒世恆言．卷二九．盧太學詩酒傲王侯》。', '形容心慌意亂，拿不定主意。※語或出《醒世恆言．卷二九．盧太學詩酒傲王侯》。 △「手足無措」、「不知所措」', '形容心慌意亂，拿不定主意。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '驚魂未定的孩子，六神無主地東張西望。', '驚魂未定的孩子，六神無主地東張西望。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"107"}'::jsonb)
  ,('active', '本末倒置', 'ㄅㄣˇ ㄇㄛˋ ㄉㄠˋ ㄓˋ', '成語', 3, '事物的先後次序顛倒。語本《禮記．大學》。後用「本末倒置」比喻不知事情的輕重緩急。', '事物的先後次序顛倒。語本《禮記．大學》。後用「本末倒置」比喻不知事情的輕重緩急。 △「輕重倒置」', '比喻不知事情的輕重緩急。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '處理事情如果本末倒置，一定越弄越糟。', '處理事情如果本末倒置，一定越弄越糟。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"108"}'::jsonb)
  ,('active', '良莠不齊', 'ㄌㄧㄤˊ ㄧㄡˋ ㄅㄨˋ ㄑㄧˊ', '成語', 3, '良，指禾苗。莠，惡草，俗稱狗尾草，葉與禾苗相似，難以辨認。「良莠不齊」，謂好壞參差，素質不一。※語或出清．紀昀《閱微草堂筆記．卷一○．如是我聞四》。', '良，指禾苗。莠，惡草，俗稱狗尾草，葉與禾苗相似，難以辨認。「良莠不齊」，謂好壞參差，素質不一。※語或出清．紀昀《閱微草堂筆記．卷一○．如是我聞四》。 △「參差不齊」', '好壞參差，素質不一。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些法拍物品的品質良莠不齊，要小心挑選。', '這些法拍物品的品質良莠不齊，要小心挑選。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"109"}'::jsonb)
  ,('active', '水乳交融', 'ㄕㄨㄟˇ ㄖㄨˇ ㄐㄧㄠ ㄖㄨㄥˊ', '成語', 3, '水與乳融合在一起。比喻彼此關係密切，契合無間。※語或本《高僧傳．三集．卷一六．唐撫州景雲寺上恆傳》。', '水與乳融合在一起。比喻彼此關係密切，契合無間。※語或本《高僧傳．三集．卷一六．唐撫州景雲寺上恆傳》。 △「如膠似漆」', '比喻彼此關係密切，契合無間。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他倆原是青梅竹馬，如今結為夫妻自是水乳交融。', '他倆原是青梅竹馬，如今結為夫妻自是水乳交融。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"110"}'::jsonb)
  ,('active', '夜以繼日', 'ㄧㄝˋ ㄧˇ ㄐㄧˋ ㄖˋ', '成語', 3, '以夜晚接續白天，晝夜都不歇息。※＃語或出《孟子．離婁下》。亦用來形容工作勤奮，日夜不停。', '以夜晚接續白天，晝夜都不歇息。※＃語或出《孟子．離婁下》。亦用來形容工作勤奮，日夜不停。 △「通宵達旦」', '形容工作勤奮，日夜不停。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為了加速施工的進度，工人們夜以繼日地趕工。', '為了加速施工的進度，工人們夜以繼日地趕工。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"111"}'::jsonb)
  ,('active', '防微杜漸', 'ㄈㄤˊ ㄨㄟˊ ㄉㄨˋ ㄐㄧㄢˋ', '成語', 3, '在錯誤或壞事萌芽的時候及時制止，杜絕它發展。※語或本漢．丁鴻〈日食上封事〉。', '在錯誤或壞事萌芽的時候及時制止，杜絕它發展。※語或本漢．丁鴻〈日食上封事〉。 △「未雨綢繆」、「防患未然」', '防範弊病要從小地方著手，並制止弊端逐漸擴大。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為政要防微杜漸，消弭亂源，才能安定政局。', '為政要防微杜漸，消弭亂源，才能安定政局。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"112"}'::jsonb)
  ,('active', '岌岌可危', 'ㄐㄧˊ ㄐㄧˊ ㄎㄜˇ ㄨㄟˊ', '成語', 3, '岌岌，危險的樣子。「岌岌可危」形容非常危險。＃語本《管子．小問》。', '岌岌，危險的樣子。「岌岌可危」形容非常危險。＃語本《管子．小問》。 △「搖搖欲墜」', '形容非常危險。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '土石流傾瀉而下，山坡上的房子顯得岌岌可危。', '土石流傾瀉而下，山坡上的房子顯得岌岌可危。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"113"}'::jsonb)
  ,('active', '沽名釣譽', 'ㄍㄨ ㄇㄧㄥˊ ㄉㄧㄠˋ ㄩˋ', '成語', 3, '「沽名」，用手段謀取名聲。※語或出《廙別傳》。「釣譽」，用手段謀取讚譽。語本《漢書．卷五八．公孫弘卜式兒寬傳．公孫弘》。「沽名釣譽」指故意做作，用手段謀取名聲和讚譽。', '「沽名」，用手段謀取名聲。※語或出《廙別傳》。「釣譽」，用手段謀取讚譽。語本《漢書．卷五八．公孫弘卜式兒寬傳．公孫弘》。「沽名釣譽」指故意做作，用手段謀取名聲和讚譽。 △「欺世盜名」', '形容故意做作，用手段謀取名聲和讚譽。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我不屑做這種沽名釣譽的事，這不是君子所當為。', '我不屑做這種沽名釣譽的事，這不是君子所當為。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"114"}'::jsonb)
  ,('active', '以訛傳訛', 'ㄧˇ ㄜˊ ㄔㄨㄢˊ ㄜˊ', '成語', 3, '訛，錯誤。「以訛傳訛」指將不正確的訊息繼續傳播下去。語本宋．王柏〈默成定武蘭亭記〉。', '訛，錯誤。「以訛傳訛」指將不正確的訊息繼續傳播下去。語本宋．王柏〈默成定武蘭亭記〉。 △「道聽塗說」', '指將不正確的訊息繼續傳播下去。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '她才訂婚，怎麼會以訛傳訛說她已經生了孩子？', '她才訂婚，怎麼會以訛傳訛說她已經生了孩子？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"115"}'::jsonb)
  ,('active', '一落千丈', 'ㄧ ㄌㄨㄛˋ ㄑㄧㄢ ㄓㄤˋ', '成語', 3, '本指琴聲由高驟然下降到很低。語出唐．韓愈〈聽穎師彈琴〉詩。後用「一落千丈」比喻成績、地位、景況、情緒或聲望等急遽下降。', '本指琴聲由高驟然下降到很低。語出唐．韓愈〈聽穎師彈琴〉詩。後用「一落千丈」比喻成績、地位、景況、情緒或聲望等急遽下降。 △「一瀉千里」', '指聲音由高驟然下降到很低。＆比喻成績、地位、景況、情緒或聲望等急遽下降。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '只聽她那嗓音，在高處溜轉後，從巔峰處一落千丈，而後又似黃鶯出谷般的一片清亮。', '只聽她那嗓音，在高處溜轉後，從巔峰處一落千丈，而後又似黃鶯出谷般的一片清亮。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"116"}'::jsonb)
  ,('active', '一針見血', 'ㄧ ㄓㄣ ㄐㄧㄢˋ ㄒㄧㄝˇ', '成語', 3, '一針刺入手指，鮮血即出。語本《晉書．卷六六．陶侃列傳》。後用「一針見血」比喻言論簡潔透澈，深中肯綮（ㄑㄧㄥˋ）。', '一針刺入手指，鮮血即出。語本《晉書．卷六六．陶侃列傳》。後用「一針見血」比喻言論簡潔透澈，深中肯綮（ㄑㄧㄥˋ）。 △「一語道破」', '比喻言論簡潔透澈，深中肯綮。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這篇文章評論當今社會問題，真是一針見血。', '這篇文章評論當今社會問題，真是一針見血。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"117"}'::jsonb)
  ,('active', '萬籟俱寂', 'ㄨㄢˋ ㄌㄞˋ ㄐㄩˋ ㄐㄧˊ', '成語', 3, '萬物無聲，一片寂靜。語本唐．常建〈題破山寺後禪院〉詩。', '萬物無聲，一片寂靜。語本唐．常建〈題破山寺後禪院〉詩。 △「鴉雀無聲」', '萬物無聲，一片寂靜。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我最愛在萬籟俱寂的深夜沉思與寫作。', '我最愛在萬籟俱寂的深夜沉思與寫作。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"118"}'::jsonb)
  ,('active', '笑容可掬', 'ㄒㄧㄠˋ ㄖㄨㄥˊ ㄎㄜˇ ㄐㄩˊ', '成語', 3, '笑容滿溢，似乎可用雙手捧取。形容笑容滿面的樣子。※語或出《三國演義》第九五回。', '笑容滿溢，似乎可用雙手捧取。形容笑容滿面的樣子。※語或出《三國演義》第九五回。 △「喜形於色」', '形容笑容滿面的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '一到會場，就看到老闆站在門口，笑容可掬。', '一到會場，就看到老闆站在門口，笑容可掬。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"119"}'::jsonb)
  ,('active', '揮金如土', 'ㄏㄨㄟ ㄐㄧㄣ ㄖㄨˊ ㄊㄨˇ', '成語', 3, '花錢就像撒土一樣。比喻極端浪費錢財。語出宋．毛滂〈祭鄭庭誨文〉。', '花錢就像撒土一樣。比喻極端浪費錢財。語出宋．毛滂〈祭鄭庭誨文〉。 △「一擲千金」', '比喻極端浪費錢財。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '像他這樣揮金如土，再多的家產也不夠他花。', '像他這樣揮金如土，再多的家產也不夠他花。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"120"}'::jsonb)
  ,('active', '嗤之以鼻', 'ㄔ ㄓ ㄧˇ ㄅㄧˊ', '成語', 3, '嗤，譏笑。「嗤之以鼻」指用鼻子哼氣譏笑某一人事物，以表示不屑、鄙視。※語或出《黃繡球》第七回。', '嗤，譏笑。「嗤之以鼻」指用鼻子哼氣譏笑某一人事物，以表示不屑、鄙視。※語或出《黃繡球》第七回。 △「不屑一顧」', '指用鼻子哼氣譏笑某一人事物以表示不屑、鄙視。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種賣友求榮的人，我當然要嗤之以鼻！', '這種賣友求榮的人，我當然要嗤之以鼻！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"121"}'::jsonb)
  ,('active', '急流勇退', 'ㄐㄧˊ ㄌㄧㄡˊ ㄩㄥˇ ㄊㄨㄟˋ', '成語', 3, '在湍急的水勢中，當機立斷，回舟退出。比喻人於得意順遂時，及時隱退。＃語出宋．邵伯溫《邵氏聞見錄》卷七。', '在湍急的水勢中，當機立斷，回舟退出。比喻人於得意順遂時，及時隱退。＃語出宋．邵伯溫《邵氏聞見錄》卷七。 △「功成身退」', '在湍急的水勢中，當機立斷，回舟退出。＆比喻人處於得意順遂時及時隱退。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '溪水突然暴漲，大家趕快急流勇退，免得發生危險。', '溪水突然暴漲，大家趕快急流勇退，免得發生危險。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"122"}'::jsonb)
  ,('active', '赴湯蹈火', 'ㄈㄨˋ ㄊㄤ ㄉㄠˋ ㄏㄨㄛˇ', '成語', 3, '甘願奔投至烈火沸水當中。比喻奮不顧身，不避艱險。※＃語本《漢書．卷四九．爰盎鼂錯傳．鼂錯》。', '甘願奔投至烈火沸水當中。比喻奮不顧身，不避艱險。※＃語本《漢書．卷四九．爰盎鼂錯傳．鼂錯》。 △「出生入死」、「赴火蹈刃」', '比喻奮不顧身，不避艱險。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '只要是您老交代的事，我赴湯蹈火，在所不辭。', '只要是您老交代的事，我赴湯蹈火，在所不辭。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"123"}'::jsonb)
  ,('active', '包藏禍心', 'ㄅㄠ ㄘㄤˊ ㄏㄨㄛˋ ㄒㄧㄣ', '成語', 3, '懷藏詭計，圖謀害人。語出《左傳．昭公元年》。', '懷藏詭計，圖謀害人。語出《左傳．昭公元年》。 △「居心叵測」', '懷藏詭計，圖謀害人。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '可惡的叛賊，竟包藏禍心，謀我江山！', '可惡的叛賊，竟包藏禍心，謀我江山！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"124"}'::jsonb)
  ,('active', '旗鼓相當', 'ㄑㄧˊ ㄍㄨˇ ㄒㄧㄤ ㄉㄤ', '成語', 3, '軍旗和戰鼓表現出的氣勢相當，形容兩方軍隊陣容、聲勢不相上下。※＃語或本《後漢書．卷一三．隗囂公孫述列傳．隗囂》。後用「旗鼓相當」比喻雙方勢均力敵。', '軍旗和戰鼓表現出的氣勢相當，形容兩方軍隊陣容、聲勢不相上下。※＃語或本《後漢書．卷一三．隗囂公孫述列傳．隗囂》。後用「旗鼓相當」比喻雙方勢均力敵。 △「旗鼓相望」、「勢均力敵」', '比喻雙方勢均力敵。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這兩隊實力旗鼓相當，這場球賽精采可期。', '這兩隊實力旗鼓相當，這場球賽精采可期。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"125"}'::jsonb)
  ,('active', '樂不可支', 'ㄌㄜˋ ㄅㄨˋ ㄎㄜˇ ㄓ', '成語', 3, '快樂到無法受得住，形容快樂到了極點。＃語出《東觀漢記．卷一五．張堪列傳》。', '快樂到無法受得住，形容快樂到了極點。＃語出《東觀漢記．卷一五．張堪列傳》。 △「喜不自勝」、「樂不可言」', '形容快樂到了極點。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '老師宣布今天小考取消，全班同學都樂不可支！', '老師宣布今天小考取消，全班同學都樂不可支！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"126"}'::jsonb)
  ,('active', '分道揚鑣', 'ㄈㄣ ㄉㄠˋ ㄧㄤˊ ㄅㄧㄠ', '成語', 3, '分道而行，形容各走各的路。＃語本《魏書．卷一四．神元平文諸帝子孫列傳．河間公齊》。後用「分道揚鑣」比喻人依其志向，各奔前程。', '分道而行，形容各走各的路。＃語本《魏書．卷一四．神元平文諸帝子孫列傳．河間公齊》。後用「分道揚鑣」比喻人依其志向，各奔前程。 △「各奔前程」', '形容各走各的路。＆比喻人依其志向，各奔前程。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '從此我跟你分道揚鑣，各走各的路。', '從此我跟你分道揚鑣，各走各的路。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"127"}'::jsonb)
  ,('active', '曇花一現', 'ㄊㄢˊ ㄏㄨㄚ ㄧ ㄒㄧㄢˋ', '成語', 3, '曇花，一種多在夜間開放，開後不久旋即凋謝的花。「曇花一現」比喻事物稀有難得。語本《妙法蓮華經．方便品》。後用「曇花一現」比喻人或事物一出現便迅速消失。', '曇花，一種多在夜間開放，開後不久旋即凋謝的花。「曇花一現」比喻事物稀有難得。語本《妙法蓮華經．方便品》。後用「曇花一現」比喻人或事物一出現便迅速消失。 △「過眼雲煙」', '人或事物一出現便迅速消失。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '眼前的一切繁華有如曇花一現，切莫流連而忘本。', '眼前的一切繁華有如曇花一現，切莫流連而忘本。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"128"}'::jsonb)
  ,('active', '目中無人', 'ㄇㄨˋ ㄓㄨㄥ ㄨˊ ㄖㄣˊ', '成語', 3, '眼中除自己外，沒有他人。形容人高傲自大，瞧不起別人。※語或出《初刻拍案驚奇》卷一三。', '眼中除自己外，沒有他人。形容人高傲自大，瞧不起別人。※語或出《初刻拍案驚奇》卷一三。 △「目空一切」、「旁若無人」', '形容人高傲自大，瞧不起別人。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種目中無人的人，不必理會他。', '這種目中無人的人，不必理會他。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"129"}'::jsonb)
  ,('active', '春風得意', 'ㄔㄨㄣ ㄈㄥ ㄉㄜˊ ㄧˋ', '成語', 3, '春風吹拂中，心情怡然自得，指登進士第後稱心如意的感受。語出唐．孟郊〈登科後〉詩。後用「春風得意」形容人因事情如願以償而心情愉悅滿足。', '春風吹拂中，心情怡然自得，指登進士第後稱心如意的感受。語出唐．孟郊〈登科後〉詩。後用「春風得意」形容人因事情如願以償而心情愉悅滿足。 △「走馬看花」、「躊躇滿志」', '指考中後稱心如意的感受。＆形容人因事情如願以償而心情愉悅滿足。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '考上第一志願後，別說他自己春風得意了，連他父母親都鎮日笑得合不攏嘴。', '考上第一志願後，別說他自己春風得意了，連他父母親都鎮日笑得合不攏嘴。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"130"}'::jsonb)
  ,('active', '難兄難弟', '（一）ㄋㄢˊ ㄒㄩㄥ ㄋㄢˊ ㄉㄧˋ（二）ㄋㄢˋ ㄒㄩㄥ ㄋㄢˋ ㄉㄧˋ', '成語', 3, '「難兄難弟」之「難」，有二讀，其意義也不同：（一）音ㄋㄢˊ，本義是做弟弟的太好，那麼做哥哥的人就「難為兄」，而做哥哥的太好，做弟弟的人就「難為弟」，是形容兄弟二人才德相當，難分高下。語本南朝宋．劉義慶《世說新語．德行》。後世多反用其義，諷刺', '「難兄難弟」之「難」，有二讀，其意義也不同：（一）音ㄋㄢˊ，本義是做弟弟的太好，那麼做哥哥的人就「難為兄」，而做哥哥的太好，做弟弟的人就「難為弟」，是形容兄弟二人才德相當，難分高下。語本南朝宋．劉義慶《世說新語．德行》。後世多反用其義，諷刺兩人同樣差勁，表現差不多。（二）音ㄋㄢˋ，形容同處困境、共同患難的朋友。 △「患難之交」', '形容兄弟二人才德相當，難分高下。（難，音ㄋㄢˊ）＆諷刺兩人同樣差勁，表現差不多。（難，音ㄋㄢˊ）＆形容同處困境、共同患難的朋友。（難，音ㄋㄢˋ）', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這兩位兄弟品學一樣好，真可說是難兄難弟。', '這兩位兄弟品學一樣好，真可說是難兄難弟。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"131"}'::jsonb)
  ,('active', '海闊天空', 'ㄏㄞˇ ㄎㄨㄛˋ ㄊㄧㄢ ㄎㄨㄥ', '成語', 3, '形容天地遼闊而無邊際。※語或本北周．庾信〈道士步虛詞〉一○首之一○。後用「海闊天空」比喻心胸開闊、心情開朗，或形容無拘無束，漫無邊際的樣子。', '形容天地遼闊而無邊際。※語或本北周．庾信〈道士步虛詞〉一○首之一○。後用「海闊天空」比喻心胸開闊、心情開朗，或形容無拘無束，漫無邊際的樣子。 △「天南地北」', '形容天地遼闊而無邊際。＆比喻心胸開闊、心情開朗＆形容無拘無束，漫無邊際的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '站在鼻頭角的燈塔上，放眼望去，真是海闊天空。', '站在鼻頭角的燈塔上，放眼望去，真是海闊天空。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"132"}'::jsonb)
  ,('active', '偷天換日', 'ㄊㄡ ㄊㄧㄢ ㄏㄨㄢˋ ㄖˋ', '成語', 3, '比喻騙局之大與技巧之妙。※語或出《群音類選．官腔類．卷一一．竊符記．如姬竊符》。', '比喻騙局之大與技巧之妙。※語或出《群音類選．官腔類．卷一一．竊符記．如姬竊符》。 △「移花接木」', '比喻騙局之大與技巧之妙。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他想用偷天換日的方法將公款中飽私囊。', '他想用偷天換日的方法將公款中飽私囊。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"133"}'::jsonb)
  ,('active', '孤芳自賞', 'ㄍㄨ ㄈㄤ ㄗˋ ㄕㄤˇ', '成語', 3, '比喻自命清高，自我欣賞。語本南朝梁．沈約〈謝齊竟陵王教撰高士傳啟〉。', '比喻自命清高，自我欣賞。語本南朝梁．沈約〈謝齊竟陵王教撰高士傳啟〉。 △「自命不凡」', '比喻自命清高，自我欣賞。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些畫都賣不出去，只好收起來孤芳自賞了。', '這些畫都賣不出去，只好收起來孤芳自賞了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"134"}'::jsonb)
  ,('active', '坐以待斃', 'ㄗㄨㄛˋ ㄧˇ ㄉㄞˋ ㄅㄧˋ', '成語', 3, '坐著等死。比喻面臨危難，不採取積極的應變措施，只坐等敗亡。 ＃語本《管子．參患》。', '坐著等死。比喻面臨危難，不採取積極的應變措施，只坐等敗亡。 ＃語本《管子．參患》。 △「束手就擒」', '比喻面臨危難，不採取積極的應變措施，只坐等敗亡。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '敵人侵略我國，我們當然要奮起抵抗，豈能坐以待斃？', '敵人侵略我國，我們當然要奮起抵抗，豈能坐以待斃？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"135"}'::jsonb)
  ,('active', '一舉兩得', 'ㄧ ㄐㄩˇ ㄌㄧㄤˇ ㄉㄜˊ', '成語', 3, '比喻做一件事，同時有兩方面的收穫。 ＃◎語本《戰國策．秦策二》。', '比喻做一件事，同時有兩方面的收穫。 ＃◎語本《戰國策．秦策二》。 △「一箭雙雕」', '比喻做一件事，同時有兩方面的收穫。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '種花既可美化環境，又可怡情養性，真是一舉兩得。', '種花既可美化環境，又可怡情養性，真是一舉兩得。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"136"}'::jsonb)
  ,('active', '守口如瓶', 'ㄕㄡˇ ㄎㄡˇ ㄖㄨˊ ㄆㄧㄥˊ', '成語', 3, '嘴像瓶口一樣封得嚴緊。語出《法苑珠林．卷四七．懲過篇．引證部》。後用「守口如瓶」比喻嚴守祕密。', '嘴像瓶口一樣封得嚴緊。語出《法苑珠林．卷四七．懲過篇．引證部》。後用「守口如瓶」比喻嚴守祕密。 △「防意如城」、「諱莫如深」', '比喻嚴守祕密。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '此事涉及國防機密，當然要守口如瓶。', '此事涉及國防機密，當然要守口如瓶。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"137"}'::jsonb)
  ,('active', '自投羅網', 'ㄗˋ ㄊㄡˊ ㄌㄨㄛˊ ㄨㄤˇ', '成語', 3, '自己投入羅網裡。比喻落入他人圈套或自取禍害。語本三國魏．曹植〈野田黃雀行〉。', '自己投入羅網裡。比喻落入他人圈套或自取禍害。語本三國魏．曹植〈野田黃雀行〉。 △「自掘墳墓」', '比喻落入他人圈套或自取禍害。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '且讓我來想個妙計，讓歹徒來自投羅網。', '且讓我來想個妙計，讓歹徒來自投羅網。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"138"}'::jsonb)
  ,('active', '人面獸心', 'ㄖㄣˊ ㄇㄧㄢˋ ㄕㄡˋ ㄒㄧㄣ', '成語', 3, '形容文化未開，不懂禮儀，表面上看起來像是人，內心卻像野獸一般。語出《漢書．卷九四．匈奴傳下》。後用「人面獸心」形容人凶狠殘暴，如野獸一般。', '形容文化未開，不懂禮儀，表面上看起來像是人，內心卻像野獸一般。語出《漢書．卷九四．匈奴傳下》。後用「人面獸心」形容人凶狠殘暴，如野獸一般。 △「衣冠禽獸」', '形容人凶狠殘暴，如野獸一般。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '怎會有人販賣自己兒女？簡直是人面獸心！', '怎會有人販賣自己兒女？簡直是人面獸心！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"139"}'::jsonb)
  ,('active', '忘恩負義', 'ㄨㄤˋ ㄣ ㄈㄨˋ ㄧˋ', '成語', 3, '受人恩惠不知報答，反而做出對不起恩人的事情。語本《漢書．卷七六．趙尹韓張兩王傳．張敞》。', '受人恩惠不知報答，反而做出對不起恩人的事情。語本《漢書．卷七六．趙尹韓張兩王傳．張敞》。 △「五日京兆」、「背信棄義」', '受人恩惠不知報答，反而做出對不起恩人的事情。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他向來有情有義，絕非忘恩負義之人。', '他向來有情有義，絕非忘恩負義之人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"140"}'::jsonb)
  ,('active', '川流不息', 'ㄔㄨㄢ ㄌㄧㄡˊ ㄅㄨˋ ㄒㄧˊ', '成語', 3, '像河川般奔流不停，比喻時光無止盡地流逝。※語或本《論語．子罕》。後用「川流不息」形容連綿不絕或往返不斷。', '像河川般奔流不停，比喻時光無止盡地流逝。※語或本《論語．子罕》。後用「川流不息」形容連綿不絕或往返不斷。 △「絡繹不絕」', '形容連綿不絕。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這條大街上，人來人往，川流不息。', '這條大街上，人來人往，川流不息。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"141"}'::jsonb)
  ,('active', '天涯海角', 'ㄊㄧㄢ ㄧㄚˊ ㄏㄞˇ ㄐㄧㄠˇ', '成語', 3, '「天涯海角」之「海」，典源作「地」。形容偏僻或相距遙遠的地方。※語或本南朝陳．徐陵〈武皇帝作相時與嶺南酋豪書〉。', '「天涯海角」之「海」，典源作「地」。形容偏僻或相距遙遠的地方。※語或本南朝陳．徐陵〈武皇帝作相時與嶺南酋豪書〉。 △「天南地北」、「天涯海際」', '形容偏僻或相距遙遠的地方。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他為了找尋失散的妻子，走遍了天涯海角。', '他為了找尋失散的妻子，走遍了天涯海角。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"142"}'::jsonb)
  ,('active', '九死一生', 'ㄐㄧㄡˇ ㄙˇ ㄧ ㄕㄥ', '成語', 3, '「九死」指歷經多次近於死亡之險境。見於戰國．楚．屈原〈離騷〉。「九死一生」形容歷經極大的危險而倖存。※語或本《六臣註文選．屈原．離騷》唐．劉良．注。後亦用「九死一生」表十死其九之意，比喻倖免於死的人很少，亦用於比喻生命跡象微弱，瀕臨死亡。', '「九死」指歷經多次近於死亡之險境。見於戰國．楚．屈原〈離騷〉。「九死一生」形容歷經極大的危險而倖存。※語或本《六臣註文選．屈原．離騷》唐．劉良．注。後亦用「九死一生」表十死其九之意，比喻倖免於死的人很少，亦用於比喻生命跡象微弱，瀕臨死亡。 △「死裡逃生」、「虎口餘生」', '形容歷經極大的危險而倖存。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '大巴士翻入河中後，他在九死一生中救了許多人。', '大巴士翻入河中後，他在九死一生中救了許多人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"143"}'::jsonb)
  ,('active', '如數家珍', 'ㄖㄨˊ ㄕㄨˇ ㄐㄧㄚ ㄓㄣ', '成語', 3, '好像計算自家所珍藏的珠寶一樣。比喻敘述事物明晰熟練。※語或本《韓詩外傳》卷一。', '好像計算自家所珍藏的珠寶一樣。比喻敘述事物明晰熟練。※語或本《韓詩外傳》卷一。 △「一五一十」', '比喻敘述事物明晰熟練。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他只要一談起電影，就滔滔不絕，如數家珍。', '他只要一談起電影，就滔滔不絕，如數家珍。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"144"}'::jsonb)
  ,('active', '情不自禁', 'ㄑㄧㄥˊ ㄅㄨˋ ㄗˋ ㄐㄧㄣ', '成語', 3, '感情激動得無法自我控制。語出南朝梁．劉遵〈七夕穿針〉詩。', '感情激動得無法自我控制。語出南朝梁．劉遵〈七夕穿針〉詩。 △「不由自主」', '感情激動得無法自我控制。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '看到國旗冉冉上升時，他情不自禁地激動起來。', '看到國旗冉冉上升時，他情不自禁地激動起來。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"145"}'::jsonb)
  ,('active', '想入非非', 'ㄒㄧㄤˇ ㄖㄨˋ ㄈㄟ ㄈㄟ', '成語', 3, '「想入非非」是從佛經中「非想非非想處」變化而來。「非想非非想處」指佛教禪修者修習至最高的境界。語本《大佛頂首楞嚴經》卷九。後來「想入非非」轉而用來形容脫離現實的想像或念頭。', '「想入非非」是從佛經中「非想非非想處」變化而來。「非想非非想處」指佛教禪修者修習至最高的境界。語本《大佛頂首楞嚴經》卷九。後來「想入非非」轉而用來形容脫離現實的想像或念頭。 △「胡思亂想」、「異想天開」', '形容脫離現實的想像或念頭。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '請用藝術的眼光欣賞這些畫作，不要想入非非。', '請用藝術的眼光欣賞這些畫作，不要想入非非。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"146"}'::jsonb)
  ,('active', '鬼鬼祟祟', 'ㄍㄨㄟˇ ㄍㄨㄟˇ ㄙㄨㄟˋ ㄙㄨㄟˋ', '成語', 3, '形容行事不光明，偷偷摸摸的樣子。※語或出《紅樓夢》第二四回。', '形容行事不光明，偷偷摸摸的樣子。※語或出《紅樓夢》第二四回。 △「鬼頭鬼腦」', '形容行事不光明，偷偷摸摸的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '扒手鬼鬼祟祟地，在公共場所偷竊財物。', '扒手鬼鬼祟祟地，在公共場所偷竊財物。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"147"}'::jsonb)
  ,('active', '置若罔聞', 'ㄓˋ ㄖㄨㄛˋ ㄨㄤˇ ㄨㄣˊ', '成語', 3, '置，放著。罔，沒有。「置若罔聞」指雖有耳聞，卻好像沒有聽到一樣不加理會。※＃語或出明．朱國幀《湧幢小品．卷九．閣臣相搆》。', '置，放著。罔，沒有。「置若罔聞」指雖有耳聞，卻好像沒有聽到一樣不加理會。※＃語或出明．朱國幀《湧幢小品．卷九．閣臣相搆》。 △「置之不理」', '雖有耳聞，卻好像沒有聽到一樣不加理會。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '今天你如果對父母的話置若罔聞，日後必將後悔！', '今天你如果對父母的話置若罔聞，日後必將後悔！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"148"}'::jsonb)
  ,('active', '捕風捉影', 'ㄅㄨˇ ㄈㄥ ㄓㄨㄛ ㄧㄥˇ', '成語', 3, '風和影子均無可捉摸，「捕風捉影」比喻所做的事或所說的話毫無根據，憑空揣測。語本《漢書．卷二五．郊祀志下》。', '風和影子均無可捉摸，「捕風捉影」比喻所做的事或所說的話毫無根據，憑空揣測。語本《漢書．卷二五．郊祀志下》。 △「無中生有」', '比喻所做的事或所說的話毫無根據，憑空揣測。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '那些傳聞只不過是捕風捉影，不必理會。', '那些傳聞只不過是捕風捉影，不必理會。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"149"}'::jsonb)
  ,('active', '義不容辭', 'ㄧˋ ㄅㄨˋ ㄖㄨㄥˊ ㄘˊ', '成語', 3, '道義上不容許推卻。語出唐．岑文本〈唐故特進尚書右僕射上柱國虞恭公溫公碑〉。', '道義上不容許推卻。語出唐．岑文本〈唐故特進尚書右僕射上柱國虞恭公溫公碑〉。 △「責無旁貸」、「義不容隱」、「當仁不讓」、「義無反顧」', '道義上不容許推卻。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這件事，我義不容辭，就讓我來協助你吧！', '這件事，我義不容辭，就讓我來協助你吧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"150"}'::jsonb)
  ,('active', '異想天開', 'ㄧˋ ㄒㄧㄤˇ ㄊㄧㄢ ㄎㄞ', '成語', 3, '不符實際、不合事理的奇特想法。※語或出清．無名氏〈都門紀變百詠〉其五七。', '不符實際、不合事理的奇特想法。※語或出清．無名氏〈都門紀變百詠〉其五七。 △「想入非非」', '不符實際、不合事理的奇特想法。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '是誰異想天開，把腳踏車弄到樹上去的？', '是誰異想天開，把腳踏車弄到樹上去的？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"151"}'::jsonb)
  ,('active', '當仁不讓', 'ㄉㄤ ㄖㄣˊ ㄅㄨˋ ㄖㄤˋ', '成語', 3, '面臨仁義之事而不謙讓。語出《論語．衛靈公》。後用「當仁不讓」指遇到應該做的事，主動承擔起來，而不推讓。', '面臨仁義之事而不謙讓。語出《論語．衛靈公》。後用「當仁不讓」指遇到應該做的事，主動承擔起來，而不推讓。 △「義不容辭」、「責無旁貸」、「義無反顧」', '遇到應該做的事，主動承擔起來而不推辭。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為人服務，我們要有當仁不讓的精神。', '為人服務，我們要有當仁不讓的精神。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"152"}'::jsonb)
  ,('active', '恍然大悟', 'ㄏㄨㄤˇ ㄖㄢˊ ㄉㄚˋ ㄨˋ', '成語', 3, '猛然醒悟過來。語本唐．高彥休《唐闕史．卷上．裴丞相古器》。', '猛然醒悟過來。語本唐．高彥休《唐闕史．卷上．裴丞相古器》。 △「豁然大悟」、「豁然貫通」、「豁然開朗」', '猛然醒悟過來。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '經過警方的說明，大家才恍然大悟，知道真凶是誰。', '經過警方的說明，大家才恍然大悟，知道真凶是誰。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"153"}'::jsonb)
  ,('active', '穿鑿附會', 'ㄔㄨㄢ ㄗㄨㄛˋ ㄈㄨˋ ㄏㄨㄟˋ', '成語', 3, '「穿鑿」，牽強的解釋，硬要把說不通的事情說通。語出《漢書．卷七二．王貢兩龔鮑傳．王吉》。「附會」之「附」，典源作「傅」，或作「傅會」，指牽引古事與時事相結合，並據以發表議論。後用「附會」比喻把不相關的事物牽連成有關聯。語本《史記．卷一○一．', '「穿鑿」，牽強的解釋，硬要把說不通的事情說通。語出《漢書．卷七二．王貢兩龔鮑傳．王吉》。「附會」之「附」，典源作「傅」，或作「傅會」，指牽引古事與時事相結合，並據以發表議論。後用「附會」比喻把不相關的事物牽連成有關聯。語本《史記．卷一○一．袁盎鼂錯列傳》。「穿鑿附會」指生拉硬扯，牽強解釋。 △「牽強附會」', '生拉硬扯，牽強解釋。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為了支撐自己的論點，他只好穿鑿附會，胡亂引據。', '為了支撐自己的論點，他只好穿鑿附會，胡亂引據。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"154"}'::jsonb)
  ,('active', '敷衍塞責', 'ㄈㄨ ㄧㄢˇ ㄙㄜˋ ㄗㄜˊ', '成語', 3, '形容做事不認真負責，只是表面應付。※語或出清．張集馨《道咸宦海見聞錄．丁巳五十八歲》。', '形容做事不認真負責，只是表面應付。※語或出清．張集馨《道咸宦海見聞錄．丁巳五十八歲》。 △「敷衍了事」', '形容做事不認真負責，只是表面應付。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '做一行要像一行，千萬不可敷衍塞責，隨便應付了事。', '做一行要像一行，千萬不可敷衍塞責，隨便應付了事。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"155"}'::jsonb)
  ,('active', '暗箭傷人', 'ㄢˋ ㄐㄧㄢˋ ㄕㄤ ㄖㄣˊ', '成語', 3, '在隱蔽處放箭傷害他人。＃語本宋．劉炎《邇言》卷六。後用「暗箭傷人」比喻暗中用陰險的手段傷害人。', '在隱蔽處放箭傷害他人。＃語本宋．劉炎《邇言》卷六。後用「暗箭傷人」比喻暗中用陰險的手段傷害人。 △「含沙射影」。', '比喻暗中用陰險的手段中傷他人。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他向來行事光明正大，從不暗箭傷人。', '他向來行事光明正大，從不暗箭傷人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"156"}'::jsonb)
  ,('active', '隨波逐流', 'ㄙㄨㄟˊ ㄅㄛ ㄓㄨˊ ㄌㄧㄡˊ', '成語', 3, '順著水流而行。比喻人沒有確定的方向和目標，只依從環境潮流行事。語本《史記．卷八四．屈原列傳》。', '順著水流而行。比喻人沒有確定的方向和目標，只依從環境潮流行事。語本《史記．卷八四．屈原列傳》。 △「同流合汙」', '順著水流而行。＆比喻人沒有確定的方向和目標，只依從環境潮流行事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '因為發動機故障了，如今只能任船兒在海上隨波逐流。', '因為發動機故障了，如今只能任船兒在海上隨波逐流。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"157"}'::jsonb)
  ,('active', '暴跳如雷', 'ㄅㄠˋ ㄊㄧㄠˋ ㄖㄨˊ ㄌㄟˊ', '成語', 3, '暴躁得像打雷一樣猛烈。形容脾氣暴躁。語本無名氏〈古詩為焦仲卿妻作〉。後用「暴跳如雷」形容人急怒時跳腳吼叫的樣子。', '暴躁得像打雷一樣猛烈。形容脾氣暴躁。語本無名氏〈古詩為焦仲卿妻作〉。後用「暴跳如雷」形容人急怒時跳腳吼叫的樣子。 △「大發雷霆」', '形容人急怒時跳腳吼叫的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '聽到這些傳聞，他一時情緒激動，暴跳如雷。', '聽到這些傳聞，他一時情緒激動，暴跳如雷。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"158"}'::jsonb)
  ,('active', '優柔寡斷', 'ㄧㄡ ㄖㄡˊ ㄍㄨㄚˇ ㄉㄨㄢˋ', '成語', 3, '優柔，柔弱。「優柔寡斷」形容行事猶豫，不能當機立斷。語本《韓非子．亡徵》。', '優柔，柔弱。「優柔寡斷」形容行事猶豫，不能當機立斷。語本《韓非子．亡徵》。 △「猶豫不決」', '形容行事猶豫，不能當機立斷。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在面對前途的抉擇時，他一反平日，顯得優柔寡斷了。', '在面對前途的抉擇時，他一反平日，顯得優柔寡斷了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"159"}'::jsonb)
  ,('active', '聲色俱厲', 'ㄕㄥ ㄙㄜˋ ㄐㄩˋ ㄌㄧˋ', '成語', 3, '說話時的聲音和臉色都很嚴厲。※＃語或出晉．裴啟《語林》。', '說話時的聲音和臉色都很嚴厲。※＃語或出晉．裴啟《語林》。 △「正言厲色」', '說話時的聲音和臉色都很嚴厲。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '老師一反平日的溫和，聲色俱厲地要求我們團結。', '老師一反平日的溫和，聲色俱厲地要求我們團結。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"160"}'::jsonb)
  ,('active', '華而不實', 'ㄏㄨㄚˊ ㄦˊ ㄅㄨˋ ㄕˊ', '成語', 3, '只開花而不結果，比喻虛浮而不切實際。語出《左傳．文公五年》。', '只開花而不結果，比喻虛浮而不切實際。語出《左傳．文公五年》。 △「金玉其外，敗絮其中」、「虛有其表」', '比喻虛浮而不切實際。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我們做事要務實，不可華而不實。', '我們做事要務實，不可華而不實。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"161"}'::jsonb)
  ,('active', '利令智昏', 'ㄌㄧˋ ㄌㄧㄥˋ ㄓˋ ㄏㄨㄣ', '成語', 3, '形容受利慾迷惑，使得理智昏亂。語出《史記．卷七六．平原君虞卿列傳》。', '形容受利慾迷惑，使得理智昏亂。語出《史記．卷七六．平原君虞卿列傳》。 △「見利忘義」、「見利忘親」', '形容受利慾迷惑，使得理智昏亂。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他坦承自己一時利令智昏，才會盜用公款。', '他坦承自己一時利令智昏，才會盜用公款。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"162"}'::jsonb)
  ,('active', '置之度外', 'ㄓˋ ㄓ ㄉㄨˋ ㄨㄞˋ', '成語', 3, '不放在心上，不加理會。＃語本《東觀漢記．卷一．光武帝紀》。', '不放在心上，不加理會。＃語本《東觀漢記．卷一．光武帝紀》。 △「置之腦後」、「置之膜外」', '不放在心上，不加理會。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我們不能只專注在工作上，而把健康置之度外。', '我們不能只專注在工作上，而把健康置之度外。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"163"}'::jsonb)
  ,('active', '不修邊幅', 'ㄅㄨˋ ㄒㄧㄡ ㄅㄧㄢ ㄈㄨˊ', '成語', 3, '「不修邊幅」，典源本作「修飾邊幅」，指修整布帛邊緣，使它變得整齊。比喻講究衣飾儀容或形式小節。語本《後漢書．卷二四．馬援列傳》。後反義轉用「不修邊幅」形容不講究衣飾儀容，或形容不拘形式小節。', '「不修邊幅」，典源本作「修飾邊幅」，指修整布帛邊緣，使它變得整齊。比喻講究衣飾儀容或形式小節。語本《後漢書．卷二四．馬援列傳》。後反義轉用「不修邊幅」形容不講究衣飾儀容，或形容不拘形式小節。 △「妄自尊大」、「修飾邊幅」、「蓬頭垢面」', '形容不講究衣飾儀容。＆形容不拘形式小節。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他向來不修邊幅，滿頭亂髮，穿著邋遢。', '他向來不修邊幅，滿頭亂髮，穿著邋遢。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"164"}'::jsonb)
  ,('active', '手無寸鐵', 'ㄕㄡˇ ㄨˊ ㄘㄨㄣˋ ㄊㄧㄝˇ', '成語', 3, '「手無寸鐵」之「鐵」，典源作「刃」。手上沒有短小鋒利的武器。形容手上沒有拿任何武器。語本南朝宋．劉敬叔《異苑．卷一○．楊香搤虎》。', '「手無寸鐵」之「鐵」，典源作「刃」。手上沒有短小鋒利的武器。形容手上沒有拿任何武器。語本南朝宋．劉敬叔《異苑．卷一○．楊香搤虎》。 △「赤手空拳」', '形容手上沒有拿任何武器。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '對方來勢洶洶，我們手無寸鐵，先退了再說吧！', '對方來勢洶洶，我們手無寸鐵，先退了再說吧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"165"}'::jsonb)
  ,('active', '玉石俱焚', 'ㄩˋ ㄕˊ ㄐㄩˋ ㄈㄣˊ', '成語', 3, '美玉和石頭一同被燒毀。語出《書經．胤征》。後用「玉石俱焚」比喻不論賢愚、善惡、好壞同時受害，盡皆毀滅。', '美玉和石頭一同被燒毀。語出《書經．胤征》。後用「玉石俱焚」比喻不論賢愚、善惡、好壞同時受害，盡皆毀滅。 △「同歸於盡」', '比喻不論賢愚、善惡、好壞同時受害，盡皆毀滅。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '核戰一旦爆發，結果必是萬物成灰、玉石俱焚。', '核戰一旦爆發，結果必是萬物成灰、玉石俱焚。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"166"}'::jsonb)
  ,('active', '一手遮天', 'ㄧ ㄕㄡˇ ㄓㄜ ㄊㄧㄢ', '成語', 3, '比喻玩弄權術、瞞上欺下的行徑。語本唐．曹鄴〈讀李斯傳〉詩。', '比喻玩弄權術、瞞上欺下的行徑。語本唐．曹鄴〈讀李斯傳〉詩。 △「瞞天過海」', '比喻玩弄權術、瞞上欺下的行徑。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '此事多人皆可見證，豈容他一手遮天，欺上瞞下！', '此事多人皆可見證，豈容他一手遮天，欺上瞞下！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"167"}'::jsonb)
  ,('active', '七手八腳', 'ㄑㄧ ㄕㄡˇ ㄅㄚ ㄐㄧㄠˇ', '成語', 3, '形容人多動作紛亂又沒條理。※語或出《續傳燈錄．卷二二．慶元府育王佛照德光禪師》。', '形容人多動作紛亂又沒條理。※語或出《續傳燈錄．卷二二．慶元府育王佛照德光禪師》。 △「手忙腳亂」', '形容人多動作紛亂又沒條理。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '大家七嘴八舌加上七手八腳，現場真是亂成一團。', '大家七嘴八舌加上七手八腳，現場真是亂成一團。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"168"}'::jsonb)
  ,('active', '一觸即發', 'ㄧ ㄔㄨˋ ㄐㄧˊ ㄈㄚ', '成語', 3, '一經觸動就立即有所感發或反應。※語或本明．李開先〈原性堂記〉。後用「一觸即發」比喻很緊張的情勢或很危險的時刻。', '一經觸動就立即有所感發或反應。※語或本明．李開先〈原性堂記〉。後用「一觸即發」比喻很緊張的情勢或很危險的時刻。 △「劍拔弩張」', '比喻很緊張的情勢或很危險的時刻。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這場貿易戰，大有一觸即發之勢。', '這場貿易戰，大有一觸即發之勢。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"169"}'::jsonb)
  ,('active', '心悅誠服', 'ㄒㄧㄣ ㄩㄝˋ ㄔㄥˊ ㄈㄨˊ', '成語', 3, '誠心誠意地歸服。語本《孟子．公孫丑上》。', '誠心誠意地歸服。語本《孟子．公孫丑上》。 △「心服口服」', '誠心誠意地歸服。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我雖無法反駁他這些話，但沒有心悅誠服。', '我雖無法反駁他這些話，但沒有心悅誠服。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"170"}'::jsonb)
  ,('active', '改弦易轍', 'ㄍㄞˇ ㄒㄧㄢˊ ㄧˋ ㄔㄜˋ', '成語', 3, '「改弦」，改換樂弦。語本漢．董仲舒〈元光元年舉賢良對策〉。「易轍」，改變車行方向。語本《晏子》。「改弦易轍」比喻改變制度、做法或態度。', '「改弦」，改換樂弦。語本漢．董仲舒〈元光元年舉賢良對策〉。「易轍」，改變車行方向。語本《晏子》。「改弦易轍」比喻改變制度、做法或態度。 △「改弦更張」', '比喻改變制度、做法或態度。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '經商一途既然行不通，他就改弦易轍地寫起小說來。', '經商一途既然行不通，他就改弦易轍地寫起小說來。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"171"}'::jsonb)
  ,('active', '兵連禍結', 'ㄅㄧㄥ ㄌㄧㄢˊ ㄏㄨㄛˋ ㄐㄧㄝˊ', '成語', 3, '兵，戰爭。結，相連。「兵連禍結」指戰爭持續不斷，災禍接連而來。語出《漢書．卷九四．匈奴傳下》。', '兵，戰爭。結，相連。「兵連禍結」指戰爭持續不斷，災禍接連而來。語出《漢書．卷九四．匈奴傳下》。 △「兵荒馬亂」', '戰爭持續不斷，災禍接連而來。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這地區長久以來因為種族問題而兵連禍結。', '這地區長久以來因為種族問題而兵連禍結。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"172"}'::jsonb)
  ,('active', '出神入化', 'ㄔㄨ ㄕㄣˊ ㄖㄨˋ ㄏㄨㄚˋ', '成語', 3, '產生神妙，入於化境。語出明．黃佐《翰林記．卷一○．習書》。後用「出神入化」形容文藝、技藝、工藝等之技巧達到至高絕妙的境界。', '產生神妙，入於化境。語出明．黃佐《翰林記．卷一○．習書》。後用「出神入化」形容文藝、技藝、工藝等之技巧達到至高絕妙的境界。 △「出神變化」、「巧奪天工」、「鬼斧神工」', '形容文藝、技藝、工藝等之技巧達到至高絕妙的境界。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '只見他提起筆，才幾筆就出神入化地畫出一匹馬。', '只見他提起筆，才幾筆就出神入化地畫出一匹馬。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"173"}'::jsonb)
  ,('active', '居心叵測', 'ㄐㄩ ㄒㄧㄣ ㄆㄛˇ ㄘㄜˋ', '成語', 3, '「居心」，存心、處心。語出《三國志．卷五九．吳書．吳主五子傳》；「叵測」，難以預料、不可測。語出《新唐書．卷二○○．儒學列傳下．尹愔》。後用「居心叵測」比喻心存險詐，難以預測。', '「居心」，存心、處心。語出《三國志．卷五九．吳書．吳主五子傳》；「叵測」，難以預料、不可測。語出《新唐書．卷二○○．儒學列傳下．尹愔》。後用「居心叵測」比喻心存險詐，難以預測。 △「包藏禍心」、「別有用心」', '比喻心存險詐，難以預測。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他巧言令色，居心叵測，絕不是一個好人。', '他巧言令色，居心叵測，絕不是一個好人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"174"}'::jsonb)
  ,('active', '千方百計', 'ㄑㄧㄢ ㄈㄤ ㄅㄞˇ ㄐㄧˋ', '成語', 3, '費盡心機，想盡一切辦法、計謀。※＃語或出宋．彭龜年〈論小人疑間兩宮乞車駕過宮面質疏〉。', '費盡心機，想盡一切辦法、計謀。※＃語或出宋．彭龜年〈論小人疑間兩宮乞車駕過宮面質疏〉。 △「千方萬計」', '費盡心機，想盡一切辦法、計謀。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為了解決眼前的難題，他們確實用盡了千方百計。', '為了解決眼前的難題，他們確實用盡了千方百計。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"175"}'::jsonb)
  ,('active', '一帆風順', 'ㄧ ㄈㄢˊ ㄈㄥ ㄕㄨㄣˋ', '成語', 3, '船掛滿帆，一路順風而行。※語或本宋．楊萬里〈曉出洪澤霜晴風順〉詩。後用「一帆風順」比喻非常順利，毫無阻礙。', '船掛滿帆，一路順風而行。※語或本宋．楊萬里〈曉出洪澤霜晴風順〉詩。後用「一帆風順」比喻非常順利，毫無阻礙。 △「無往不利」', '比喻非常順利，毫無阻礙。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '明天你出國，在此祝你一帆風順。', '明天你出國，在此祝你一帆風順。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"176"}'::jsonb)
  ,('active', '大惑不解', 'ㄉㄚˋ ㄏㄨㄛˋ ㄅㄨˋ ㄐㄧㄝˇ', '成語', 3, '十分糊塗、迷惑，不懂道理。語本《莊子．天地》。後用「大惑不解」指對事物感到非常疑惑，無法了解。', '十分糊塗、迷惑，不懂道理。語本《莊子．天地》。後用「大惑不解」指對事物感到非常疑惑，無法了解。 △「百思不解」', '指對事物感到非常疑惑，無法了解。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我看你是大惑不解，居然不能體會人家對你的關心。', '我看你是大惑不解，居然不能體會人家對你的關心。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"177"}'::jsonb)
  ,('active', '金蟬脫殼', 'ㄐㄧㄣ ㄔㄢˊ ㄊㄨㄛ ㄎㄜˊ', '成語', 3, '金蟬蛻變於脫去外殼。比喻利用假象藉以脫身。※語或本《三國志平話》卷上。', '金蟬蛻變於脫去外殼。比喻利用假象藉以脫身。※語或本《三國志平話》卷上。 △「逃之夭夭」、「溜之大吉」', '比喻利用假象藉以脫身。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '凶手巧使金蟬脫殼之計，讓追捕他的人撲了個空。', '凶手巧使金蟬脫殼之計，讓追捕他的人撲了個空。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"178"}'::jsonb)
  ,('active', '五花八門', 'ㄨˇ ㄏㄨㄚ ㄅㄚ ㄇㄣˊ', '成語', 3, '五花、八門各指古代兵法中的五花陣、八門陣。※語或出清．錢泳《履園叢話．卷一六．精怪．張氏怪》。後用「五花八門」比喻花樣繁多，變化多端。', '五花、八門各指古代兵法中的五花陣、八門陣。※語或出清．錢泳《履園叢話．卷一六．精怪．張氏怪》。後用「五花八門」比喻花樣繁多，變化多端。 △「形形色色」', '比喻花樣繁多，變化多端。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這家專賣店所陳列的女鞋五花八門，應有盡有。', '這家專賣店所陳列的女鞋五花八門，應有盡有。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"179"}'::jsonb)
  ,('active', '一貧如洗', 'ㄧ ㄆㄧㄣˊ ㄖㄨˊ ㄒㄧˇ', '成語', 3, '形容非常貧窮，一無所有。※語或本宋．王鎡〈山居〉詩。', '形容非常貧窮，一無所有。※語或本宋．王鎡〈山居〉詩。 △「家徒四壁」', '形容非常貧窮，一無所有。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '雖然我已是一貧如洗，但我決心伺機再起。', '雖然我已是一貧如洗，但我決心伺機再起。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"180"}'::jsonb)
  ,('active', '心安理得', 'ㄒㄧㄣ ㄢ ㄌㄧˇ ㄉㄜˊ', '成語', 3, '形容心中坦然無所愧咎，則行事合情合理。※＃語或本《論語．陽貨》。', '形容心中坦然無所愧咎，則行事合情合理。※＃語或本《論語．陽貨》。 △「問心無愧」', '形容行事合情合理，則心中坦然無憾。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我平生不做虧心事，當然心安理得。', '我平生不做虧心事，當然心安理得。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"181"}'::jsonb)
  ,('active', '道貌岸然', 'ㄉㄠˋ ㄇㄠˋ ㄢˋ ㄖㄢˊ', '成語', 3, '學道的人容貌莊嚴肅穆。形容外表莊重嚴肅的樣子。語本敦煌變文《維摩詰經講經文》。', '學道的人容貌莊嚴肅穆。形容外表莊重嚴肅的樣子。語本敦煌變文《維摩詰經講經文》。 △「一本正經」', '形容外表莊重嚴肅的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '想不到他外表道貌岸然，其實卻是滿肚子壞心意。', '想不到他外表道貌岸然，其實卻是滿肚子壞心意。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"182"}'::jsonb)
  ,('active', '飛揚跋扈', 'ㄈㄟ ㄧㄤˊ ㄅㄚˊ ㄏㄨˋ', '成語', 3, '跋扈，形容人傲慢蠻橫。「飛揚跋扈」則形容態度蠻橫放縱，不受約束。＃語出《北齊書．卷二．神武帝紀下》。', '跋扈，形容人傲慢蠻橫。「飛揚跋扈」則形容態度蠻橫放縱，不受約束。＃語出《北齊書．卷二．神武帝紀下》。 △「飛揚跋扈」', '形容態度蠻橫放縱，不受約束。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他那種傲氣十足、飛揚跋扈的態度，令人厭惡。', '他那種傲氣十足、飛揚跋扈的態度，令人厭惡。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"183"}'::jsonb)
  ,('active', '苦口婆心', 'ㄎㄨˇ ㄎㄡˇ ㄆㄛˊ ㄒㄧㄣ', '成語', 3, '「苦口」，不辭辛苦的反覆規勸。＃語出《宋史．卷二五六．趙普列傳》。「婆心」，像老婆婆那樣慈愛的心腸。語出《景德傳燈錄．卷一二．鎮州臨濟義玄禪師》。「苦口婆心」形容以懇切真摯的態度，竭力勸告他人。', '「苦口」，不辭辛苦的反覆規勸。＃語出《宋史．卷二五六．趙普列傳》。「婆心」，像老婆婆那樣慈愛的心腸。語出《景德傳燈錄．卷一二．鎮州臨濟義玄禪師》。「苦口婆心」形容以懇切真摯的態度，竭力勸告他人。 △「語重心長」', '形容以懇切真摯的態度，竭力勸告他人。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '母親苦口婆心的勸告，我一定牢記於心。', '母親苦口婆心的勸告，我一定牢記於心。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"184"}'::jsonb)
  ,('active', '比比皆是', 'ㄅㄧˋ ㄅㄧˋ ㄐㄧㄝ ㄕˋ', '成語', 3, '比比，每每、頻頻。「比比皆是」形容到處都是。語本《戰國策．秦策一》。', '比比，每每、頻頻。「比比皆是」形容到處都是。語本《戰國策．秦策一》。 △「比肩皆是」、「摩肩接踵」、「觸目皆是」', '形容到處都是。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '如今社會富裕了，住高樓、開汽車的人比比皆是。', '如今社會富裕了，住高樓、開汽車的人比比皆是。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"185"}'::jsonb)
  ,('active', '顛沛流離', 'ㄉㄧㄢ ㄆㄟˋ ㄌㄧㄡˊ ㄌㄧˊ', '成語', 3, '「顛沛」，比喻世道衰亂或人事挫折。語出《論語．里仁》。「流離」，流亡離散。◎語出《漢書．卷二四．食貨志上》。「顛沛流離」形容生活困迫不安，四處流浪。', '「顛沛」，比喻世道衰亂或人事挫折。語出《論語．里仁》。「流離」，流亡離散。◎語出《漢書．卷二四．食貨志上》。「顛沛流離」形容生活困迫不安，四處流浪。 △「百六之會」、「流離失所」、「陽九之阸」', '形容生活困迫不安，四處流浪。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '假如一個國家戰禍連年，必然造成人民顛沛流離。', '假如一個國家戰禍連年，必然造成人民顛沛流離。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"186"}'::jsonb)
  ,('active', '雷厲風行', 'ㄌㄟˊ ㄌㄧˋ ㄈㄥ ㄒㄧㄥˊ', '成語', 3, '像打雷般猛烈，如颳風般快速。比喻政令執行嚴格迅速。※＃語或本《易經．復卦》三國魏．王弼．注。後用「雷厲風行」比喻人行事嚴格迅速。', '像打雷般猛烈，如颳風般快速。比喻政令執行嚴格迅速。※＃語或本《易經．復卦》三國魏．王弼．注。後用「雷厲風行」比喻人行事嚴格迅速。 △「大刀闊斧」', '比喻人行事嚴格迅速。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '推行掃黑政策時，就要雷厲風行，以避免姑息養奸。', '推行掃黑政策時，就要雷厲風行，以避免姑息養奸。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"187"}'::jsonb)
  ,('active', '十拿九穩', 'ㄕˊ ㄋㄚˊ ㄐㄧㄡˇ ㄨㄣˇ', '成語', 3, '拿：握持。穩：穩當。比喻很有把握。※語或出明．阮大鋮《燕子箋》第七齣。', '拿：握持。穩：穩當。比喻很有把握。※語或出明．阮大鋮《燕子箋》第七齣。 △「萬無一失」', '比喻很有把握。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '若不是十拿九穩的事，他不會輕易答應你的。', '若不是十拿九穩的事，他不會輕易答應你的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"188"}'::jsonb)
  ,('active', '寡廉鮮恥', 'ㄍㄨㄚˇ ㄌㄧㄢˊ ㄒㄧㄢˇ ㄔˇ', '成語', 3, '缺乏廉恥之心。比喻不知羞恥。語出漢．司馬相如〈喻巴蜀檄〉。', '缺乏廉恥之心。比喻不知羞恥。語出漢．司馬相如〈喻巴蜀檄〉。 △「恬不知恥」、「義無反顧」', '比喻不知羞恥。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種人唯利是圖，寡廉鮮恥，我深為不齒！', '這種人唯利是圖，寡廉鮮恥，我深為不齒！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"189"}'::jsonb)
  ,('active', '模稜兩可', 'ㄇㄛˊ ㄌㄥˊ ㄌㄧㄤˇ ㄎㄜˇ', '成語', 3, '「模稜兩可」之「模」，典源作「摸」。「摸」，通「模」。「模稜兩可」摸物稜角兩端，摸那一端都可以。比喻處理事情的態度含混，不表示明確的意見或主張。語本《舊唐書．卷九四．蘇味道列傳》。', '「模稜兩可」之「模」，典源作「摸」。「摸」，通「模」。「模稜兩可」摸物稜角兩端，摸那一端都可以。比喻處理事情的態度含混，不表示明確的意見或主張。語本《舊唐書．卷九四．蘇味道列傳》。 △「不置可否」', '比喻處理事情的態度含混，不表示明確的意見或主張。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你說話模稜兩可，我無法了解你的真實意願。', '你說話模稜兩可，我無法了解你的真實意願。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"190"}'::jsonb)
  ,('active', '充耳不聞', 'ㄔㄨㄥ ㄦˇ ㄅㄨˋ ㄨㄣˊ', '成語', 3, '塞住耳朵，裝作沒聽見。※語或本《詩經．邶風．旄丘》鄭玄．箋。後用「充耳不聞」形容拒絕或不願聽取別人意見。', '塞住耳朵，裝作沒聽見。※語或本《詩經．邶風．旄丘》鄭玄．箋。後用「充耳不聞」形容拒絕或不願聽取別人意見。 △「不聞不問」', '裝作沒聽見。＆形容拒絕或不願聽取別人意見。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他只要一專心，屋外隆隆的車聲，他都可以充耳不聞。', '他只要一專心，屋外隆隆的車聲，他都可以充耳不聞。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"191"}'::jsonb)
  ,('active', '蠢蠢欲動', 'ㄔㄨㄣˇ ㄔㄨㄣˇ ㄩˋ ㄉㄨㄥˋ', '成語', 3, '像蟲子一樣扭曲著身軀欲有所行動。比喻人意圖為害作亂。語本《左傳．昭公二十四年》。', '像蟲子一樣扭曲著身軀欲有所行動。比喻人意圖為害作亂。語本《左傳．昭公二十四年》。 △「躍躍欲試」', '比喻人意圖為害作亂。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '面對偷渡客蠢蠢欲動，海防單位隨時都得嚴陣以待。', '面對偷渡客蠢蠢欲動，海防單位隨時都得嚴陣以待。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"192"}'::jsonb)
  ,('active', '聽天由命', 'ㄊㄧㄥˋ ㄊㄧㄢ ㄧㄡˊ ㄇㄧㄥˋ', '成語', 3, '任憑天意及命運而自然發展。語本漢．孔臧〈鴞賦〉。', '任憑天意及命運而自然發展。語本漢．孔臧〈鴞賦〉。 △「聽其自然」', '形容任憑天意及命運而自然發展。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在地震來臨、天搖地動之際，人只能聽天由命。', '在地震來臨、天搖地動之際，人只能聽天由命。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"193"}'::jsonb)
  ,('active', '大腹便便', 'ㄉㄚˋ ㄈㄨˋ ㄆㄧㄢˊ ㄆㄧㄢˊ', '成語', 3, '大肚子顯得肥胖而凸出的樣子。＃語本晉．司馬彪《續漢書》。', '大肚子顯得肥胖而凸出的樣子。＃語本晉．司馬彪《續漢書》。 △「腦滿腸肥」', '大肚子顯得肥胖而凸出的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '婦女懷胎幾個月後，就會顯得大腹便便，行動極不方便。', '婦女懷胎幾個月後，就會顯得大腹便便，行動極不方便。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"194"}'::jsonb)
  ,('active', '聲名狼藉', 'ㄕㄥ ㄇㄧㄥˊ ㄌㄤˊ ㄐㄧˊ', '成語', 3, '「聲名狼藉」之「藉」，典源作「籍」。「籍」通「藉」。指肆意妄為，名聲惡劣。語本《史記．卷八八．蒙恬列傳》唐．司馬貞．索隱。', '「聲名狼藉」之「藉」，典源作「籍」。「籍」通「藉」。指肆意妄為，名聲惡劣。語本《史記．卷八八．蒙恬列傳》唐．司馬貞．索隱。 △「身敗名裂」', '指肆意妄為，名聲惡劣。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他無惡不作，在這地區早已聲名狼藉。', '他無惡不作，在這地區早已聲名狼藉。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"195"}'::jsonb)
  ,('active', '探囊取物', 'ㄊㄢˋ ㄋㄤˊ ㄑㄩˇ ㄨˋ', '成語', 3, '伸手到袋子裡拿取東西。比喻事情極容易辦到。語本《新五代史．卷六二．十國世家．南唐世家》。', '伸手到袋子裡拿取東西。比喻事情極容易辦到。語本《新五代史．卷六二．十國世家．南唐世家》。 △「甕中捉鱉」', '比喻事情極容易辦到。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '只要我們準備妥當，要取得勝利就如探囊取物一般。', '只要我們準備妥當，要取得勝利就如探囊取物一般。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"196"}'::jsonb)
  ,('active', '處心積慮', 'ㄔㄨˇ ㄒㄧㄣ ㄐㄧ ㄌㄩˋ', '成語', 3, '千方百慮，蓄意已久。語出《穀梁傳．隱公元年》。', '千方百慮，蓄意已久。語出《穀梁傳．隱公元年》。 △「挖空心思」', '千方百慮，蓄意已久。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '敵人正處心積慮地想分化我們，我們千萬別中計。', '敵人正處心積慮地想分化我們，我們千萬別中計。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"197"}'::jsonb)
  ,('active', '呆若木雞', 'ㄉㄞ ㄖㄨㄛˋ ㄇㄨˋ ㄐㄧ', '成語', 3, '木雞，木頭製成的雞，任何情況下皆紋風不動，比喻修養深厚、態度沈穩。語本《莊子．達生》。後用「呆若木雞」形容愚笨或受驚嚇而發愣的樣子。', '木雞，木頭製成的雞，任何情況下皆紋風不動，比喻修養深厚、態度沈穩。語本《莊子．達生》。後用「呆若木雞」形容愚笨或受驚嚇而發愣的樣子。 △「木雞養到」、「目瞪口呆」', '形容愚笨或受驚嚇而發愣的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '都好半天了，他仍然呆若木雞地瞪著天花板看。', '都好半天了，他仍然呆若木雞地瞪著天花板看。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"198"}'::jsonb)
  ,('active', '以鄰為壑', 'ㄧˇ ㄌㄧㄣˊ ㄨㄟˊ ㄏㄨㄛˋ', '成語', 3, '將鄰國當作渲洩洪水的溝壑。語本《孟子．告子下》。後用「以鄰為壑」比喻將困難和災禍推到別人身上。', '將鄰國當作渲洩洪水的溝壑。語本《孟子．告子下》。後用「以鄰為壑」比喻將困難和災禍推到別人身上。 △「嫁禍於人」', '比喻將困難和災禍推到別人身上。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這種盡占別人便宜，以鄰為壑的態度，真叫人不齒。', '他這種盡占別人便宜，以鄰為壑的態度，真叫人不齒。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"199"}'::jsonb)
  ,('active', '言簡意賅', 'ㄧㄢˊ ㄐㄧㄢˇ ㄧˋ ㄍㄞ', '成語', 3, '賅，兼備。「言簡意賅」指言辭簡單而意思完備。語本宋．張載《張子全書．卷六．義理》。', '賅，兼備。「言簡意賅」指言辭簡單而意思完備。語本宋．張載《張子全書．卷六．義理》。 △「要言不煩」', '言辭簡單而意思完備。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他向來說話言簡意賅，絕不囉嗦。', '他向來說話言簡意賅，絕不囉嗦。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"200"}'::jsonb)
  ,('active', '積重難返', 'ㄐㄧ ㄓㄨㄥˋ ㄋㄢˊ ㄈㄢˇ', '成語', 3, '長期累積成的不良習慣與弊病，難以改正。※語或出明．張居正〈陳六事疏〉。', '長期累積成的不良習慣與弊病，難以改正。※語或出明．張居正〈陳六事疏〉。 △「根深蒂固」', '長期累積成的不良習慣與弊病，難以改正。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種惡習如果不及時糾正，等到積重難返，要改也改不成了。', '這種惡習如果不及時糾正，等到積重難返，要改也改不成了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"201"}'::jsonb)
  ,('active', '標新立異', 'ㄅㄧㄠ ㄒㄧㄣ ㄌㄧˋ ㄧˋ', '成語', 3, '新的獨到見解，與諸家立論不同。◎語本南朝宋．劉義慶《世說新語．文學》。後用「標新立異」形容創立新奇的名目或主張，以表示與眾不同。', '新的獨到見解，與諸家立論不同。◎語本南朝宋．劉義慶《世說新語．文學》。後用「標新立異」形容創立新奇的名目或主張，以表示與眾不同。 △「立奇造異」、「獨樹一幟」', '形容創立新奇的名目或主張，以表示與眾不同。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '設計海報就是要講究另類，標新立異。', '設計海報就是要講究另類，標新立異。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"202"}'::jsonb)
  ,('active', '來龍去脈', 'ㄌㄞˊ ㄌㄨㄥˊ ㄑㄩˋ ㄇㄞˋ', '成語', 3, '本是堪輿家用以形容山脈河流走向的術語，後用以比喻事情的首尾始末。※語或出明．無名氏《運甓記》第一三齣。', '本是堪輿家用以形容山脈河流走向的術語，後用以比喻事情的首尾始末。※語或出明．無名氏《運甓記》第一三齣。 △「前因後果」', '堪輿家用以形容山脈河流走向的術語。＆比喻事情的首尾始末。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這塊是大富大貴之地，來龍去脈，靠嶺朝山。', '這塊是大富大貴之地，來龍去脈，靠嶺朝山。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"203"}'::jsonb)
  ,('active', '櫛風沐雨', 'ㄐㄧㄝˊ ㄈㄥ ㄇㄨˋ ㄩˇ', '成語', 3, '以風梳髮，以雨沐浴。語本《莊子．天下》。後用「櫛風沐雨」比喻在外奔走，極為辛勞。', '以風梳髮，以雨沐浴。語本《莊子．天下》。後用「櫛風沐雨」比喻在外奔走，極為辛勞。 △「風餐露宿」', '比喻在外奔走，極為辛勞。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '父親當推銷員，必須長年累月、櫛風沐雨地在外工作。', '父親當推銷員，必須長年累月、櫛風沐雨地在外工作。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"204"}'::jsonb)
  ,('active', '所向披靡', 'ㄙㄨㄛˇ ㄒㄧㄤˋ ㄆㄧ ㄇㄧˇ', '成語', 3, '風吹到的地方，草木立即伏倒。比喻力量所到之處，敵人紛紛潰敗逃散。＃語本《史記．卷七．項羽本紀》。', '風吹到的地方，草木立即伏倒。比喻力量所到之處，敵人紛紛潰敗逃散。＃語本《史記．卷七．項羽本紀》。 △「所向無敵」', '比喻力量所到之處，敵人紛紛潰敗逃散。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '義軍所到之處，無不所向披靡。', '義軍所到之處，無不所向披靡。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"205"}'::jsonb)
  ,('active', '海底撈針', 'ㄏㄞˇ ㄉㄧˇ ㄌㄠ ㄓㄣ', '成語', 3, '在大海中尋找一根細小的針。比喻東西很難找到或事情很難做到。※＃語或本元．吳昌齡《二郎收豬八戒》第二折。', '在大海中尋找一根細小的針。比喻東西很難找到或事情很難做到。※＃語或本元．吳昌齡《二郎收豬八戒》第二折。 △「水中撈月」', '比喻東西很難找到或事情很難做到。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '既然沒有其他線索，就只好請你在這堆資料中海底撈針吧！', '既然沒有其他線索，就只好請你在這堆資料中海底撈針吧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"206"}'::jsonb)
  ,('active', '栩栩如生', 'ㄒㄩˇ ㄒㄩˇ ㄖㄨˊ ㄕㄥ', '成語', 3, '栩栩，生動可喜的樣子。語本《莊子．齊物論》。後用「栩栩如生」形容貌態逼真，彷彿具有生命力。', '栩栩，生動可喜的樣子。語本《莊子．齊物論》。後用「栩栩如生」形容貌態逼真，彷彿具有生命力。 △「活龍活現」、「莊周夢蝶」、「維妙維肖」、「躍然紙上」', '貌態逼真，彷彿具有生命力。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這尊判官神像雕得栩栩如生，有點嚇人。', '這尊判官神像雕得栩栩如生，有點嚇人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"207"}'::jsonb)
  ,('active', '惡貫滿盈', 'ㄜˋ ㄍㄨㄢˋ ㄇㄢˇ ㄧㄥˊ', '成語', 3, '貫，本指以線穿錢，錢滿一貫，就不能增加，稱為滿貫。此處指惡行「累積」，《廣雅．釋詁一》︰「貫，累也。」罪惡累積，已達滿溢的程度。比喻罪大惡極，末日已到。＃語本《書經．泰誓上》。', '貫，本指以線穿錢，錢滿一貫，就不能增加，稱為滿貫。此處指惡行「累積」，《廣雅．釋詁一》︰「貫，累也。」罪惡累積，已達滿溢的程度。比喻罪大惡極，末日已到。＃語本《書經．泰誓上》。 △「罪大惡極」', '比喻罪大惡極，末日已到。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這幫歹徒惡貫滿盈，終於受到法律制裁。', '這幫歹徒惡貫滿盈，終於受到法律制裁。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"208"}'::jsonb)
  ,('active', '朝秦暮楚', 'ㄓㄠ ㄑㄧㄣˊ ㄇㄨˋ ㄔㄨˇ', '成語', 3, '（一）「朝秦暮楚」之「暮」，典源作「莫」。「莫」為「暮」的本字。戰國時之小國，時而事秦，時而事楚，反覆無常。語出宋．晁補之〈海陵集序〉。後用「朝秦暮楚」比喻人心反覆無常。', '（一）「朝秦暮楚」之「暮」，典源作「莫」。「莫」為「暮」的本字。戰國時之小國，時而事秦，時而事楚，反覆無常。語出宋．晁補之〈海陵集序〉。後用「朝秦暮楚」比喻人心反覆無常。 △「反覆無常」、「出爾反爾」、「朝三暮四」、「朝梁暮陳」 （二）「朝秦暮楚」之「暮」，典源作「莫」。「莫」為「暮」的本字。早上還在秦國，晚上卻已在楚國。比喻人東飄西蕩，行蹤無定。語出宋．晁補之〈北渚亭賦〉。 △「朝吳暮楚」', '比喻人心反覆無常。貶義。＆比喻人東飄西蕩，行蹤無定。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '她是個拜金女郎，朝秦暮楚，有何奇怪？', '她是個拜金女郎，朝秦暮楚，有何奇怪？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"209"}'::jsonb)
  ,('active', '斬草除根', 'ㄓㄢˇ ㄘㄠˇ ㄔㄨˊ ㄍㄣ', '成語', 3, '將雜草連根拔除。比喻除去禍根，不留後患。語本《左傳．隱公六年》。', '將雜草連根拔除。比喻除去禍根，不留後患。語本《左傳．隱公六年》。 △「除惡務盡」、「趕盡殺絕」', '比喻除去禍根，不留後患。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這件事唯有澈底地斬草除根，才算治本。', '這件事唯有澈底地斬草除根，才算治本。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"210"}'::jsonb)
  ,('active', '喜出望外', 'ㄒㄧˇ ㄔㄨ ㄨㄤˋ ㄨㄞˋ', '成語', 3, '望外，意想不到。「喜出望外」指因意想不到的事感到欣喜。語出宋．蘇軾〈與李之儀書〉五首之二。', '望外，意想不到。「喜出望外」指因意想不到的事感到欣喜。語出宋．蘇軾〈與李之儀書〉五首之二。 △「大喜過望」、「喜從天降」', '因意想不到的事感到欣喜。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '失聯多年的叔父意外歸來，讓全家都喜出望外。', '失聯多年的叔父意外歸來，讓全家都喜出望外。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"211"}'::jsonb)
  ,('active', '花言巧語', 'ㄏㄨㄚ ㄧㄢˊ ㄑㄧㄠˇ ㄩˇ', '成語', 3, '形容虛假而動聽的言語。語出《朱子語類．卷二○．論語．學而篇》。', '形容虛假而動聽的言語。語出《朱子語類．卷二○．論語．學而篇》。 △「甜言蜜語」', '形容虛假而動聽的言語。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '金光黨利用人性貪的弱點，花言巧語騙走許多人畢生的積蓄。', '金光黨利用人性貪的弱點，花言巧語騙走許多人畢生的積蓄。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"212"}'::jsonb)
  ,('active', '垂頭喪氣', 'ㄔㄨㄟˊ ㄊㄡˊ ㄙㄤˋ ㄑㄧˋ', '成語', 3, '低垂著頭，意氣消沉。形容失意沮喪的樣子。※＃語或出唐．韓愈〈送窮文〉。', '低垂著頭，意氣消沉。形容失意沮喪的樣子。※＃語或出唐．韓愈〈送窮文〉。 △「灰心喪氣」、「面目可憎」', '形容失意沮喪的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '人生難免遭遇挫折，與其垂頭喪氣，不如振作精神，重新再幹。', '人生難免遭遇挫折，與其垂頭喪氣，不如振作精神，重新再幹。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"213"}'::jsonb)
  ,('active', '流連忘返', 'ㄌㄧㄡˊ ㄌㄧㄢˊ ㄨㄤˋ ㄈㄢˇ', '成語', 3, '貪戀沉迷而不願離去。語本《孟子．梁惠王下》。', '貪戀沉迷而不願離去。語本《孟子．梁惠王下》。 △「流宕忘反」、「流遯忘反」、「樂而忘返」', '貪戀沉迷而忘了回去。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這草原、這白雲，就是讓我流連忘返的好地方。', '這草原、這白雲，就是讓我流連忘返的好地方。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"214"}'::jsonb)
  ,('active', '隨機應變', 'ㄙㄨㄟˊ ㄐㄧ ㄧㄥˋ ㄅㄧㄢˋ', '成語', 3, '隨著時機和情況的變化而靈活應付。＃語出《舊唐書．卷八三．郭孝恪列傳》。', '隨著時機和情況的變化而靈活應付。＃語出《舊唐書．卷八三．郭孝恪列傳》。 △「見風使舵」、「見機行事」、「隨時應變」', '隨著時機和情況的變化而靈活應付。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '做事要靈活，隨機應變，不要死守舊規則。', '做事要靈活，隨機應變，不要死守舊規則。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"215"}'::jsonb)
  ,('active', '分庭抗禮', 'ㄈㄣ ㄊㄧㄥˊ ㄎㄤˋ ㄌㄧˇ', '成語', 3, '「分庭抗禮」之「抗」，典源作「伉」，對等、匹敵之義。「分庭抗禮」指分處庭中，相對設禮，以平等的禮節相見。比喻地位相當。語本《莊子．漁父》。後亦用「分庭抗禮」比喻兩者對立。', '「分庭抗禮」之「抗」，典源作「伉」，對等、匹敵之義。「分庭抗禮」指分處庭中，相對設禮，以平等的禮節相見。比喻地位相當。語本《莊子．漁父》。後亦用「分庭抗禮」比喻兩者對立。 △「平起平坐」', '以平等禮節相待。＆比喻兩者對立。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '唐代雖有不少著名詩人，但恐怕只有杜甫能和李白分庭抗禮吧！', '唐代雖有不少著名詩人，但恐怕只有杜甫能和李白分庭抗禮吧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"216"}'::jsonb)
  ,('active', '應接不暇', 'ㄧㄥˋ ㄐㄧㄝ ㄅㄨˋ ㄒㄧㄚˊ', '成語', 3, '暇，空閒。「應接不暇」形容景物繁多，來不及觀賞。語出南朝宋．劉義慶《世說新語．言語》。後亦用「應接不暇」比喻事情繁忙，難以應付。', '暇，空閒。「應接不暇」形容景物繁多，來不及觀賞。語出南朝宋．劉義慶《世說新語．言語》。後亦用「應接不暇」比喻事情繁忙，難以應付。 △「目不暇給」', '形容景物繁多，來不及觀賞。＆比喻事情繁忙，難以應付。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '剛到日月潭，山光水景應接不暇的就迎面而來，令人陶醉。', '剛到日月潭，山光水景應接不暇的就迎面而來，令人陶醉。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"217"}'::jsonb)
  ,('active', '鞠躬盡瘁', 'ㄐㄩˊ ㄍㄨㄥ ㄐㄧㄣˋ ㄘㄨㄟˋ', '成語', 3, '「鞠躬」，彎身以示敬慎。語出《論語．鄉黨》。「盡瘁」，竭盡辛勞。語出《詩經．小雅．北山》。「鞠躬盡瘁」意謂恭謹戒慎，不辭勞病地貢獻心力。或以為典故出自三國蜀．諸葛亮〈後出師表〉。', '「鞠躬」，彎身以示敬慎。語出《論語．鄉黨》。「盡瘁」，竭盡辛勞。語出《詩經．小雅．北山》。「鞠躬盡瘁」意謂恭謹戒慎，不辭勞病地貢獻心力。或以為典故出自三國蜀．諸葛亮〈後出師表〉。 △「摩頂放踵」', '比喻恭敬謹慎，不辭勞病地貢獻心力。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他可以為公事鞠躬盡瘁，犧牲所有假期。', '他可以為公事鞠躬盡瘁，犧牲所有假期。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"218"}'::jsonb)
  ,('active', '愛莫能助', 'ㄞˋ ㄇㄛˋ ㄋㄥˊ ㄓㄨˋ', '成語', 3, '指內心雖然同情，想要幫助卻無能為力。語本《詩經．大雅．烝民》。', '指內心雖然同情，想要幫助卻無能為力。語本《詩經．大雅．烝民》。 △「心有餘而力不足」、「愛莫之助」', '內心雖然同情，想要幫助卻無能為力。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '不是我不願幫忙，實在我自身難保，愛莫能助啊！', '不是我不願幫忙，實在我自身難保，愛莫能助啊！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"219"}'::jsonb)
  ,('active', '洗耳恭聽', 'ㄒㄧˇ ㄦˇ ㄍㄨㄥ ㄊㄧㄥ', '成語', 3, '洗乾淨耳朵恭敬地聆聽，比喻專心恭敬地聆聽。※＃語或出元．鄭廷玉《楚昭公》第四折。', '洗乾淨耳朵恭敬地聆聽，比喻專心恭敬地聆聽。※＃語或出元．鄭廷玉《楚昭公》第四折。 △「傾耳而聽」', '比喻專心恭敬的聆聽。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你有什麼意見可以儘管說，我洗耳恭聽。', '你有什麼意見可以儘管說，我洗耳恭聽。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"220"}'::jsonb)
  ,('active', '不勝枚舉', 'ㄅㄨˋ ㄕㄥ ㄇㄟˊ ㄐㄩˇ', '成語', 3, '勝，音ㄕㄥ，盡。枚，一個一個的。「不勝枚舉」指事物太多，不能一一舉出。＃語本宋．王楙《野客叢書．卷三九．俗語有所自》。', '勝，音ㄕㄥ，盡。枚，一個一個的。「不勝枚舉」指事物太多，不能一一舉出。＃語本宋．王楙《野客叢書．卷三九．俗語有所自》。 △「不可勝數」', '事物太多，不能一一舉出。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '巴黎市區中處處可見街頭藝術家，而且崛起於此地的名人不勝枚舉。', '巴黎市區中處處可見街頭藝術家，而且崛起於此地的名人不勝枚舉。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"221"}'::jsonb)
  ,('active', '不知所措', 'ㄅㄨˋ ㄓ ㄙㄨㄛˇ ㄘㄨㄛˋ', '成語', 3, '「不知所措」之「措」，典源作「錯」。「錯」通「措」。「不知所措」形容人惶恐不安，不知道怎麼辦才好。＃語本《管子．七臣七主》。', '「不知所措」之「措」，典源作「錯」。「錯」通「措」。「不知所措」形容人惶恐不安，不知道怎麼辦才好。＃語本《管子．七臣七主》。 △「手足無措」、「六神無主」', '形容人惶恐不安，不知道怎麼辦才好。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '遇到突發事件要保持冷靜，才不會不知所措。', '遇到突發事件要保持冷靜，才不會不知所措。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"222"}'::jsonb)
  ,('active', '美不勝收', 'ㄇㄟˇ ㄅㄨˋ ㄕㄥ ㄕㄡ', '成語', 3, '勝，音ㄕㄥ，盡。「美不勝收」形容美好的事物太多，無法盡收眼底。※語或出清．袁枚《隨園詩話》卷三。', '勝，音ㄕㄥ，盡。「美不勝收」形容美好的事物太多，無法盡收眼底。※語或出清．袁枚《隨園詩話》卷三。 △「美不勝書」、「琳琅滿目」', '形容美好的事物太多，無法盡收眼底。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '滿園的牡丹花爭奇鬥豔，美不勝收。', '滿園的牡丹花爭奇鬥豔，美不勝收。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"223"}'::jsonb)
  ,('active', '絕無僅有', 'ㄐㄩㄝˊ ㄨˊ ㄐㄧㄣˇ ㄧㄡˇ', '成語', 3, '只此一個，絕無其他。形容極為稀少。※語或出宋．蘇軾〈上神宗皇帝書〉。', '只此一個，絕無其他。形容極為稀少。※語或出宋．蘇軾〈上神宗皇帝書〉。 △「獨一無二」', '形容極為稀少。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這兩床棉被是我絕無僅有的財產了，你要就給你。', '這兩床棉被是我絕無僅有的財產了，你要就給你。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"224"}'::jsonb)
  ,('active', '另眼相看', 'ㄌㄧㄥˋ ㄧㄢˇ ㄒㄧㄤ ㄎㄢˋ', '成語', 3, '以特別的眼光或態度相待，以示重視或歧視。※＃語或出《初刻拍案驚奇》卷八。', '以特別的眼光或態度相待，以示重視或歧視。※＃語或出《初刻拍案驚奇》卷八。 △「刮目相看」', '以特別的眼光或態度相待，以示重視或歧視。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '只要我們有實力，別人自然會另眼相看。', '只要我們有實力，別人自然會另眼相看。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"225"}'::jsonb)
  ,('active', '隔岸觀火', 'ㄍㄜˊ ㄢˋ ㄍㄨㄢ ㄏㄨㄛˇ', '成語', 3, '在河水對岸看火災。※語或本清．梁啟超〈呵旁觀者文〉。比喻事不干己，袖手旁觀，漠不關心。', '在河水對岸看火災。※語或本清．梁啟超〈呵旁觀者文〉。比喻事不干己，袖手旁觀，漠不關心。 △「見死不救」', '比喻事不干己，袖手旁觀，漠不關心。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '要我見死不救、隔岸觀火？我做不到！', '要我見死不救、隔岸觀火？我做不到！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"226"}'::jsonb)
  ,('active', '雷霆萬鈞', 'ㄌㄟˊ ㄊㄧㄥˊ ㄨㄢˋ ㄐㄩㄣ', '成語', 3, '比喻威力強大，勢不可擋。語本漢．賈山〈至言〉。', '比喻威力強大，勢不可擋。語本漢．賈山〈至言〉。 △「排山倒海」', '比喻威力強大，勢不可擋。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '水壩閘門一開，霎時飛瀑怒瀉，雷霆萬鈞。', '水壩閘門一開，霎時飛瀑怒瀉，雷霆萬鈞。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"227"}'::jsonb)
  ,('active', '巧奪天工', 'ㄑㄧㄠˇ ㄉㄨㄛˊ ㄊㄧㄢ ㄍㄨㄥ', '成語', 3, '雖然是人工所製，但是精巧勝過天然。形容技藝巧妙。語本晉．郭璞《葬書．外篇》。', '雖然是人工所製，但是精巧勝過天然。形容技藝巧妙。語本晉．郭璞《葬書．外篇》。 △「出神入化」、「鬼斧神工」', '形容技藝巧妙。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些蠟像栩栩如生，巧奪天工，令人嘆為觀止！', '這些蠟像栩栩如生，巧奪天工，令人嘆為觀止！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"228"}'::jsonb)
  ,('active', '萬紫千紅', 'ㄨㄢˋ ㄗˇ ㄑㄧㄢ ㄏㄨㄥˊ', '成語', 3, '形容百花盛開，色彩絢麗的景象。語出宋．邵雍〈落花吟〉詩。後用「萬紫千紅」比喻事物豐富而多采多姿。', '形容百花盛開，色彩絢麗的景象。語出宋．邵雍〈落花吟〉詩。後用「萬紫千紅」比喻事物豐富而多采多姿。 △「奼紫嫣紅」', '形容百花盛開，色彩絢麗的景象。＆比喻事物豐富而多采多姿。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '春天一到，百花盛開，一片萬紫千紅。', '春天一到，百花盛開，一片萬紫千紅。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"229"}'::jsonb)
  ,('active', '當機立斷', 'ㄉㄤ ㄐㄧ ㄌㄧˋ ㄉㄨㄢˋ', '成語', 3, '當下立刻作出決斷，毫不遲疑。語本三國魏．陳琳〈答東阿王牋〉。', '當下立刻作出決斷，毫不遲疑。語本三國魏．陳琳〈答東阿王牋〉。 △「毅然決然」', '當下立刻作出決斷，毫不遲疑。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他一見苗頭不對，便當機立斷，拔退就跑。', '他一見苗頭不對，便當機立斷，拔退就跑。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"230"}'::jsonb)
  ,('active', '綽綽有餘', 'ㄔㄨㄛˋ ㄔㄨㄛˋ ㄧㄡˇ ㄩˊ', '成語', 3, '「綽綽有餘」之「有餘」，典源作「有裕」。綽綽，寬裕貌。指恩義情厚。語本《詩經．小雅．角弓》。後用「綽綽有餘」形容各方面非常寬裕，足以應付所需。', '「綽綽有餘」之「有餘」，典源作「有裕」。綽綽，寬裕貌。指恩義情厚。語本《詩經．小雅．角弓》。後用「綽綽有餘」形容各方面非常寬裕，足以應付所需。 △「遊刃有餘」、「綽有餘地」、「綽有餘裕」', '形容各方面非常寬裕，足以應付所需。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '看來時間綽綽有餘，我們可以慢慢吃這頓飯。', '看來時間綽綽有餘，我們可以慢慢吃這頓飯。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"231"}'::jsonb)
  ,('active', '放蕩不羈', 'ㄈㄤˋ ㄉㄤˋ ㄅㄨˋ ㄐㄧ', '成語', 3, '「放蕩」，放縱，行為不加檢束。語出《漢書．卷六五．東方朔傳》。「不羈」，不受拘束。語出《史記．卷八三．魯仲連鄒陽列傳．鄒陽》。「放蕩不羈」原指豪放而不受拘束。後用以形容行為放縱隨便，不加檢點。', '「放蕩」，放縱，行為不加檢束。語出《漢書．卷六五．東方朔傳》。「不羈」，不受拘束。語出《史記．卷八三．魯仲連鄒陽列傳．鄒陽》。「放蕩不羈」原指豪放而不受拘束。後用以形容行為放縱隨便，不加檢點。 △「不拘形跡」、「牛驥同皁」、「放浪形骸」', '指豪放而不受拘束。＆形容行為放縱隨便，不加檢點。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我放蕩不羈慣了，很難適應官場的生活。', '我放蕩不羈慣了，很難適應官場的生活。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"232"}'::jsonb)
  ,('active', '漫不經心', 'ㄇㄢˋ ㄅㄨˋ ㄐㄧㄥ ㄒㄧㄣ', '成語', 3, '「漫不經心」的「心」典源作「意」，「心」與「意」意同。是隨隨便便，不加留意的意思。語本宋．陳亮〈與徐大諫書〉。', '「漫不經心」的「心」典源作「意」，「心」與「意」意同。是隨隨便便，不加留意的意思。語本宋．陳亮〈與徐大諫書〉。 △「漠不關心」', '隨隨便便，不加留意。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他唱著歌，漫不經心地開著車。', '他唱著歌，漫不經心地開著車。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"233"}'::jsonb)
  ,('active', '咎由自取', 'ㄐㄧㄡˋ ㄧㄡˊ ㄗˋ ㄑㄩˇ', '成語', 3, '所有的罪過、災禍都是自己造成的。＃語本《三國志．卷四○．蜀書．劉彭廖李劉魏楊傳》。', '所有的罪過、災禍都是自己造成的。＃語本《三國志．卷四○．蜀書．劉彭廖李劉魏楊傳》。 △「自取其咎」、「罪有應得」', '所有的罪過、災禍都是自己造成的。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他會身陷囹圄，完全是咎由自取，不值得同情。', '他會身陷囹圄，完全是咎由自取，不值得同情。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"234"}'::jsonb)
  ,('active', '醉生夢死', 'ㄗㄨㄟˋ ㄕㄥ ㄇㄥˋ ㄙˇ', '成語', 3, '像在酒醉和睡夢中那樣醉醺醺、昏沉沉地過日子。形容生活目的不明確，過得糊裡糊塗。語出宋．程頤〈明道先生行狀〉。', '像在酒醉和睡夢中那樣醉醺醺、昏沉沉地過日子。形容生活目的不明確，過得糊裡糊塗。語出宋．程頤〈明道先生行狀〉。 △「花天酒地」', '比喻人糊裡糊塗或頹廢消沉地活著。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '年輕人要心懷理想，怎可終日過那種醉生夢死的生活呢？', '年輕人要心懷理想，怎可終日過那種醉生夢死的生活呢？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"235"}'::jsonb)
  ,('active', '豁然貫通', 'ㄏㄨㄛˋ ㄖㄢˊ ㄍㄨㄢˋ ㄊㄨㄥ', '成語', 3, '因對事理領悟通曉，而能全盤理解。語出宋．朱熹《四書章句集注．大學章句．五章》。', '因對事理領悟通曉，而能全盤理解。語出宋．朱熹《四書章句集注．大學章句．五章》。 △「恍然大悟」', '因對事理領悟通曉，而能全盤理解。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '經過大師的指點，我對這套魔術的訣竅才豁然貫通。', '經過大師的指點，我對這套魔術的訣竅才豁然貫通。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"236"}'::jsonb)
  ,('active', '夙興夜寐', 'ㄙㄨˋ ㄒㄧㄥ ㄧㄝˋ ㄇㄟˋ', '成語', 3, '早起晚睡。形容終日勤勞。◎語出《詩經．衛風．氓》。', '早起晚睡。形容終日勤勞。◎語出《詩經．衛風．氓》。 △「宵衣旰食」', '形容終日勤勞。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他為了完成學位論文，一年來夙興夜寐，非常辛苦。', '他為了完成學位論文，一年來夙興夜寐，非常辛苦。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"237"}'::jsonb)
  ,('active', '鉤心鬥角', 'ㄍㄡ ㄒㄧㄣ ㄉㄡˋ ㄐㄧㄠˇ', '成語', 3, '形容宮室建築的結構精緻巧妙。語出唐．杜牧〈阿房宮賦〉。後用「鉤心鬥角」比喻詩文的布局結構精心巧製，爭奇鬥勝。亦用於比喻競鬥心機，刻意經營。', '形容宮室建築的結構精緻巧妙。語出唐．杜牧〈阿房宮賦〉。後用「鉤心鬥角」比喻詩文的布局結構精心巧製，爭奇鬥勝。亦用於比喻競鬥心機，刻意經營。 △「明爭暗鬥」、「爾虞我詐」', '比喻競鬥心機，刻意經營。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我不擅長與人鉤心鬥角。', '我不擅長與人鉤心鬥角。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"238"}'::jsonb)
  ,('active', '顛撲不破', 'ㄉㄧㄢ ㄆㄨ ㄅㄨˋ ㄆㄛˋ', '成語', 3, '無論怎麼摔打都不破。比喻理論真確可靠，永遠不能被改易或推翻。◎語出宋．朱熹〈與張欽夫書〉其二。', '無論怎麼摔打都不破。比喻理論真確可靠，永遠不能被改易或推翻。◎語出宋．朱熹〈與張欽夫書〉其二。 △「牢不可破」', '比喻理論真確可靠，永遠不能被改易或推翻。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '達爾文的進化論至今仍舊顛撲不破。', '達爾文的進化論至今仍舊顛撲不破。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"239"}'::jsonb)
  ,('active', '聲淚俱下', 'ㄕㄥ ㄌㄟˋ ㄐㄩˋ ㄒㄧㄚˋ', '成語', 3, '邊說邊哭。形容極度悲慟、激動。語出《晉書．卷七六．王廙列傳》。', '邊說邊哭。形容極度悲慟、激動。語出《晉書．卷七六．王廙列傳》。 △「血淚俱下」、「痛哭流涕」', '形容極度悲慟、激動。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '老先生聲淚俱下的控訴，令人感同身受。', '老先生聲淚俱下的控訴，令人感同身受。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"240"}'::jsonb)
  ,('active', '老奸巨猾', 'ㄌㄠˇ ㄐㄧㄢ ㄐㄩˋ ㄏㄨㄚˊ', '成語', 3, '「老奸巨猾」之「奸」，典源作「姦」。「姦」，義同「奸」。形容人世故老練、極為奸詐狡猾。語本《資治通鑑．卷二一四．唐紀三○．玄宗開元二十四年》。', '「老奸巨猾」之「奸」，典源作「姦」。「姦」，義同「奸」。形容人世故老練、極為奸詐狡猾。語本《資治通鑑．卷二一四．唐紀三○．玄宗開元二十四年》。 △「老謀深算」、「深奸巨猾」', '形容人世故老練、極為奸詐狡猾。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他太老奸巨猾了，你根本不是他的對手。', '他太老奸巨猾了，你根本不是他的對手。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"241"}'::jsonb)
  ,('active', '汗馬功勞', 'ㄏㄢˋ ㄇㄚˇ ㄍㄨㄥ ㄌㄠˊ', '成語', 3, '汗馬，使戰馬辛苦勞累而流汗。「汗馬功勞」指征戰的功勞，亦泛指一般的功勞。＃語本《韓非子．五蠹》。', '汗馬，使戰馬辛苦勞累而流汗。「汗馬功勞」指征戰的功勞，亦泛指一般的功勞。＃語本《韓非子．五蠹》。 △「豐功偉績」', '指征戰的功勞，亦泛指一般的功勞。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '沒有李經理的汗馬功勞，公司哪能有今日的規模？', '沒有李經理的汗馬功勞，公司哪能有今日的規模？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"242"}'::jsonb)
  ,('active', '千載一時', 'ㄑㄧㄢ ㄗㄞˇ ㄧ ㄕˊ', '成語', 3, '千年才有一次的好時機，形容機會十分難得，稍縱即逝。＃語本《戰國策．楚策四》。', '千年才有一次的好時機，形容機會十分難得，稍縱即逝。＃語本《戰國策．楚策四》。 △「千載難逢」、「萬世一時」', '形容機會十分難得，稍縱即逝。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你如果不努力，就算遇到千載一時的機會也無濟於事。', '你如果不努力，就算遇到千載一時的機會也無濟於事。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"243"}'::jsonb)
  ,('active', '光明磊落', 'ㄍㄨㄤ ㄇㄧㄥˊ ㄌㄟˇ ㄌㄨㄛˋ', '成語', 3, '磊落，坦蕩。「光明磊落」形容心地無私，胸懷坦蕩。※語或出《朱子語類．卷七四．易．上繫上》。', '磊落，坦蕩。「光明磊落」形容心地無私，胸懷坦蕩。※語或出《朱子語類．卷七四．易．上繫上》。 △「光明正大」', '形容心地無私，胸懷坦蕩。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他一生做事光明磊落，深受眾人敬仰。', '他一生做事光明磊落，深受眾人敬仰。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"244"}'::jsonb)
  ,('active', '同病相憐', 'ㄊㄨㄥˊ ㄅㄧㄥˋ ㄒㄧㄤ ㄌㄧㄢˊ', '成語', 3, '有同樣不幸遭遇的人互相同情。語出漢．趙曄《吳越春秋．闔閭內傳》。', '有同樣不幸遭遇的人互相同情。語出漢．趙曄《吳越春秋．闔閭內傳》。 △「同憂相救」、「物傷其類」', '有同樣不幸遭遇的人互相同情。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這對同病相憐的朋友，總是甘苦與共，感情十分深厚。', '這對同病相憐的朋友，總是甘苦與共，感情十分深厚。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"245"}'::jsonb)
  ,('active', '生龍活虎', 'ㄕㄥ ㄌㄨㄥˊ ㄏㄨㄛˊ ㄏㄨˇ', '成語', 3, '像有活力的龍虎一般，比喻活潑勇猛，生氣勃勃。※語或出《朱子語類．卷九五．程子之書》。', '像有活力的龍虎一般，比喻活潑勇猛，生氣勃勃。※語或出《朱子語類．卷九五．程子之書》。 △「龍騰虎躍」', '比喻活潑勇猛，生氣勃勃。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '球場上的同學們個個生龍活虎。', '球場上的同學們個個生龍活虎。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"246"}'::jsonb)
  ,('active', '同床異夢', 'ㄊㄨㄥˊ ㄔㄨㄤˊ ㄧˋ ㄇㄥˋ', '成語', 3, '睡在同一張床上但各做各的夢，比喻共同生活或一起做事的人意見不同，各有各的打算。＃語本宋．陳亮〈又乙巳春書之一〉。', '睡在同一張床上但各做各的夢，比喻共同生活或一起做事的人意見不同，各有各的打算。＃語本宋．陳亮〈又乙巳春書之一〉。 △「分床同夢」、「同室異夢」、「異榻同夢」、「貌合神離」', '比喻共同生活或一起做事的人意見不同，各有各的打算。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這兩個合夥人早已經同床異夢，早晚要拆夥的。', '這兩個合夥人早已經同床異夢，早晚要拆夥的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"247"}'::jsonb)
  ,('active', '出其不意', 'ㄔㄨ ㄑㄧˊ ㄅㄨˋ ㄧˋ', '成語', 3, '趁敵人沒有防備之時出兵。語出《孫子．計篇》。後用「出其不意」指趁人不備，出乎對方意料之外。', '趁敵人沒有防備之時出兵。語出《孫子．計篇》。後用「出其不意」指趁人不備，出乎對方意料之外。 △「出人意表」、「攻其無備」', '指趁人不備，出乎對方意料之外。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '採取出其不意的行動，給予敵人沉重的打擊。', '採取出其不意的行動，給予敵人沉重的打擊。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"248"}'::jsonb)
  ,('active', '不知所云', 'ㄅㄨˋ ㄓ ㄙㄨㄛˇ ㄩㄣˊ', '成語', 3, '言語模糊或內容空洞，無法得知意旨為何。語出三國蜀．諸葛亮〈出師表〉。', '言語模糊或內容空洞，無法得知意旨為何。語出三國蜀．諸葛亮〈出師表〉。 △「語無倫次」', '言語模糊或內容空洞，無法得知意旨為何。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '一本好的書絕對條理清晰，不會讓人不知所云。', '一本好的書絕對條理清晰，不會讓人不知所云。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"249"}'::jsonb)
  ,('active', '不言而喻', 'ㄅㄨˋ ㄧㄢˊ ㄦˊ ㄩˋ', '成語', 3, '事態明顯，不待說明即可曉悟。語出《孟子．盡心上》。', '事態明顯，不待說明即可曉悟。語出《孟子．盡心上》。 △「顯而易見」', '事態明顯，不待說明即可曉悟。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他老年得子，快樂的心情自是不言而喻。', '他老年得子，快樂的心情自是不言而喻。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"250"}'::jsonb)
  ,('active', '不苟言笑', 'ㄅㄨˋ ㄍㄡˇ ㄧㄢˊ ㄒㄧㄠˋ', '成語', 3, '苟，隨便。「不苟言笑」指不隨便談笑，態度嚴肅。語本《禮記．曲禮上》。', '苟，隨便。「不苟言笑」指不隨便談笑，態度嚴肅。語本《禮記．曲禮上》。 △「一本正經」', '不隨便談笑，態度嚴肅。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他平日不苟言笑，很少與人閒聊。', '他平日不苟言笑，很少與人閒聊。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"251"}'::jsonb)
  ,('active', '大驚小怪', 'ㄉㄚˋ ㄐㄧㄥ ㄒㄧㄠˇ ㄍㄨㄞˋ', '成語', 3, '形容為一些不足為奇的小事而過分聲張、驚怪。※語或出宋．朱熹〈答林擇之〉其一四。', '形容為一些不足為奇的小事而過分聲張、驚怪。※語或出宋．朱熹〈答林擇之〉其一四。 △「少見多怪」', '形容為一些不足為奇的小事而過分聲張、驚怪。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '東西用久了難免會壞，燈泡不亮，不用這麼大驚小怪。', '東西用久了難免會壞，燈泡不亮，不用這麼大驚小怪。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"252"}'::jsonb)
  ,('active', '手足無措', 'ㄕㄡˇ ㄗㄨˊ ㄨˊ ㄘㄨㄛˋ', '成語', 3, '「不知所措」之「措」，典源作「錯」。「錯」通「措」。「手足無措」指手腳無處安放。形容人惶恐不安，不知如何是好。＃語本《論語．子路》。', '「不知所措」之「措」，典源作「錯」。「錯」通「措」。「手足無措」指手腳無處安放。形容人惶恐不安，不知如何是好。＃語本《論語．子路》。 △「不知所措」、「六神無主」、「名正言順」', '形容人惶恐不安，不知如何是好。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '喜歡朝令夕改的主管，常常使得下屬手足無措。', '喜歡朝令夕改的主管，常常使得下屬手足無措。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"253"}'::jsonb)
  ,('active', '屈指可數', 'ㄑㄩ ㄓˇ ㄎㄜˇ ㄕㄨˇ', '成語', 3, '彎曲手指可計數，形容數量很少。語本《三國志．卷一七．魏書．張樂于張徐傳．張郃》。', '彎曲手指可計數，形容數量很少。語本《三國志．卷一七．魏書．張樂于張徐傳．張郃》。 △「寥若晨星」、「寥寥無幾」', '形容數量很少。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '今天到場的親友沒幾個，屈指可數。', '今天到場的親友沒幾個，屈指可數。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"254"}'::jsonb)
  ,('active', '眉飛色舞', 'ㄇㄟˊ ㄈㄟ ㄙㄜˋ ㄨˇ', '成語', 3, '形容非常喜悅得意的神情。※語或出清．梁章鉅《浪跡叢談．卷二．少穆尚書贈聯》。', '形容非常喜悅得意的神情。※語或出清．梁章鉅《浪跡叢談．卷二．少穆尚書贈聯》。 △「眉開眼笑」', '形容非常喜悅得意的神情。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '最近小琪總是滿臉笑容，眉飛色舞，準是好事近了！', '最近小琪總是滿臉笑容，眉飛色舞，準是好事近了！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"255"}'::jsonb)
  ,('active', '洗心革面', 'ㄒㄧˇ ㄒㄧㄣ ㄍㄜˊ ㄇㄧㄢˋ', '成語', 3, '「洗心」，洗滌心胸，摒除惡念或雜念。語出《易經．繫辭上》。「革面」，改變面目。語出《易經．革卦》。「洗心革面」指除去邪思雜念，改變舊日面目；比喻澈底悔悟，改過遷善。', '「洗心」，洗滌心胸，摒除惡念或雜念。語出《易經．繫辭上》。「革面」，改變面目。語出《易經．革卦》。「洗心革面」指除去邪思雜念，改變舊日面目；比喻澈底悔悟，改過遷善。 △「脫胎換骨」', '比喻澈底悔悟，改過遷善。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '出獄後，他決定洗心革面，重新做人。', '出獄後，他決定洗心革面，重新做人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"256"}'::jsonb)
  ,('active', '飛黃騰達', 'ㄈㄟ ㄏㄨㄤˊ ㄊㄥˊ ㄉㄚˊ', '成語', 3, '比喻得意於仕途。語本唐．韓愈〈符讀書城南〉詩。', '比喻得意於仕途。語本唐．韓愈〈符讀書城南〉詩。 △「扶搖直上」、「青雲直上」', '比喻仕途得意，很快到達高位。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他本來沒沒無聞，因為受到長官的賞識，從此飛黃騰達起來。', '他本來沒沒無聞，因為受到長官的賞識，從此飛黃騰達起來。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"257"}'::jsonb)
  ,('active', '紙醉金迷', 'ㄓˇ ㄗㄨㄟˋ ㄐㄧㄣ ㄇㄧˊ', '成語', 3, '絢麗燦爛的金飾紙光令人迷醉。形容絢爛奪目。語本宋．陶穀《清異錄．卷下．居室門．金迷紙醉》。後用「紙醉金迷」比喻奢侈浮華的享樂生活。', '絢麗燦爛的金飾紙光令人迷醉。形容絢爛奪目。語本宋．陶穀《清異錄．卷下．居室門．金迷紙醉》。後用「紙醉金迷」比喻奢侈浮華的享樂生活。 △「燈紅酒綠」', '比喻奢侈浮華的享樂生活。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '仗著祖先留下的產業，他每天紙醉金迷，不思振作。', '仗著祖先留下的產業，他每天紙醉金迷，不思振作。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"258"}'::jsonb)
  ,('active', '烏合之眾', 'ㄨ ㄏㄜˊ ㄓ ㄓㄨㄥˋ', '成語', 3, '像烏鴉般聚在一起的一群人。比喻暫時湊合，無組織、無紀律的一群人。語出《管子》逸文。', '像烏鴉般聚在一起的一群人。比喻暫時湊合，無組織、無紀律的一群人。語出《管子》逸文。 △「一盤散沙」', '比喻暫時湊合，無組織、無紀律的一群人。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '一群沒有組織的烏合之眾，是成不了大事的。', '一群沒有組織的烏合之眾，是成不了大事的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"259"}'::jsonb)
  ,('active', '逆來順受', 'ㄋㄧˋ ㄌㄞˊ ㄕㄨㄣˋ ㄕㄡˋ', '成語', 3, '以順從的態度接受惡劣環境或不合理的待遇。語本宋．陳錄《善誘文．對治十常》。', '以順從的態度接受惡劣環境或不合理的待遇。語本宋．陳錄《善誘文．對治十常》。 △「委曲求全」', '以順從的態度接受惡劣環境或不合理的待遇。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在悲觀的宿命論影響下，她對於任何事都逆來順受。', '在悲觀的宿命論影響下，她對於任何事都逆來順受。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"260"}'::jsonb)
  ,('active', '啞口無言', 'ㄧㄚˇ ㄎㄡˇ ㄨˊ ㄧㄢˊ', '成語', 3, '遭人質問或駁斥時沉默不語或無言以對。※◎語或出《醒世恆言．卷八．喬太守亂點鴛鴦譜》。', '遭人質問或駁斥時沉默不語或無言以對。※◎語或出《醒世恆言．卷八．喬太守亂點鴛鴦譜》。 △「張口結舌」、「緘舌閉口」', '遭人質問或駁斥時沉默不語或無言以對。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這句話說得他滿臉通紅，羞愧萬分，啞口無言。', '這句話說得他滿臉通紅，羞愧萬分，啞口無言。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"261"}'::jsonb)
  ,('active', '等量齊觀', 'ㄉㄥˇ ㄌㄧㄤˋ ㄑㄧˊ ㄍㄨㄢ', '成語', 3, '不分輕重，一律同等看待。※＃語或出清．況周頤《蕙風詞話．卷三．劉仲尹參涪翁得法》。', '不分輕重，一律同等看待。※＃語或出清．況周頤《蕙風詞話．卷三．劉仲尹參涪翁得法》。 △「相提並論」', '不分輕重，一律同等看待。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '雞鶩與鳳雛，豈能等量齊觀？', '雞鶩與鳳雛，豈能等量齊觀？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"262"}'::jsonb)
  ,('active', '荒謬絕倫', 'ㄏㄨㄤ ㄇㄧㄡˋ ㄐㄩㄝˊ ㄌㄨㄣˊ', '成語', 3, '形容荒唐、錯誤到了極點。※＃語或出《掃迷帚》第三回。', '形容荒唐、錯誤到了極點。※＃語或出《掃迷帚》第三回。 △「荒誕不經」', '形容荒唐、錯誤到了極點。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '誰都知道這麼做是荒謬絕倫的，你怎麼會答應他呢？', '誰都知道這麼做是荒謬絕倫的，你怎麼會答應他呢？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"263"}'::jsonb)
  ,('active', '深惡痛絕', 'ㄕㄣ ㄨˋ ㄊㄨㄥˋ ㄐㄩㄝˊ', '成語', 3, '厭惡、痛恨到極點。※語或出宋．朱熹《四書章句集注．孟子集注．盡心下》。', '厭惡、痛恨到極點。※語或出宋．朱熹《四書章句集注．孟子集注．盡心下》。 △「深懲痛絕」、「痛心疾首」', '厭惡、痛恨到極點。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我對那種虛情假意的人，深惡痛絕。', '我對那種虛情假意的人，深惡痛絕。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"264"}'::jsonb)
  ,('active', '殊途同歸', 'ㄕㄨ ㄊㄨˊ ㄊㄨㄥˊ ㄍㄨㄟ', '成語', 3, '「殊途同歸」之「途」，典源作「塗」。「塗」通「途」。比喻採取的方法雖不同，所得的結果卻相同。語本《易經．繫辭下》。', '「殊途同歸」之「途」，典源作「塗」。「塗」通「途」。比喻採取的方法雖不同，所得的結果卻相同。語本《易經．繫辭下》。 △「異曲同工」', '比喻採取的方法雖不同，所得的結果卻相同。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我們追求的目標一致，所以不論採用何種方法，最後都是殊途同歸。', '我們追求的目標一致，所以不論採用何種方法，最後都是殊途同歸。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"265"}'::jsonb)
  ,('active', '千變萬化', 'ㄑㄧㄢ ㄅㄧㄢˋ ㄨㄢˋ ㄏㄨㄚˋ', '成語', 3, '形容變化無窮。＃◎語出《列子．周穆王》。', '形容變化無窮。＃◎語出《列子．周穆王》。 △「瞬息萬變」', '形容變化無窮。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '魔術師的表演千變萬化，讓人嘆為觀止。', '魔術師的表演千變萬化，讓人嘆為觀止。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"266"}'::jsonb)
  ,('active', '得不償失', 'ㄉㄜˊ ㄅㄨˋ ㄔㄤˊ ㄕ', '成語', 3, '表示所得不足以抵補所失。語本《後漢書．卷八七．西羌傳》。', '表示所得不足以抵補所失。語本《後漢書．卷八七．西羌傳》。 △「貪小失大」', '表示所得不足以抵補所失。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你老想占人家小便宜，小心會得不償失。', '你老想占人家小便宜，小心會得不償失。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"267"}'::jsonb)
  ,('active', '冥頑不靈', 'ㄇㄧㄥˊ ㄨㄢˊ ㄅㄨˋ ㄌㄧㄥˊ', '成語', 3, '愚昧頑固而不通靈性。語出唐．韓愈〈祭鱷魚文〉。', '愚昧頑固而不通靈性。語出唐．韓愈〈祭鱷魚文〉。 △「執迷不悟」', '愚昧頑固而不通靈性。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他是個冥頑不靈的人，你就是再勸也沒用。', '他是個冥頑不靈的人，你就是再勸也沒用。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"268"}'::jsonb)
  ,('active', '望洋興嘆', 'ㄨㄤˋ ㄧㄤˊ ㄒㄧㄥ ㄊㄢˋ', '成語', 3, '望洋，抬頭看的意思。形容因驚奇而仰視發出驚嘆。語本《莊子．秋水》。後用「望洋興嘆」比喻因能力不足而自嘆不如或感到無可奈何。', '望洋，抬頭看的意思。形容因驚奇而仰視發出驚嘆。語本《莊子．秋水》。後用「望洋興嘆」比喻因能力不足而自嘆不如或感到無可奈何。 △「無可奈何」、「貽笑大方」', '比喻因力量不夠而感到無可奈何。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '高級轎車的價格，往往使一般老百姓望洋興嘆！', '高級轎車的價格，往往使一般老百姓望洋興嘆！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"269"}'::jsonb)
  ,('active', '嬌生慣養', 'ㄐㄧㄠ ㄕㄥ ㄍㄨㄢˋ ㄧㄤˇ', '成語', 3, '在備受寵愛縱容中成長。※語或出《醒世姻緣傳》第五七回。', '在備受寵愛縱容中成長。※語或出《醒世姻緣傳》第五七回。 △「養尊處優」', '在備受寵愛縱容中成長。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他從小嬌生慣養，所以相當任性而不顧別人。', '他從小嬌生慣養，所以相當任性而不顧別人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"270"}'::jsonb)
  ,('active', '養精蓄銳', 'ㄧㄤˇ ㄐㄧㄥ ㄒㄩˋ ㄖㄨㄟˋ', '成語', 3, '保養精神，積蓄力量。※語或本唐．符載〈上巳日陪劉尚書宴集北池序〉。', '保養精神，積蓄力量。※語或本唐．符載〈上巳日陪劉尚書宴集北池序〉。 △「休養生息」、「養威蓄銳」', '保養精神，積蓄力量。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這支軍隊經過養精蓄銳後，戰鬥力更強了。', '這支軍隊經過養精蓄銳後，戰鬥力更強了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"271"}'::jsonb)
  ,('active', '陽奉陰違', 'ㄧㄤˊ ㄈㄥˋ ㄧㄣ ㄨㄟˊ', '成語', 3, '陽，表面上；陰，暗地裡。「陽奉陰違」指表面上裝著遵守奉行，暗地裡卻違反不照辦。語出明．范景文〈革大戶行召募疏〉。', '陽，表面上；陰，暗地裡。「陽奉陰違」指表面上裝著遵守奉行，暗地裡卻違反不照辦。語出明．范景文〈革大戶行召募疏〉。 △「口是心非」', '表面上裝著遵守奉行，暗地裡卻違反不照辦。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '公務人員應該依法行事，不可陽奉陰違。', '公務人員應該依法行事，不可陽奉陰違。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"272"}'::jsonb)
  ,('active', '懷才不遇', 'ㄏㄨㄞˊ ㄘㄞˊ ㄅㄨˋ ㄩˋ', '成語', 3, '懷有才能卻際遇不佳，不受重用。※語或出《喻世明言．卷五．窮馬周遭際賣䭔媼》。', '懷有才能卻際遇不佳，不受重用。※語或出《喻世明言．卷五．窮馬周遭際賣䭔媼》。 △「英雄無用武之地」', '懷有才能卻際遇不佳，不受重用。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他一生懷才不遇，最後抑鬱以終。', '他一生懷才不遇，最後抑鬱以終。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"273"}'::jsonb)
  ,('active', '連篇累牘', 'ㄌㄧㄢˊ ㄆㄧㄢ ㄌㄟˇ ㄉㄨˊ', '成語', 3, '牘，古代用以書寫文字的木片。「連篇累牘」指寫字用的竹簡、木片編串堆積在一起。形容文章篇幅冗長。＃語出《隋書．卷六六．李諤列傳》。', '牘，古代用以書寫文字的木片。「連篇累牘」指寫字用的竹簡、木片編串堆積在一起。形容文章篇幅冗長。＃語出《隋書．卷六六．李諤列傳》。 △「長篇大論」', '形容文章篇幅冗長。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '讀者對短文的喜愛，勝過那些連篇累牘的長文。', '讀者對短文的喜愛，勝過那些連篇累牘的長文。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"274"}'::jsonb)
  ,('active', '並駕齊驅', 'ㄅㄧㄥˋ ㄐㄧㄚˋ ㄑㄧˊ ㄑㄩ', '成語', 3, '多匹馬並排駕車，齊頭奔馳。語出南朝宋．劉勰《文心雕龍．附會》。後用「並駕齊驅」比喻彼此實力相當，不分軒輊。', '多匹馬並排駕車，齊頭奔馳。語出南朝宋．劉勰《文心雕龍．附會》。後用「並駕齊驅」比喻彼此實力相當，不分軒輊。 △「不相上下」、「齊足並驅」', '並排駕車，齊頭奔馳。＆比喻彼此實力相當，不分軒輊。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他倆騎著腳踏車並駕齊驅地通過草原，前往下一個村莊。', '他倆騎著腳踏車並駕齊驅地通過草原，前往下一個村莊。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"275"}'::jsonb)
  ,('active', '起死回生', 'ㄑㄧˇ ㄙˇ ㄏㄨㄟˊ ㄕㄥ', '成語', 3, '使瀕死的人復生。語本《史記．卷一○五．扁鵲倉公列傳．扁鵲》。後用「起死回生」比喻毫無希望的情勢扭轉過來。', '使瀕死的人復生。語本《史記．卷一○五．扁鵲倉公列傳．扁鵲》。後用「起死回生」比喻毫無希望的情勢扭轉過來。 △「妙手回春」、「著手成春」', '使瀕死的人復生。＆比喻毫無希望的情勢扭轉過來。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '傳說華佗是位名醫，有起死回生之術。', '傳說華佗是位名醫，有起死回生之術。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"276"}'::jsonb)
  ,('active', '大名鼎鼎', 'ㄉㄚˋ ㄇㄧㄥˊ ㄉㄧㄥˇ ㄉㄧㄥˇ', '成語', 3, '鼎鼎，盛大貌。「大名鼎鼎」形容人的名氣聲望很大。※語或出《官場現形記》第二四回。', '鼎鼎，盛大貌。「大名鼎鼎」形容人的名氣聲望很大。※語或出《官場現形記》第二四回。 △「赫赫有名」', '形容人的名氣聲望很大。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他是當今文壇上大名鼎鼎的作家。', '他是當今文壇上大名鼎鼎的作家。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"277"}'::jsonb)
  ,('active', '大智若愚', 'ㄉㄚˋ ㄓˋ ㄖㄨㄛˋ ㄩˊ', '成語', 3, '指具有極高智慧的人，往往表面上看起來似乎愚笨。語本宋．蘇軾〈賀歐陽少師致仕啟〉。', '指具有極高智慧的人，往往表面上看起來似乎愚笨。語本宋．蘇軾〈賀歐陽少師致仕啟〉。 △「大巧若拙」、「大勇若怯」', '表示具有極高智慧的人，往往表面上看起來似乎愚笨。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位長者的為人處世，令人有一種大智若愚的感覺。', '這位長者的為人處世，令人有一種大智若愚的感覺。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"278"}'::jsonb)
  ,('active', '錦囊妙計', 'ㄐㄧㄣˇ ㄋㄤˊ ㄇㄧㄠˋ ㄐㄧˋ', '成語', 3, '封裝在錦囊裡的神妙計策。比喻預先規劃以應付意外、解決危急的有效方法。語本《三國演義》第五四回。', '封裝在錦囊裡的神妙計策。比喻預先規劃以應付意外、解決危急的有效方法。語本《三國演義》第五四回。 △「神機妙算」、「錦囊訣」', '比喻預先規劃以應付意外、解決危急的有效方法。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '靠著他的錦囊妙計，我們總算化解了危機。', '靠著他的錦囊妙計，我們總算化解了危機。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"279"}'::jsonb)
  ,('active', '一目了然', 'ㄧ ㄇㄨˋ ㄌㄧㄠˇ ㄖㄢˊ', '成語', 3, '看一眼就完全清楚明白。語本《朱子語類．卷一三七．戰國漢唐諸子》。', '看一眼就完全清楚明白。語本《朱子語類．卷一三七．戰國漢唐諸子》。 △「一覽無遺」', '看一眼就完全清楚明白。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這張設計圖畫得十分詳細，即使外行人看了也會一目了然。', '這張設計圖畫得十分詳細，即使外行人看了也會一目了然。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"280"}'::jsonb)
  ,('active', '五光十色', 'ㄨˇ ㄍㄨㄤ ㄕˊ ㄙㄜˋ', '成語', 3, '形容景色鮮麗複雜，光彩奪目。語本南朝梁．江淹〈麗色賦〉。後亦用「五光十色」比喻內容豐富，變化萬端。', '形容景色鮮麗複雜，光彩奪目。語本南朝梁．江淹〈麗色賦〉。後亦用「五光十色」比喻內容豐富，變化萬端。 △「五彩繽紛」', '形容景色鮮麗複雜，光彩奪目。＆比喻內容豐富，變化萬端。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '夕照彩霞，映得湖面五光十色，非常好看。', '夕照彩霞，映得湖面五光十色，非常好看。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"281"}'::jsonb)
  ,('active', '年高德劭', 'ㄋㄧㄢˊ ㄍㄠ ㄉㄜˊ ㄕㄠˋ', '成語', 3, '「年高德劭」之「劭」，典源作「邵」。「邵」通「劭」。「年高德劭」指年紀大而品德好。語本漢．揚雄《法言．孝至》。', '「年高德劭」之「劭」，典源作「邵」。「邵」通「劭」。「年高德劭」指年紀大而品德好。語本漢．揚雄《法言．孝至》。 △「德高望重」', '指年紀大而品德好。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '來賓當中，張先生年高德劭，理當就上座。', '來賓當中，張先生年高德劭，理當就上座。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"282"}'::jsonb)
  ,('active', '快馬加鞭', 'ㄎㄨㄞˋ ㄇㄚˇ ㄐㄧㄚ ㄅㄧㄢ', '成語', 3, '對跑很快的馬，再加以鞭策，使牠跑得更快。形容快上加快。語本宋．王安石〈送純甫如江南〉詩。', '對跑很快的馬，再加以鞭策，使牠跑得更快。形容快上加快。語本宋．王安石〈送純甫如江南〉詩。 △「馬不停蹄」', '形容快上加快。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '下午就要開會了，請你快馬加鞭把報告趕出來。', '下午就要開會了，請你快馬加鞭把報告趕出來。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"283"}'::jsonb)
  ,('active', '志同道合', 'ㄓˋ ㄊㄨㄥˊ ㄉㄠˋ ㄏㄜˊ', '成語', 3, '彼此的志趣和理想一致。＃語本漢．王充《論衡．逢遇》。', '彼此的志趣和理想一致。＃語本漢．王充《論衡．逢遇》。 △「合志同方」、「情投意合」', '彼此的志趣和理想一致。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '小陳和我是志同道合的好朋友。', '小陳和我是志同道合的好朋友。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"284"}'::jsonb)
  ,('active', '冷言冷語', 'ㄌㄥˇ ㄧㄢˊ ㄌㄥˇ ㄩˇ', '成語', 3, '含有譏諷意味的冷冰冰的話。語出《虛堂和尚語錄．卷二．婺州雲黃山寶林禪寺語錄》。', '含有譏諷意味的冷冰冰的話。語出《虛堂和尚語錄．卷二．婺州雲黃山寶林禪寺語錄》。 △「冷嘲熱諷」', '含有譏諷意味的冷冰冰的話。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你老對別人冷言冷語的，難怪人緣會不好。', '你老對別人冷言冷語的，難怪人緣會不好。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"285"}'::jsonb)
  ,('active', '流言蜚語', 'ㄌㄧㄡˊ ㄧㄢˊ ㄈㄟ ㄩˇ', '成語', 3, '「流言」和「蜚語」義同，都是指沒有根據的話，用於毀謗他人。＃「流言」語出《書經．金縢》。「蜚語」語本《鶡冠子．武靈王》。「流言蜚語」本指製造不實的傳言，用來詆毀他人。後泛指謠言。「蜚」亦作「飛」。', '「流言」和「蜚語」義同，都是指沒有根據的話，用於毀謗他人。＃「流言」語出《書經．金縢》。「蜚語」語本《鶡冠子．武靈王》。「流言蜚語」本指製造不實的傳言，用來詆毀他人。後泛指謠言。「蜚」亦作「飛」。 △「風言風語」', '泛指謠言。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些人不斷地散布流言蜚語，真令人討厭。', '這些人不斷地散布流言蜚語，真令人討厭。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"286"}'::jsonb)
  ,('active', '殺人越貨', 'ㄕㄚ ㄖㄣˊ ㄩㄝˋ ㄏㄨㄛˋ', '成語', 3, '殺人搶劫。語本《書經．康誥》。', '殺人搶劫。語本《書經．康誥》。 △「謀財害命」', '殺人搶劫。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這個刑犯因為殺人越貨，而被判處死刑。', '這個刑犯因為殺人越貨，而被判處死刑。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"287"}'::jsonb)
  ,('active', '銳不可當', 'ㄖㄨㄟˋ ㄅㄨˋ ㄎㄜˇ ㄉㄤˇ', '成語', 3, '「銳不可當」的「銳」，典源作「鋒」。形容氣勢威猛，所向無敵。※語或本《史記．卷九二．淮陰侯列傳》。', '「銳不可當」的「銳」，典源作「鋒」。形容氣勢威猛，所向無敵。※語或本《史記．卷九二．淮陰侯列傳》。 △「勢不可當」、「勢如破竹」', '形容氣勢威猛，所向無敵。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我們球隊有銳不可當的實力，奪魁有望。', '我們球隊有銳不可當的實力，奪魁有望。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"288"}'::jsonb)
  ,('active', '錙銖必較', 'ㄗ ㄓㄨ ㄅㄧˋ ㄐㄧㄠˋ', '成語', 3, '「錙銖必較」，典源作「計較錙銖」。連很少的錢或很小的事情都非常計較。※語或本北齊．顏之推《顏氏家訓．治家》。', '「錙銖必較」，典源作「計較錙銖」。連很少的錢或很小的事情都非常計較。※語或本北齊．顏之推《顏氏家訓．治家》。 △「斤斤計較」', '計較小錢。貶義。＆形容對很小的事十分計較。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這間公司對職員的薪水錙銖必較，請個病假也要扣錢。', '這間公司對職員的薪水錙銖必較，請個病假也要扣錢。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"289"}'::jsonb)
  ,('active', '苦心孤詣', 'ㄎㄨˇ ㄒㄧㄣ ㄍㄨ ㄧˋ', '成語', 3, '費盡心思，專心研究，達到他人所無法達到的境地。※語本清．屈復〈論詩絕句〉二四首之一三。', '費盡心思，專心研究，達到他人所無法達到的境地。※語本清．屈復〈論詩絕句〉二四首之一三。 △「煞費苦心」', '指費盡心思，專心研究，達到他人所無法達到的境地。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這部小說是這位大作家的苦心孤詣之作。', '這部小說是這位大作家的苦心孤詣之作。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"290"}'::jsonb)
  ,('active', '刻骨銘心', 'ㄎㄜˋ ㄍㄨˇ ㄇㄧㄥˊ ㄒㄧㄣ', '成語', 3, '刻在骨頭，刻在心上。形容感受深刻，難以忘懷。語本唐．李白〈上安州李長史書〉。', '刻在骨頭，刻在心上。形容感受深刻，難以忘懷。語本唐．李白〈上安州李長史書〉。 △「沒齒不忘」、「銘肌鏤骨」', '形容感受深刻，難以忘懷。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你的這番教誨刻骨銘心，讓我永遠不會忘記。', '你的這番教誨刻骨銘心，讓我永遠不會忘記。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"291"}'::jsonb)
  ,('active', '深謀遠慮', 'ㄕㄣ ㄇㄡˊ ㄩㄢˇ ㄌㄩˋ', '成語', 3, '計畫周密而慮事深遠。◎語出漢．賈誼〈過秦論上〉。', '計畫周密而慮事深遠。◎語出漢．賈誼〈過秦論上〉。 △「深思熟慮」', '計畫周密而慮事深遠。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '設立教育基金，是我們深謀遠慮後所作的決定。', '設立教育基金，是我們深謀遠慮後所作的決定。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"292"}'::jsonb)
  ,('active', '魂不附體', 'ㄏㄨㄣˊ ㄅㄨˋ ㄈㄨˋ ㄊㄧˇ', '成語', 3, '魂魄脫離肉體。語本《南史．卷三二．徐嗣伯列傳》。後用「魂不附體」形容驚嚇過度而心不能自主。', '魂魄脫離肉體。語本《南史．卷三二．徐嗣伯列傳》。後用「魂不附體」形容驚嚇過度而心不能自主。 △「魂飛魄散」', '形容驚嚇過度而心不能自主。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '突然發生地震，天搖地動的，每個人都嚇得魂不附體。', '突然發生地震，天搖地動的，每個人都嚇得魂不附體。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"293"}'::jsonb)
  ,('active', '入不敷出', 'ㄖㄨˋ ㄅㄨˋ ㄈㄨ ㄔㄨ', '成語', 3, '敷，足夠。收入不夠支出。※語或出清．朱彝尊《竹垞詩話．卷下．臣士下．倪嘉慶》。', '敷，足夠。收入不夠支出。※語或出清．朱彝尊《竹垞詩話．卷下．臣士下．倪嘉慶》。 △「寅吃卯糧」', '收入不夠支出。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '開源節流是避免入不敷出的最好方法。', '開源節流是避免入不敷出的最好方法。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"294"}'::jsonb)
  ,('active', '十全十美', 'ㄕˊ ㄑㄩㄢˊ ㄕˊ ㄇㄟˇ', '成語', 3, '十全，指治療十個人，十個人都能痊癒。※語或本《周禮．天官冢宰下．醫師》。後用「十全十美」比喻圓滿美好毫無缺陷的境界。', '十全，指治療十個人，十個人都能痊癒。※語或本《周禮．天官冢宰下．醫師》。後用「十全十美」比喻圓滿美好毫無缺陷的境界。 △「盡善盡美」', '比喻圓滿美好毫無缺陷的境界。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這部作品絕非十全十美，仍有改進的空間。', '這部作品絕非十全十美，仍有改進的空間。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"295"}'::jsonb)
  ,('active', '人山人海', 'ㄖㄣˊ ㄕㄢ ㄖㄣˊ ㄏㄞˇ', '成語', 3, '人群如山海般眾多，無法估計，形容人聚集得非常多。※語或出宋．西湖老人《西湖老人繁勝錄．諸行市》。', '人群如山海般眾多，無法估計，形容人聚集得非常多。※語或出宋．西湖老人《西湖老人繁勝錄．諸行市》。 △「萬人空巷」', '形容人聚集得非常多。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '花季時的陽明山，天天是人山人海。', '花季時的陽明山，天天是人山人海。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"296"}'::jsonb)
  ,('active', '無微不至', 'ㄨˊ ㄨㄟˊ ㄅㄨˋ ㄓˋ', '成語', 3, '沒有細節不照顧到的，形容做事非常細心周到。靡，無。語本宋．魏了翁〈辭免督視軍馬乞以參贊軍事從丞相行奏劄〉。', '沒有細節不照顧到的，形容做事非常細心周到。靡，無。語本宋．魏了翁〈辭免督視軍馬乞以參贊軍事從丞相行奏劄〉。 △「無所不至」', '形容做事非常細心周到。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '老王對待朋友無微不至，所以人緣極好。', '老王對待朋友無微不至，所以人緣極好。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"297"}'::jsonb)
  ,('active', '不遺餘力', 'ㄅㄨˋ ㄧˊ ㄩˊ ㄌㄧˋ', '成語', 3, '不保留一點力氣。形容竭盡全力，毫無保留。語出《戰國策．趙策三》。', '不保留一點力氣。形容竭盡全力，毫無保留。語出《戰國策．趙策三》。 △「盡心竭力」', '形容竭盡全力，毫無保留。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '王老師盡心竭志教導學生，不遺餘力。', '王老師盡心竭志教導學生，不遺餘力。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"298"}'::jsonb)
  ,('active', '心平氣和', 'ㄒㄧㄣ ㄆㄧㄥˊ ㄑㄧˋ ㄏㄜˊ', '成語', 3, '心氣平和，不急不怒。語本《左傳．昭公二十年》。', '心氣平和，不急不怒。語本《左傳．昭公二十年》。 △「平心靜氣」', '形容心氣平和，不急不怒。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你們應該心平氣和地互相溝通，才能解決問題。', '你們應該心平氣和地互相溝通，才能解決問題。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"299"}'::jsonb)
  ,('active', '心血來潮', 'ㄒㄧㄣ ㄒㄧㄝˇ ㄌㄞˊ ㄔㄠˊ', '成語', 3, '思緒像浪潮般地突起。原指神仙對人事的感應與預知。※語或出《封神演義》第三四回。後用「心血來潮 」形容突然興起的念頭。', '思緒像浪潮般地突起。原指神仙對人事的感應與預知。※語或出《封神演義》第三四回。後用「心血來潮 」形容突然興起的念頭。 △「靈機一動」', '形容突然興起的念頭。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在回家的路上，我突然心血來潮想買一束花送給妻子。', '在回家的路上，我突然心血來潮想買一束花送給妻子。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"300"}'::jsonb)
  ,('active', '隨遇而安', 'ㄙㄨㄟˊ ㄩˋ ㄦˊ ㄢ', '成語', 3, '指能安於所處的環境。語本《石門文字禪．卷二二．舫齋記》。後亦用「隨遇而安」比喻安於現狀，不思長進。', '指能安於所處的環境。語本《石門文字禪．卷二二．舫齋記》。後亦用「隨遇而安」比喻安於現狀，不思長進。 △「安之若素」', '比喻能安於所處的環境。＆比喻安於現狀，不思長進。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '有智慧的人，雖然處於逆境，仍能隨遇而安。', '有智慧的人，雖然處於逆境，仍能隨遇而安。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"301"}'::jsonb)
  ,('active', '神通廣大', 'ㄕㄣˊ ㄊㄨㄥ ㄍㄨㄤˇ ㄉㄚˋ', '成語', 3, '神通，原為佛教用語，指能清楚明白直接看見，知道一切遠時、遠地各種情況的一種神祕智力。「神通廣大」則指廣大之神力。※語或本《敦煌變文集新書．卷二．維摩詰經講經文》。後用「神通廣大」形容人的本領、手段高明巧妙。', '神通，原為佛教用語，指能清楚明白直接看見，知道一切遠時、遠地各種情況的一種神祕智力。「神通廣大」則指廣大之神力。※語或本《敦煌變文集新書．卷二．維摩詰經講經文》。後用「神通廣大」形容人的本領、手段高明巧妙。 △「三頭六臂」', '形容本領、手段高明巧妙。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '連這種東西你都弄得到，真是神通廣大啊！', '連這種東西你都弄得到，真是神通廣大啊！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"302"}'::jsonb)
  ,('active', '孤苦伶仃', 'ㄍㄨ ㄎㄨˇ ㄌㄧㄥˊ ㄉㄧㄥ', '成語', 3, '「孤苦伶仃」之「伶仃 」，典源作「零丁 」。「零丁 」同「伶仃 」。形容孤單貧苦，無依無助。語本晉．李密〈陳情表〉。', '「孤苦伶仃」之「伶仃 」，典源作「零丁 」。「零丁 」同「伶仃 」。形容孤單貧苦，無依無助。語本晉．李密〈陳情表〉。 △「孑然一身」、「形單影隻」', '形容孤單貧苦，無依無助。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在孤兒院裡，有許多孤苦伶仃的小朋友。', '在孤兒院裡，有許多孤苦伶仃的小朋友。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"303"}'::jsonb)
  ,('active', '名不副實', 'ㄇㄧㄥˊ ㄅㄨˋ ㄈㄨˋ ㄕˊ', '成語', 3, '空有虛名，不合實際。＃語本《漢書．卷九九．王莽傳上》。', '空有虛名，不合實際。＃語本《漢書．卷九九．王莽傳上》。 △「有名無實」', '形容空有虛名，不合實際。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些誇大的廣告名不副實，根本是在欺騙消費者。', '這些誇大的廣告名不副實，根本是在欺騙消費者。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"304"}'::jsonb)
  ,('active', '爾虞我詐', 'ㄦˇ ㄩˊ ㄨㄛˇ ㄓㄚˋ', '成語', 3, '彼此互相詐騙。語本《左傳．宣公十五年》。後用「爾虞我詐」形容人與人之間的互相猜疑，玩弄欺騙手段。', '彼此互相詐騙。語本《左傳．宣公十五年》。後用「爾虞我詐」形容人與人之間的互相猜疑，玩弄欺騙手段。 △「易子而食」、「析骸以爨」、「鉤心鬥角」', '形容人與人之間的互相猜疑，玩弄欺騙手段。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為了利益，商人們經常爾虞我詐。', '為了利益，商人們經常爾虞我詐。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"305"}'::jsonb)
  ,('active', '義正辭嚴', 'ㄧˋ ㄓㄥˋ ㄘˊ ㄧㄢˊ', '成語', 3, '義理正當，措詞嚴厲。語本宋．歐陽修〈讀張李二生文贈石先生〉詩。', '義理正當，措詞嚴厲。語本宋．歐陽修〈讀張李二生文贈石先生〉詩。 △「理直氣壯」、「義正辭約」、「辭順理正」', '義理正當，措詞嚴厲。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '儘管老王的話說得義正辭嚴，對方依然不肯接受。', '儘管老王的話說得義正辭嚴，對方依然不肯接受。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"306"}'::jsonb)
  ,('active', '改邪歸正', 'ㄍㄞˇ ㄒㄧㄝˊ ㄍㄨㄟ ㄓㄥˋ', '成語', 3, '「改」、「歸」，典源分別作「背」、「向」。指改正錯誤的行為，返回正途。語本漢．應劭《漢官》。', '「改」、「歸」，典源分別作「背」、「向」。指改正錯誤的行為，返回正途。語本漢．應劭《漢官》。 △「棄暗投明」', '指改正錯誤的行為，返回正途。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '雖然他從前做了不少惡事，但如今已經改邪歸正了。', '雖然他從前做了不少惡事，但如今已經改邪歸正了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"307"}'::jsonb)
  ,('active', '顧此失彼', 'ㄍㄨˋ ㄘˇ ㄕ ㄅㄧˇ', '成語', 3, '注意這個，卻忽略了那個。謂作戰時不能全面防守。語本《隋書．卷五七．薛道衡列傳》。後多用「顧此失彼」指做事時不能全面兼顧。', '注意這個，卻忽略了那個。謂作戰時不能全面防守。語本《隋書．卷五七．薛道衡列傳》。後多用「顧此失彼」指做事時不能全面兼顧。 △「捉襟見肘」', '指做事時不能全面兼顧。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這篇文章的論點顧此失彼，不夠周延。', '這篇文章的論點顧此失彼，不夠周延。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"308"}'::jsonb)
  ,('active', '言聽計從', 'ㄧㄢˊ ㄊㄧㄥ ㄐㄧˋ ㄘㄨㄥˊ', '成語', 3, '指聽從某人說的話、出的計謀。形容某人深受信任。＃語本《史記．卷九二．淮陰侯列傳》。', '指聽從某人說的話、出的計謀。形容某人深受信任。＃語本《史記．卷九二．淮陰侯列傳》。 △「百依百順」、「解衣推食」', '形容某人深受信任。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '經理很信任小王，對他總是言聽計從。', '經理很信任小王，對他總是言聽計從。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"309"}'::jsonb)
  ,('active', '困獸猶鬥', 'ㄎㄨㄣˋ ㄕㄡˋ ㄧㄡˊ ㄉㄡˋ', '成語', 3, '被圍困的野獸尚且作最後的搏鬥。比喻處於絕境，仍然奮力抵抗。◎語出《左傳．宣公十二年》。', '被圍困的野獸尚且作最後的搏鬥。比喻處於絕境，仍然奮力抵抗。◎語出《左傳．宣公十二年》。 △「負嵎頑抗」', '比喻處於絕境，仍然奮力抵抗。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你快快投降吧！別再困獸猶鬥了！', '你快快投降吧！別再困獸猶鬥了！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"310"}'::jsonb)
  ,('active', '迥然不同', 'ㄐㄩㄥˇ ㄖㄢˊ ㄅㄨˋ ㄊㄨㄥˊ', '成語', 3, '迥然，相差很大的樣子。「迥然不同」指彼此不同，相差很大。※＃語或出宋．張戒《歲寒堂詩話》卷上。', '迥然，相差很大的樣子。「迥然不同」指彼此不同，相差很大。※＃語或出宋．張戒《歲寒堂詩話》卷上。 △「截然不同」', '彼此不同，相差很大。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '佛教徒與天主教徒對人生的想法迥然不同。', '佛教徒與天主教徒對人生的想法迥然不同。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"311"}'::jsonb)
  ,('active', '如出一轍', 'ㄖㄨˊ ㄔㄨ ㄧ ㄔㄜˋ', '成語', 3, '轍，車輛駛過，車輪所留下的行跡。行徑相同，車轍一致。比喻前後所發生的事情非常相似。◎語出宋．洪邁《容齋續筆．卷一一．名將晚謬》。', '轍，車輛駛過，車輪所留下的行跡。行徑相同，車轍一致。比喻前後所發生的事情非常相似。◎語出宋．洪邁《容齋續筆．卷一一．名將晚謬》。 △「一模一樣」', '比喻非常相像，幾乎沒有差別。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你們幾個人好吃懶做，如出一轍。', '你們幾個人好吃懶做，如出一轍。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"312"}'::jsonb)
  ,('active', '歡天喜地', 'ㄏㄨㄢ ㄊㄧㄢ ㄒㄧˇ ㄉㄧˋ', '成語', 3, '非常歡喜高興的樣子。※語或出《京本通俗小說．錯斬崔寧》。', '非常歡喜高興的樣子。※語或出《京本通俗小說．錯斬崔寧》。 △「歡欣鼓舞」', '非常歡喜高興的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '家家戶戶歡天喜地迎接新年的來臨。', '家家戶戶歡天喜地迎接新年的來臨。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"313"}'::jsonb)
  ,('active', '循規蹈矩', 'ㄒㄩㄣˊ ㄍㄨㄟ ㄉㄠˋ ㄐㄩˇ', '成語', 3, '遵守禮法，不踰越法度。語本《隋書．卷一四．音樂志中》。', '遵守禮法，不踰越法度。語本《隋書．卷一四．音樂志中》。 △「安分守己」', '遵守禮法，不踰越法度。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '經過這次教訓，他變得循規蹈矩多了。', '經過這次教訓，他變得循規蹈矩多了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"314"}'::jsonb)
  ,('active', '唯唯諾諾', 'ㄨㄟˇ ㄨㄟˇ ㄋㄨㄛˋ ㄋㄨㄛˋ', '成語', 3, '連聲稱是。比喻順從而無所違逆。語本《韓非子．八姦》。', '連聲稱是。比喻順從而無所違逆。語本《韓非子．八姦》。 △「唯命是聽」', '比喻順從而無所違逆。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '做人要有原則，不能老是唯唯諾諾的。', '做人要有原則，不能老是唯唯諾諾的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"315"}'::jsonb)
  ,('active', '孑然一身', 'ㄐㄧㄝˊ ㄖㄢˊ ㄧ ㄕㄣ', '成語', 3, '孑然，孤獨的樣子。「孑然一身」形容孤獨一個人。語本《三國志．卷五七．吳書．虞陸張駱吾朱傳．陸瑁》。', '孑然，孤獨的樣子。「孑然一身」形容孤獨一個人。語本《三國志．卷五七．吳書．虞陸張駱吾朱傳．陸瑁》。 △「形單影隻」、「孤苦伶仃」', '形容孤獨一個人。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他在臺灣，無親無故的，又沒有成家，至今仍是孑然一身。', '他在臺灣，無親無故的，又沒有成家，至今仍是孑然一身。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"316"}'::jsonb)
  ,('active', '氣壯山河', 'ㄑㄧˋ ㄓㄨㄤˋ ㄕㄢ ㄏㄜˊ', '成語', 3, '形容氣勢如高山大河般雄壯豪邁。語本唐．張說〈洛州張司馬集序〉。', '形容氣勢如高山大河般雄壯豪邁。語本唐．張說〈洛州張司馬集序〉。', '形容氣勢如高山大河般雄壯豪邁。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '文天祥慷慨就義，充滿氣壯山河的節操。', '文天祥慷慨就義，充滿氣壯山河的節操。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"317"}'::jsonb)
  ,('active', '不同凡響', 'ㄅㄨˋ ㄊㄨㄥˊ ㄈㄢˊ ㄒㄧㄤˇ', '成語', 3, '「不同凡響」典源作「非凡響」，意謂不是平凡的音樂。後用來比喻特出、不平凡的人或事物。※語或本唐．程太虛〈漱玉泉〉詩。', '「不同凡響」典源作「非凡響」，意謂不是平凡的音樂。後用來比喻特出、不平凡的人或事物。※語或本唐．程太虛〈漱玉泉〉詩。 △「不同凡庸」、「與眾不同」', '比喻特出、不平凡的人或事物。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位大師一出手，果然不同凡響。', '這位大師一出手，果然不同凡響。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"318"}'::jsonb)
  ,('active', '骨瘦如柴', 'ㄍㄨˇ ㄕㄡˋ ㄖㄨˊ ㄔㄞˊ', '成語', 3, '人身骨架瘦得露出來，根根像木材一樣。形容非常消瘦的樣子。語出敦煌變文《維摩詰經講經文》。', '人身骨架瘦得露出來，根根像木材一樣。形容非常消瘦的樣子。語出敦煌變文《維摩詰經講經文》。 △「形銷骨立」', '形容非常消瘦的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '別看他骨瘦如柴，卻是耐力十足。', '別看他骨瘦如柴，卻是耐力十足。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"319"}'::jsonb)
  ,('active', '理直氣壯', 'ㄌㄧˇ ㄓˊ ㄑㄧˋ ㄓㄨㄤˋ', '成語', 3, '理由正大、充分，則氣盛勢壯而無所畏懼。※＃語或出《喻世明言．卷三一．鬧陰司司馬貌斷獄》。', '理由正大、充分，則氣盛勢壯而無所畏懼。※＃語或出《喻世明言．卷三一．鬧陰司司馬貌斷獄》。 △「詞強理直」、「振振有辭」、「義正辭嚴」', '理由正大、充分，則氣勢壯盛而無所畏懼。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '只要你沒作虧心事，自然就能理直氣壯。', '只要你沒作虧心事，自然就能理直氣壯。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"320"}'::jsonb)
  ,('active', '星羅棋布', 'ㄒㄧㄥ ㄌㄨㄛˊ ㄑㄧˊ ㄅㄨˋ', '成語', 3, '如羅列在天上的群星、分布在棋盤上的棋子。形容布列繁密。語本《後漢書．卷四○．班彪列傳上》。', '如羅列在天上的群星、分布在棋盤上的棋子。形容布列繁密。語本《後漢書．卷四○．班彪列傳上》。 △「鱗次櫛比」', '形容布列繁密。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '來到野柳，只見怪石奇岩，星羅棋布。', '來到野柳，只見怪石奇岩，星羅棋布。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"321"}'::jsonb)
  ,('active', '依然故我', 'ㄧ ㄖㄢˊ ㄍㄨˋ ㄨㄛˇ', '成語', 3, '依舊和從前的我一樣，指情況依舊，沒有任何變化。※語或出宋．陳著〈賀新郎．北馬飛江過〉詞。', '依舊和從前的我一樣，指情況依舊，沒有任何變化。※語或出宋．陳著〈賀新郎．北馬飛江過〉詞。 △「依然如故」', '指情況依舊，沒有任何變化。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '儘管已經傾家蕩產，他還是依然故我，賭性不改。', '儘管已經傾家蕩產，他還是依然故我，賭性不改。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"322"}'::jsonb)
  ,('active', '大庭廣眾', 'ㄉㄚˋ ㄊㄧㄥˊ ㄍㄨㄤˇ ㄓㄨㄥˋ', '成語', 3, '「大庭廣眾」典源作「廣庭大眾」。廣，大同義。「大庭廣眾」指人多且公開的場合。＃語本《公孫龍子．跡府》。', '「大庭廣眾」典源作「廣庭大眾」。廣，大同義。「大庭廣眾」指人多且公開的場合。＃語本《公孫龍子．跡府》。 △「眾目睽睽」', '公開而人多的場合。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '現在的歹徒越來越囂張，竟然在大庭廣眾下公然搶劫！', '現在的歹徒越來越囂張，竟然在大庭廣眾下公然搶劫！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"323"}'::jsonb)
  ,('active', '鬼使神差', 'ㄍㄨㄟˇ ㄕˇ ㄕㄣˊ ㄔㄞ', '成語', 3, '冥冥中有鬼神相助。比喻被莫名力量驅使而不由自主。＃語出元．李致遠《還牢末》第四折。', '冥冥中有鬼神相助。比喻被莫名力量驅使而不由自主。＃語出元．李致遠《還牢末》第四折。 △「陰錯陽差」', '比喻被莫名力量驅使而不由自主。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我實在很意外，他竟然會做出這樣鬼使神差的事。', '我實在很意外，他竟然會做出這樣鬼使神差的事。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"324"}'::jsonb)
  ,('active', '粗枝大葉', 'ㄘㄨ ㄓ ㄉㄚˋ ㄧㄝˋ', '成語', 3, '「粗枝大葉」之「粗」，典源作「麤」。「麤」同「粗」。簡略概括。※語或本《朱子語類．卷七八．尚書一．綱領》。後用「粗枝大葉」比喻疏略，做事不細密。亦用於比喻大體的輪廓。', '「粗枝大葉」之「粗」，典源作「麤」。「麤」同「粗」。簡略概括。※語或本《朱子語類．卷七八．尚書一．綱領》。後用「粗枝大葉」比喻疏略，做事不細密。亦用於比喻大體的輪廓。 △「粗心大意」', '簡略概括。＆比喻疏略，做事不細密。＆比喻大體的輪廓。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他的報告寫得粗枝大葉，因此有許多處內容交待不清。', '他的報告寫得粗枝大葉，因此有許多處內容交待不清。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"325"}'::jsonb)
  ,('active', '相得益彰', 'ㄒㄧㄤ ㄉㄜˊ ㄧˋ ㄓㄤ', '成語', 3, '「相得益彰」之「彰」，典源作「章」。指互相配合、映襯，更能顯出各自的優點。語本漢．王襃〈聖主得賢臣頌〉。', '「相得益彰」之「彰」，典源作「章」。指互相配合、映襯，更能顯出各自的優點。語本漢．王襃〈聖主得賢臣頌〉。 △「相映成趣」、「聚精會神」', '指互相配合、映襯，更能顯出各自的優點。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這套洋裝，配上這條銀飾，相得益彰，更突顯出妳高雅的氣質。', '這套洋裝，配上這條銀飾，相得益彰，更突顯出妳高雅的氣質。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"326"}'::jsonb)
  ,('active', '心如刀割', 'ㄒㄧㄣ ㄖㄨˊ ㄉㄠ ㄍㄜ', '成語', 3, '謂內心痛苦，像被刀割一樣。語本漢．蔡邕〈太傅胡廣碑〉。', '謂內心痛苦，像被刀割一樣。語本漢．蔡邕〈太傅胡廣碑〉。 △「肝腸寸斷」', '內心痛苦像被刀割一樣。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '看到才買的新車被人破壞，他感到心如刀割。', '看到才買的新車被人破壞，他感到心如刀割。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"327"}'::jsonb)
  ,('active', '心滿意足', 'ㄒㄧㄣ ㄇㄢˇ ㄧˋ ㄗㄨˊ', '成語', 3, '心理滿足如意。語本《漢書．卷九九．王莽傳中》。', '心理滿足如意。語本《漢書．卷九九．王莽傳中》。 △「稱心如意」', '心理滿足如意。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他心滿意足地把玩著剛到手的戰利品。', '他心滿意足地把玩著剛到手的戰利品。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"328"}'::jsonb)
  ,('active', '名列前茅', 'ㄇㄧㄥˊ ㄌㄧㄝˋ ㄑㄧㄢˊ ㄇㄠˊ', '成語', 3, '茅，通「旄」。旄，旄牛。前茅，古代行軍打仗時，前行的兵士所拿的竿頂用旄牛尾裝飾的指揮旗幟。一說茅即茅草，春秋時代楚國行軍，有人拿著茅草當旗幟走在軍隊前面，或擔任斥候。「名列前茅」，指其名列於隊伍前面。語本《左傳．宣公十二年》。後用「名列前茅', '茅，通「旄」。旄，旄牛。前茅，古代行軍打仗時，前行的兵士所拿的竿頂用旄牛尾裝飾的指揮旗幟。一說茅即茅草，春秋時代楚國行軍，有人拿著茅草當旗幟走在軍隊前面，或擔任斥候。「名列前茅」，指其名列於隊伍前面。語本《左傳．宣公十二年》。後用「名列前茅」比喻成績優異，名次排在前面。 △「獨占鰲頭」', '比喻成績優異，名次排在前面。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '她的舞技精湛，每次參加比賽總是名列前茅。', '她的舞技精湛，每次參加比賽總是名列前茅。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"329"}'::jsonb)
  ,('active', '失魂落魄', 'ㄕ ㄏㄨㄣˊ ㄌㄨㄛˋ ㄆㄛˋ', '成語', 3, '魂、魄，皆古人想像中一種能脫離人體而獨立存在的精神。「失魂落魄」形容人極度驚慌或精神恍惚、失其主宰。※語或出《初刻拍案驚奇》卷二五。', '魂、魄，皆古人想像中一種能脫離人體而獨立存在的精神。「失魂落魄」形容人極度驚慌或精神恍惚、失其主宰。※語或出《初刻拍案驚奇》卷二五。 △「魂不守舍」', '形容人極度驚慌或精神恍惚、失其主宰。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '突來的一陣爆炸巨響，把所有人嚇得失魂落魄，驚慌失措。', '突來的一陣爆炸巨響，把所有人嚇得失魂落魄，驚慌失措。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"330"}'::jsonb)
  ,('active', '粗茶淡飯', 'ㄘㄨ ㄔㄚˊ ㄉㄢˋ ㄈㄢˋ', '成語', 3, '「粗茶淡飯」之「粗」，典源作「麤」。「麤」同「粗」。簡單清淡的飲食。語本宋．黃庭堅〈四休居士詩并序〉。', '「粗茶淡飯」之「粗」，典源作「麤」。「麤」同「粗」。簡單清淡的飲食。語本宋．黃庭堅〈四休居士詩并序〉。 △「家常便飯」', '指簡單清淡的飲食。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '粗茶淡飯雖然難以下嚥，卻比大魚大肉更有益於養生。', '粗茶淡飯雖然難以下嚥，卻比大魚大肉更有益於養生。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"331"}'::jsonb)
  ,('active', '躍然紙上', 'ㄩㄝˋ ㄖㄢˊ ㄓˇ ㄕㄤˋ', '成語', 3, '像在紙上跳動一般。形容描繪的對象非常生動逼真。※語或出清．薛雪《一瓢詩話》。', '像在紙上跳動一般。形容描繪的對象非常生動逼真。※語或出清．薛雪《一瓢詩話》。 △「栩栩如生」', '形容描繪的對象非常生動逼真。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這幅墨竹雖只是寥寥幾筆，但勁節風骨躍然紙上。', '這幅墨竹雖只是寥寥幾筆，但勁節風骨躍然紙上。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"332"}'::jsonb)
  ,('active', '見義勇為', 'ㄐㄧㄢˋ ㄧˋ ㄩㄥˇ ㄨㄟˊ', '成語', 3, '看到合乎正義的事，就奮勇去做。語本《論語．為政》。', '看到合乎正義的事，就奮勇去做。語本《論語．為政》。 △「急公好義」', '見到合乎正義的事，就奮勇去做。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '現代社會人情淡薄，見義勇為的人越來越少了。', '現代社會人情淡薄，見義勇為的人越來越少了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"333"}'::jsonb)
  ,('active', '形單影隻', 'ㄒㄧㄥˊ ㄉㄢ ㄧㄥˇ ㄓ', '成語', 3, '隻，孤獨的、單獨的。「形單影隻」指身形與影子都是孤獨的。形容孤單無伴。語出唐．韓愈〈祭十二郎文〉。', '隻，孤獨的、單獨的。「形單影隻」指身形與影子都是孤獨的。形容孤單無伴。語出唐．韓愈〈祭十二郎文〉。 △「孑然一身」、「孤苦伶仃」', '形容孤單無伴。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位隱士過著形單影隻的生活，很少與人來往。', '這位隱士過著形單影隻的生活，很少與人來往。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"334"}'::jsonb)
  ,('active', '養虎遺患', 'ㄧㄤˇ ㄏㄨˇ ㄧˊ ㄏㄨㄢˋ', '成語', 3, '飼養老虎，最後為自己帶來災禍。比喻不除去仇敵、惡人，將給自己留下後患。語出《史記．卷七．項羽本紀》。', '飼養老虎，最後為自己帶來災禍。比喻不除去仇敵、惡人，將給自己留下後患。語出《史記．卷七．項羽本紀》。 △「縱虎歸山」、「養癰遺患」', '比喻不除去仇敵、惡人，將給自己留下後患。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '今日除惡不盡，等於是養虎遺患，將帶來更多的禍害。', '今日除惡不盡，等於是養虎遺患，將帶來更多的禍害。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"335"}'::jsonb)
  ,('active', '憂心如焚', 'ㄧㄡ ㄒㄧㄣ ㄖㄨˊ ㄈㄣˊ', '成語', 3, '內心憂慮有如火在焚燒。形容非常焦急憂慮。語本《詩經．小雅．節南山》。', '內心憂慮有如火在焚燒。形容非常焦急憂慮。語本《詩經．小雅．節南山》。 △「憂心忡忡」', '形容非常焦急憂慮。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '獨生子突然得了重病，讓這對父母憂心如焚。', '獨生子突然得了重病，讓這對父母憂心如焚。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"336"}'::jsonb)
  ,('active', '搜索枯腸', 'ㄙㄡ ㄙㄨㄛˇ ㄎㄨ ㄔㄤˊ', '成語', 3, '搜尋枯空的肚腸。語本唐．盧仝〈走筆謝孟諫議寄新茶〉詩 。後用「搜索枯腸」比喻竭力思索。', '搜尋枯空的肚腸。語本唐．盧仝〈走筆謝孟諫議寄新茶〉詩 。後用「搜索枯腸」比喻竭力思索。 △「兩腋生風」、「挖空心思」', '比喻竭力思索。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '看他這麼傷心，每個人都搜索枯腸，想找些話來安慰他。', '看他這麼傷心，每個人都搜索枯腸，想找些話來安慰他。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"337"}'::jsonb)
  ,('active', '義無反顧', 'ㄧˋ ㄨˊ ㄈㄢˇ ㄍㄨˋ', '成語', 3, '秉持正義，勇往直前，絕不退縮。語本漢．司馬相如〈喻巴蜀檄〉。', '秉持正義，勇往直前，絕不退縮。語本漢．司馬相如〈喻巴蜀檄〉。 △「責無旁貸」、「義不容辭」、「當仁不讓」、「寡廉鮮恥」', '秉持正義，勇往直前，絕不退縮。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位老兵縱橫沙場數十年，保衛國家，義無反顧。', '這位老兵縱橫沙場數十年，保衛國家，義無反顧。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"338"}'::jsonb)
  ,('active', '坐立不安', 'ㄗㄨㄛˋ ㄌㄧˋ ㄅㄨˋ ㄢ', '成語', 3, '形容焦急、煩躁，心神不寧的樣子。※語或本《周書．卷四七．藝術列傳．姚僧垣》。', '形容焦急、煩躁，心神不寧的樣子。※語或本《周書．卷四七．藝術列傳．姚僧垣》。 △「忐忑不安」', '形容焦急、煩躁，心神不寧的樣子。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在等待考試錄取通知的日子裡，他成天坐立不安。', '在等待考試錄取通知的日子裡，他成天坐立不安。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"339"}'::jsonb)
  ,('active', '紛至沓來', 'ㄈㄣ ㄓˋ ㄊㄚˋ ㄌㄞˊ', '成語', 3, '紛，眾多。沓，重覆。「紛至沓來」形容事物紛紛不斷地到來。＃語出宋．朱熹〈答何叔京書〉其六。', '紛，眾多。沓，重覆。「紛至沓來」形容事物紛紛不斷地到來。＃語出宋．朱熹〈答何叔京書〉其六。 △「接踵而來」', '形容事物紛紛不斷地到來。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他考上了第一志願，親戚朋友的道賀紛至沓來，十分熱鬧。', '他考上了第一志願，親戚朋友的道賀紛至沓來，十分熱鬧。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"340"}'::jsonb)
  ,('active', '首屈一指', 'ㄕㄡˇ ㄑㄩ ㄧ ㄓˇ', '成語', 3, '彎下手指計算時，首先彎曲大拇指。用以表示第一或最優秀。※語或本宋．高斯得〈次韻不浮弟自金陵相過〉詩。', '彎下手指計算時，首先彎曲大拇指。用以表示第一或最優秀。※語或本宋．高斯得〈次韻不浮弟自金陵相過〉詩。 △「數一數二」', '表示第一或最優秀。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這間飯店是本市首屈一指的大飯店。', '這間飯店是本市首屈一指的大飯店。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"341"}'::jsonb)
  ,('active', '形影不離', 'ㄒㄧㄥˊ ㄧㄥˇ ㄅㄨˋ ㄌㄧˊ', '成語', 3, '形容關係密切，不能分開。語本《呂氏春秋．孝行覽．首時》。後亦用「形影不離」形容關係親密，無時無處不在一起。', '形容關係密切，不能分開。語本《呂氏春秋．孝行覽．首時》。後亦用「形影不離」形容關係親密，無時無處不在一起。 △「如影隨形」、「形影相隨」', '形容關係密切，無時無處不在一起。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '善惡報應，形影不離。', '善惡報應，形影不離。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"342"}'::jsonb)
  ,('active', '一決雌雄', 'ㄧ ㄐㄩㄝˊ ㄘ ㄒㄩㄥˊ', '成語', 3, '比喻互相較量以決定勝敗、高下。語本《史記．卷七．項羽本紀》。', '比喻互相較量以決定勝敗、高下。語本《史記．卷七．項羽本紀》。 △「一決勝負」、「決一死戰」', '比喻互相較量以決定勝敗、高下。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '先好好充實自己，才有能力與他一決雌雄。', '先好好充實自己，才有能力與他一決雌雄。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"343"}'::jsonb)
  ,('active', '依樣畫葫蘆', 'ㄧ ㄧㄤˋ ㄏㄨㄚˋ ㄏㄨˊ ㄌㄨˊ', '成語', 3, '依照葫蘆的樣子畫葫蘆。比喻一味模仿，毫無創見。※＃語或出宋．魏泰《東軒筆錄》卷一。', '依照葫蘆的樣子畫葫蘆。比喻一味模仿，毫無創見。※＃語或出宋．魏泰《東軒筆錄》卷一。 △「如法炮製」', '比喻一味模仿，毫無創見。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這個工作很單純，你只要依樣畫葫蘆就行了。', '這個工作很單純，你只要依樣畫葫蘆就行了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"344"}'::jsonb)
  ,('active', '厲兵秣馬', 'ㄌㄧˋ ㄅㄧㄥ ㄇㄛˋ ㄇㄚˇ', '成語', 3, '磨利兵器，餵飽馬匹。指完成作戰準備。語出《左傳．僖公三十三年》。後亦用「厲兵秣馬」比喻完成事前準備工作。', '磨利兵器，餵飽馬匹。指完成作戰準備。語出《左傳．僖公三十三年》。後亦用「厲兵秣馬」比喻完成事前準備工作。 △「嚴陣以待」', '指完成作戰準備。＆比喻完成事前準備工作。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我軍厲兵秣馬，已完成備戰工作。', '我軍厲兵秣馬，已完成備戰工作。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"345"}'::jsonb)
  ,('active', '禍起蕭牆', 'ㄏㄨㄛˋ ㄑㄧˇ ㄒㄧㄠ ㄑㄧㄤˊ', '成語', 3, '蕭牆，用以區隔內外的門屏，指內部。「禍起蕭牆」比喻禍亂發生於內部。語本《論語．季氏》。', '蕭牆，用以區隔內外的門屏，指內部。「禍起蕭牆」比喻禍亂發生於內部。語本《論語．季氏》。 △「分崩離析」', '比喻禍亂發生於內部。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '最近爆發的盜領案，經查證竟是禍起蕭牆，係由銀行員工所為。', '最近爆發的盜領案，經查證竟是禍起蕭牆，係由銀行員工所為。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"346"}'::jsonb)
  ,('active', '縱虎歸山', 'ㄗㄨㄥˋ ㄏㄨˇ ㄍㄨㄟ ㄕㄢ', '成語', 3, '把老虎放回山林。比喻放走敵人，後患無窮。語本《零陵先賢傳》。', '把老虎放回山林。比喻放走敵人，後患無窮。語本《零陵先賢傳》。 △「養虎遺患」', '比喻放走敵人，後患無窮。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種惡人，你又放了他一馬，難道你忘了上次縱虎歸山的教訓嗎？', '這種惡人，你又放了他一馬，難道你忘了上次縱虎歸山的教訓嗎？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"347"}'::jsonb)
  ,('active', '黨同伐異', 'ㄉㄤˇ ㄊㄨㄥˊ ㄈㄚ ㄧˋ', '成語', 3, '結合同黨，攻擊異己。原指學術上派別之間的鬥爭。語出《後漢書．卷六七．黨錮列傳．序》。後用「黨同伐異」泛指一切團體之間的鬥爭。', '結合同黨，攻擊異己。原指學術上派別之間的鬥爭。語出《後漢書．卷六七．黨錮列傳．序》。後用「黨同伐異」泛指一切團體之間的鬥爭。 △「結黨營私」', '泛指一切團體之間的鬥爭。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '正人君子應該講求公理正義，不可黨同伐異。', '正人君子應該講求公理正義，不可黨同伐異。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"348"}'::jsonb)
  ,('active', '大喜過望', 'ㄉㄚˋ ㄒㄧˇ ㄍㄨㄛˋ ㄨㄤˋ', '成語', 3, '因結果超過原本預期而感到特別高興。＃語出《史記．卷九一．黥布列傳》。', '因結果超過原本預期而感到特別高興。＃語出《史記．卷九一．黥布列傳》。 △「喜出望外」、「喜從天降」', '因結果超過原本預期而感到特別高興。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '原本成績欠佳的弟弟，居然能考上理想的學校，讓父母大喜過望。', '原本成績欠佳的弟弟，居然能考上理想的學校，讓父母大喜過望。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"349"}'::jsonb)
  ,('active', '響遏行雲', 'ㄒㄧㄤˇ ㄜˋ ㄒㄧㄥˊ ㄩㄣˊ', '成語', 3, '聲音清越嘹亮，可直上天際，止住行雲。形容歌聲響亮高妙。語出《列子．湯問》。', '聲音清越嘹亮，可直上天際，止住行雲。形容歌聲響亮高妙。語出《列子．湯問》。 △「餘音繞梁」、「響徹雲霄」', '形容歌聲響亮高妙。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位聲樂家的歌聲，響遏行雲，十分嘹亮。', '這位聲樂家的歌聲，響遏行雲，十分嘹亮。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"350"}'::jsonb)
  ,('active', '涇渭分明', 'ㄐㄧㄥ ㄨㄟˋ ㄈㄣ ㄇㄧㄥˊ', '成語', 3, '涇水流入渭水時，清濁不混，界限分明。語本《詩經．邶風．谷風》。後用「涇渭分明」比喻彼此的區別非常清楚。', '涇水流入渭水時，清濁不混，界限分明。語本《詩經．邶風．谷風》。後用「涇渭分明」比喻彼此的區別非常清楚。 △「壁壘分明」', '比喻彼此的區別非常清楚。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這兩個產品一經比較，品質立即涇渭分明，各自的優劣表露無遺。', '這兩個產品一經比較，品質立即涇渭分明，各自的優劣表露無遺。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"351"}'::jsonb)
  ,('active', '破釜沉舟', 'ㄆㄛˋ ㄈㄨˇ ㄔㄣˊ ㄓㄡ', '成語', 3, '打破鍋釜又鑿沉船，讓自己沒有退路，以求戰爭勝利。＃典出漢．司馬遷《史記．卷七．項羽本紀》。後用「破釜沉舟」比喻不惜切斷自己的退路，以求努力獲得最好的成果。', '打破鍋釜又鑿沉船，讓自己沒有退路，以求戰爭勝利。＃典出漢．司馬遷《史記．卷七．項羽本紀》。後用「破釜沉舟」比喻不惜切斷自己的退路，以求努力獲得最好的成果。', '形容做事果決，義無反顧。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '事已至此，只有破釜沉舟，作最後一搏。', '事已至此，只有破釜沉舟，作最後一搏。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"352"}'::jsonb)
  ,('active', '中庸之道', 'ㄓㄨㄥ ㄩㄥ ㄓ ㄉㄠˋ', '成語', 3, '不偏不倚、無過與不及的處事態度。語本《論語．雍也》。', '不偏不倚、無過與不及的處事態度。語本《論語．雍也》。', '不偏不倚、無過與不及的處事態度。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他一向都秉持中庸之道，就事論事，大家都樂於和他共處。', '他一向都秉持中庸之道，就事論事，大家都樂於和他共處。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"353"}'::jsonb)
  ,('active', '一丘之貉', 'ㄧ ㄑㄧㄡ ㄓ ㄏㄜˊ', '成語', 3, '貉，音ㄏㄜˊ，一種形似狐狸的野獸。「一丘之貉」指出自同一山丘上的貉。比喻彼此同樣低劣，並無差異。語出《漢書．卷六六．公孫劉田王楊蔡陳鄭傳．楊敞》。', '貉，音ㄏㄜˊ，一種形似狐狸的野獸。「一丘之貉」指出自同一山丘上的貉。比喻彼此同樣低劣，並無差異。語出《漢書．卷六六．公孫劉田王楊蔡陳鄭傳．楊敞》。', '比喻彼此同樣低劣，並無差異。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在我看這群人都是一丘之貉，無一例外。', '在我看這群人都是一丘之貉，無一例外。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"354"}'::jsonb)
  ,('active', '班門弄斧', 'ㄅㄢ ㄇㄣˊ ㄋㄨㄥˋ ㄈㄨˇ', '成語', 3, '班，魯班，古代巧匠。「班門弄斧」指在巧匠魯班門前玩弄大斧。比喻在行家面前賣弄本事，不自量力。 ＃語本唐．柳宗元〈王氏伯仲唱和詩序〉。', '班，魯班，古代巧匠。「班門弄斧」指在巧匠魯班門前玩弄大斧。比喻在行家面前賣弄本事，不自量力。 ＃語本唐．柳宗元〈王氏伯仲唱和詩序〉。', '比喻在行家面前賣弄本事，不自量力。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他可是大名家，你別班門弄斧了。', '他可是大名家，你別班門弄斧了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"355"}'::jsonb)
  ,('active', '水落石出', 'ㄕㄨㄟˇ ㄌㄨㄛˋ ㄕˊ ㄔㄨ', '成語', 3, '冬季水位下降，使石頭顯露出來。形容水枯季節的自然景色。※語或出宋．歐陽修〈醉翁亭記〉。後用「水落石出」比喻事情經過澄清而後真相大白。', '冬季水位下降，使石頭顯露出來。形容水枯季節的自然景色。※語或出宋．歐陽修〈醉翁亭記〉。後用「水落石出」比喻事情經過澄清而後真相大白。 △「水清石見」', '比喻事情經過澄清而後真相大白。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '事實既已水落石出，謠言當然不攻自破。', '事實既已水落石出，謠言當然不攻自破。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"356"}'::jsonb)
  ,('active', '名落孫山', 'ㄇㄧㄥˊ ㄌㄨㄛˋ ㄙㄨㄣ ㄕㄢ', '成語', 3, '孫山，宋朝人，應試考中最後一名。「名落孫山」，名落於孫山之後，指參加考試或選拔沒有被錄取。 ＃典出宋．范公偁《過庭錄》。', '孫山，宋朝人，應試考中最後一名。「名落孫山」，名落於孫山之後，指參加考試或選拔沒有被錄取。 ＃典出宋．范公偁《過庭錄》。', '指應考不中。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你平時不努力，難怪幾次考試都名落孫山。', '你平時不努力，難怪幾次考試都名落孫山。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"357"}'::jsonb)
  ,('active', '胸有成竹', 'ㄒㄩㄥ ㄧㄡˇ ㄔㄥˊ ㄓㄨˊ', '成語', 3, '指畫竹之前，心中早已有了竹子的完整形象。＃語本宋．蘇軾〈文與可畫篔簹（ㄩㄣˊ ㄉㄤ）谷偃竹記〉。後用「胸有成竹」比喻處事有定見。', '指畫竹之前，心中早已有了竹子的完整形象。＃語本宋．蘇軾〈文與可畫篔簹（ㄩㄣˊ ㄉㄤ）谷偃竹記〉。後用「胸有成竹」比喻處事有定見。', '比喻處事有定見。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '如何應付這次考試，他早就胸有成竹。', '如何應付這次考試，他早就胸有成竹。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"358"}'::jsonb)
  ,('active', '指鹿為馬', 'ㄓˇ ㄌㄨˋ ㄨㄟˊ ㄇㄚˇ', '成語', 3, '將鹿指稱是馬，藉以展現自己的威權。比喻人刻意顛倒是非。＃典出漢．陸賈《新語．辨惑》。', '將鹿指稱是馬，藉以展現自己的威權。比喻人刻意顛倒是非。＃典出漢．陸賈《新語．辨惑》。', '比喻人刻意混淆是非，顛倒黑白。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '獨裁者大權在握，往往指鹿為馬，胡作非為。', '獨裁者大權在握，往往指鹿為馬，胡作非為。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"359"}'::jsonb)
  ,('active', '天衣無縫', 'ㄊㄧㄢ ㄧ ㄨˊ ㄈㄥˋ', '成語', 3, '古代傳說天神的衣服，不用針線縫製，故沒有縫痕。＃典出《神異經》。後用「天衣無縫」比喻詩文渾然天成，沒有斧鑿痕跡；亦用於比喻事物或計畫周密完美，沒有一絲破綻或缺點。', '古代傳說天神的衣服，不用針線縫製，故沒有縫痕。＃典出《神異經》。後用「天衣無縫」比喻詩文渾然天成，沒有斧鑿痕跡；亦用於比喻事物或計畫周密完美，沒有一絲破綻或缺點。', '比喻詩文渾然天成，沒有斧鑿痕跡。褒義。＆比喻事物或計畫周密完美，沒有一絲破綻或缺點。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這篇推理小說的結構，簡直是天衣無縫、無懈可擊。', '這篇推理小說的結構，簡直是天衣無縫、無懈可擊。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"360"}'::jsonb)
  ,('active', '江郎才盡', 'ㄐㄧㄤ ㄌㄤˊ ㄘㄞˊ ㄐㄧㄣˋ', '成語', 3, '江郎，指南朝梁文人江淹。「江郎才盡」則指江淹晚年才思減退，所作詩文皆無佳句。 ＃典出南朝梁．鍾嶸《詩品．卷中．齊光祿江淹》。後用「江郎才盡」比喻文人的才思枯竭，無法再創佳句。', '江郎，指南朝梁文人江淹。「江郎才盡」則指江淹晚年才思減退，所作詩文皆無佳句。 ＃典出南朝梁．鍾嶸《詩品．卷中．齊光祿江淹》。後用「江郎才盡」比喻文人的才思枯竭，無法再創佳句。', '比喻文人的才思枯竭，無法再創佳句。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '作家難免會有文思枯竭，江郎才盡的時候。', '作家難免會有文思枯竭，江郎才盡的時候。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"361"}'::jsonb)
  ,('active', '口若懸河', 'ㄎㄡˇ ㄖㄨㄛˋ ㄒㄩㄢˊ ㄏㄜˊ', '成語', 3, '說起話來像瀑布一樣滔滔不絕，比喻能言善辯。＃語本南朝宋．劉義慶《世說新語．賞譽》。', '說起話來像瀑布一樣滔滔不絕，比喻能言善辯。＃語本南朝宋．劉義慶《世說新語．賞譽》。', '比喻能言善辯。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '沒有口若懸河的本事，怎能成為演說家？', '沒有口若懸河的本事，怎能成為演說家？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"362"}'::jsonb)
  ,('active', '驚弓之鳥', 'ㄐㄧㄥ ㄍㄨㄥ ㄓ ㄋㄧㄠˇ', '成語', 3, '曾受過箭傷，一聽到弓弦的聲音，就會驚懼的鳥。比喻曾受打擊或驚嚇，心有餘悸，稍有動靜就害怕的人。典出《戰國策．楚策四》。', '曾受過箭傷，一聽到弓弦的聲音，就會驚懼的鳥。比喻曾受打擊或驚嚇，心有餘悸，稍有動靜就害怕的人。典出《戰國策．楚策四》。', '比喻曾受打擊或驚嚇，心有餘悸，稍有動靜就害怕的人。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '敵軍連吃幾次敗仗，已經成了驚弓之鳥。', '敵軍連吃幾次敗仗，已經成了驚弓之鳥。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"363"}'::jsonb)
  ,('active', '一敗塗地', 'ㄧ ㄅㄞˋ ㄊㄨˊ ㄉㄧˋ', '成語', 3, '「一」，典源作「壹」。「壹」同「一」。一旦戰敗身死，將會是肝腦塗滿大地。＃語出《史記．卷八．高祖本紀》。後用「一敗塗地」形容做事失敗，到了無法收拾的地步。', '「一」，典源作「壹」。「壹」同「一」。一旦戰敗身死，將會是肝腦塗滿大地。＃語出《史記．卷八．高祖本紀》。後用「一敗塗地」形容做事失敗，到了無法收拾的地步。', '形容做事失敗，到了無法收拾的地步。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這回考得一敗塗地，只好下次再來了。', '這回考得一敗塗地，只好下次再來了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"364"}'::jsonb)
  ,('active', '投筆從戎', 'ㄊㄡˊ ㄅㄧˇ ㄘㄨㄥˊ ㄖㄨㄥˊ', '成語', 3, '戎，軍旅。「投筆從戎」指棄文從軍，以衛國立功。＃典出《東觀漢記．卷一六．班超列傳》。', '戎，軍旅。「投筆從戎」指棄文從軍，以衛國立功。＃典出《東觀漢記．卷一六．班超列傳》。', '比喻棄文從軍，以衛國立功。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '好男兒，當自強，投筆從戎上戰場。', '好男兒，當自強，投筆從戎上戰場。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"365"}'::jsonb)
  ,('active', '畫蛇添足', 'ㄏㄨㄚˋ ㄕㄜˊ ㄊㄧㄢ ㄗㄨˊ', '成語', 3, '畫好蛇後，多事為它添上蛇足，結果反而失去本已贏得的酒。比喻多此一舉，反將事情弄糟。典出《戰國策．齊策二》。', '畫好蛇後，多事為它添上蛇足，結果反而失去本已贏得的酒。比喻多此一舉，反將事情弄糟。典出《戰國策．齊策二》。', '比喻多此一舉，反將事情弄糟。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '寫文章意足即可，不要畫蛇添足。', '寫文章意足即可，不要畫蛇添足。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"366"}'::jsonb)
  ,('active', '望梅止渴', 'ㄨㄤˋ ㄇㄟˊ ㄓˇ ㄎㄜˇ', '成語', 3, '曹操編造前方梅林結了很多果實，誘使士兵流出口水以解渴的故事。典出南朝宋．劉義慶《世說新語．假譎》。後用「望梅止渴」比喻以空想來安慰自己。', '曹操編造前方梅林結了很多果實，誘使士兵流出口水以解渴的故事。典出南朝宋．劉義慶《世說新語．假譎》。後用「望梅止渴」比喻以空想來安慰自己。 △「畫餅充飢」', '比喻以空想來安慰自己。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他沒錢買別墅，只好天天看著房屋廣告望梅止渴了。', '他沒錢買別墅，只好天天看著房屋廣告望梅止渴了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"367"}'::jsonb)
  ,('active', '司空見慣', 'ㄙ ㄎㄨㄥ ㄐㄧㄢˋ ㄍㄨㄢˋ', '成語', 3, '司空，職官名。「司空見慣」比喻經常看到，不足為奇。＃語出唐．孟棨《本事詩．情感》', '司空，職官名。「司空見慣」比喻經常看到，不足為奇。＃語出唐．孟棨《本事詩．情感》', '比喻經常看到，不足為奇。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '如此司空見慣的事，大家怎會感興趣？', '如此司空見慣的事，大家怎會感興趣？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"368"}'::jsonb)
  ,('active', '南轅北轍', 'ㄋㄢˊ ㄩㄢˊ ㄅㄟˇ ㄔㄜˋ', '成語', 3, '轅，大車前部套在牲口左右兩邊的木頭，用以拖車。轍，車輛駛過留下的痕跡。「南轅北轍」指本要向南，但卻駕車往北行，離目的地越來越遠。比喻行動和想要達到的目的相反。典出《戰國策．魏策四》。後亦用「南轅北轍」比喻二者彼此背道而馳，或比喻遙隔兩地。', '轅，大車前部套在牲口左右兩邊的木頭，用以拖車。轍，車輛駛過留下的痕跡。「南轅北轍」指本要向南，但卻駕車往北行，離目的地越來越遠。比喻行動和想要達到的目的相反。典出《戰國策．魏策四》。後亦用「南轅北轍」比喻二者彼此背道而馳，或比喻遙隔兩地。 △「背道而馳」', '比喻行動和想要達到的目的相反。 ＆比喻二者彼此背道而馳。＆比喻遙隔兩地。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '想成功卻又不努力，豈非南轅北轍？', '想成功卻又不努力，豈非南轅北轍？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"369"}'::jsonb)
  ,('active', '狼狽為奸', 'ㄌㄤˊ ㄅㄟˋ ㄨㄟˊ ㄐㄧㄢ', '成語', 3, '狼與狽相互搭配，傷害人命。語本唐．段成式《酉陽雜俎．卷一六．毛篇》。後用「狼狽為奸」比喻互相勾結做壞事。', '狼與狽相互搭配，傷害人命。語本唐．段成式《酉陽雜俎．卷一六．毛篇》。後用「狼狽為奸」比喻互相勾結做壞事。', '比喻互相勾結做壞事。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '當地米商狼狽為奸，聯手哄抬物價。', '當地米商狼狽為奸，聯手哄抬物價。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"370"}'::jsonb)
  ,('active', '狐假虎威', 'ㄏㄨˊ ㄐㄧㄚˇ ㄏㄨˇ ㄨㄟ', '成語', 3, '假，借。「狐假虎威」指狐狸借老虎的威風嚇走其他野獸。＃典出《尹文子》逸文。後用「狐假虎威」比喻藉著有權者的威勢欺壓他人、作威作福。', '假，借。「狐假虎威」指狐狸借老虎的威風嚇走其他野獸。＃典出《尹文子》逸文。後用「狐假虎威」比喻藉著有權者的威勢欺壓他人、作威作福。 △「狗仗人勢」', '比喻藉著有權者的威勢欺壓他人、作威作福。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他只是董事長身邊的司機，卻常狐假虎威地發號施令。', '他只是董事長身邊的司機，卻常狐假虎威地發號施令。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"371"}'::jsonb)
  ,('active', '為虎作倀', 'ㄨㄟˋ ㄏㄨˇ ㄗㄨㄛˋ ㄔㄤ', '成語', 3, '倀，音ㄔㄤ，傳說中被虎吃掉後又供虎使喚的鬼。「為虎作倀」指被虎咬死的人，靈魂將化為鬼而為虎所役使。＃典出唐．裴鉶《傳奇》。後用「為虎作倀」比喻幫惡人做壞事。', '倀，音ㄔㄤ，傳說中被虎吃掉後又供虎使喚的鬼。「為虎作倀」指被虎咬死的人，靈魂將化為鬼而為虎所役使。＃典出唐．裴鉶《傳奇》。後用「為虎作倀」比喻幫惡人做壞事。', '比喻幫惡人做壞事。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我真不知道他是這麼壞的人，竟然為虎作倀當了幫凶。', '我真不知道他是這麼壞的人，竟然為虎作倀當了幫凶。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"372"}'::jsonb)
  ,('active', '如火如荼', 'ㄖㄨˊ ㄏㄨㄛˇ ㄖㄨˊ ㄊㄨˊ', '成語', 3, '荼，茅草開的白花。「如火如荼」指像火那樣紅、像荼那樣白。比喻軍容壯盛浩大。語本《國語．吳語》。後用「如火如荼」形容事物的興盛或氣氛的熱烈。', '荼，茅草開的白花。「如火如荼」指像火那樣紅、像荼那樣白。比喻軍容壯盛浩大。語本《國語．吳語》。後用「如火如荼」形容事物的興盛或氣氛的熱烈。', '形容事物的興盛或氣氛的熱烈。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '國際棒球賽正在臺北市如火如荼地進行著。', '國際棒球賽正在臺北市如火如荼地進行著。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"373"}'::jsonb)
  ,('active', '老馬識途', 'ㄌㄠˇ ㄇㄚˇ ㄕˋ ㄊㄨˊ', '成語', 3, '老馬認得走過的路。典出《韓非子．說林上》。後用「老馬識途」比喻有經驗的人對情況比較熟悉，容易把工作做好。', '老馬認得走過的路。典出《韓非子．說林上》。後用「老馬識途」比喻有經驗的人對情況比較熟悉，容易把工作做好。', '比喻有經驗的人對情況比較熟悉，容易把工作做好。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '放心吧！小王老馬識途，不會迷路。', '放心吧！小王老馬識途，不會迷路。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"374"}'::jsonb)
  ,('active', '一暴十寒', 'ㄧ ㄆㄨˋ ㄕˊ ㄏㄢˊ', '成語', 3, '在陽光下曝晒一天，又接連冷凍十天。比喻人做事缺乏恆心，時常中斷。語本《孟子．告子上》。後用「一暴十寒」比喻人學習或工作不能有所堅持，缺乏恆心。', '在陽光下曝晒一天，又接連冷凍十天。比喻人做事缺乏恆心，時常中斷。語本《孟子．告子上》。後用「一暴十寒」比喻人學習或工作不能有所堅持，缺乏恆心。', '比喻人做事缺乏恆心，時常中斷。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為學要有耐心，不能一暴十寒。', '為學要有耐心，不能一暴十寒。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"375"}'::jsonb)
  ,('active', '守株待兔', 'ㄕㄡˇ ㄓㄨ ㄉㄞˋ ㄊㄨˋ', '成語', 3, '沿用過去的方法，守在樹旁，等待撞樹而死的兔子，最後終一無所得。比喻拘泥守成。典出《韓非子．五蠹》。後亦用「守株待兔」比喻妄想不勞而獲或等著目標自己送上門來。', '沿用過去的方法，守在樹旁，等待撞樹而死的兔子，最後終一無所得。比喻拘泥守成。典出《韓非子．五蠹》。後亦用「守株待兔」比喻妄想不勞而獲或等著目標自己送上門來。 △「刻舟求劍」、「膠柱鼓瑟」', '比喻拘泥守成，不知變通。貶義。＆比喻妄想不勞而獲。貶義。＆等著目標自己送上門來。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '經驗固然重要，但卻不能守株待兔，不知變通。', '經驗固然重要，但卻不能守株待兔，不知變通。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"376"}'::jsonb)
  ,('active', '四面楚歌', 'ㄙˋ ㄇㄧㄢˋ ㄔㄨˇ ㄍㄜ', '成語', 3, '四面都是楚國的歌謠。典出《史記．卷七．項羽本紀》。後用「四面楚歌」比喻四面受敵，孤立無援。', '四面都是楚國的歌謠。典出《史記．卷七．項羽本紀》。後用「四面楚歌」比喻四面受敵，孤立無援。', '比喻四面受敵，孤立無援。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '因為戰略錯誤，使前線軍隊陷入四面楚歌的困境。', '因為戰略錯誤，使前線軍隊陷入四面楚歌的困境。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"377"}'::jsonb)
  ,('active', '奇貨可居', 'ㄑㄧˊ ㄏㄨㄛˋ ㄎㄜˇ ㄐㄩ', '成語', 3, '收藏奇珍異品，等待高價出售。比喻利用某種專長或有價值的東西以謀利。語出《史記．卷八五．呂不韋列傳》。', '收藏奇珍異品，等待高價出售。比喻利用某種專長或有價值的東西以謀利。語出《史記．卷八五．呂不韋列傳》。', '比喻利用某種專長或有價值的東西以謀利。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他看準了水在大漠地區必定奇貨可居，一本萬利。', '他看準了水在大漠地區必定奇貨可居，一本萬利。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"378"}'::jsonb)
  ,('active', '刻舟求劍', 'ㄎㄜˋ ㄓㄡ ㄑㄧㄡˊ ㄐㄧㄢˋ', '成語', 3, '劍掉入水中，在船舷刻上記號，待船停止後仍從記號處下水尋劍。比喻拘泥固執，不知變通。典出《呂氏春秋．慎大覽．察今》。', '劍掉入水中，在船舷刻上記號，待船停止後仍從記號處下水尋劍。比喻拘泥固執，不知變通。典出《呂氏春秋．慎大覽．察今》。 △「守株待兔」、「膠柱鼓瑟」', '比喻拘泥固執，不知變通。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '因應各種狀況，我們不宜刻舟求劍，不知變通。', '因應各種狀況，我們不宜刻舟求劍，不知變通。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"379"}'::jsonb)
  ,('active', '後來居上', 'ㄏㄡˋ ㄌㄞˊ ㄐㄩ ㄕㄤˋ', '成語', 3, '堆積柴火時，後搬來的反而在上面。指用人時，資格淺的人反而居上位。＃語本《史記．卷一二○．汲鄭列傳．汲黯》。後用「後來居上」形容後來的人或事物超越原領先者。', '堆積柴火時，後搬來的反而在上面。指用人時，資格淺的人反而居上位。＃語本《史記．卷一二○．汲鄭列傳．汲黯》。後用「後來居上」形容後來的人或事物超越原領先者。 △「青出於藍」', '形容後來的人或事物超越原領先者。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他學棋雖然較我晚，卻後來居上，段數已比我高。', '他學棋雖然較我晚，卻後來居上，段數已比我高。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"380"}'::jsonb)
  ,('active', '負荊請罪', 'ㄈㄨˋ ㄐㄧㄥ ㄑㄧㄥˇ ㄗㄨㄟˋ', '成語', 3, '背著荊條，前往對方居所自請責罰。典出《史記．卷八一．廉頗藺相如列傳》。後用「負荊請罪」比喻主動向對方承認錯誤，請求責罰和原諒。', '背著荊條，前往對方居所自請責罰。典出《史記．卷八一．廉頗藺相如列傳》。後用「負荊請罪」比喻主動向對方承認錯誤，請求責罰和原諒。 △「刎頸之交」', '背著荊條，前往對方居所自請責罰。 ＆比喻主動向對方承認錯誤，請求責罰和原諒。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '當年廉頗向藺相如負荊請罪，是有感於藺相如的寬容大度。', '當年廉頗向藺相如負荊請罪，是有感於藺相如的寬容大度。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"381"}'::jsonb)
  ,('active', '對牛彈琴', 'ㄉㄨㄟˋ ㄋㄧㄡˊ ㄊㄢˊ ㄑㄧㄣˊ', '成語', 3, '為牛彈琴，但牛依然低頭而食，聽而不聞。比喻講話、做事不看對象。典出《弘明集．卷一．漢．牟融．理惑論》。後用「對牛彈琴」比喻對不懂道理的人講道理。', '為牛彈琴，但牛依然低頭而食，聽而不聞。比喻講話、做事不看對象。典出《弘明集．卷一．漢．牟融．理惑論》。後用「對牛彈琴」比喻對不懂道理的人講道理。', '比喻講話、做事不看對象。＆比喻對不懂道理的人講道理。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這家牧場放音樂給乳牛聽，真的是對牛彈琴。', '這家牧場放音樂給乳牛聽，真的是對牛彈琴。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"382"}'::jsonb)
  ,('active', '一鼓作氣', 'ㄧ ㄍㄨˇ ㄗㄨㄛˋ ㄑㄧˋ', '成語', 3, '古代作戰時，第一通鼓最能激起戰士們的勇氣。語出《左傳．莊公十年》。後用「一鼓作氣」比喻做事時要趁著初起時的勇氣去做才容易成功。', '古代作戰時，第一通鼓最能激起戰士們的勇氣。語出《左傳．莊公十年》。後用「一鼓作氣」比喻做事時要趁著初起時的勇氣去做才容易成功。', '比喻做事時要趁著初起時的勇氣去做才容易成功。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他拿起筆，一鼓作氣連寫了三幅字。', '他拿起筆，一鼓作氣連寫了三幅字。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"383"}'::jsonb)
  ,('active', '紙上談兵', 'ㄓˇ ㄕㄤˋ ㄊㄢˊ ㄅㄧㄥ', '成語', 3, '在文字上談論用兵的策略。典出《史記．卷八一．廉頗藺相如列傳．趙奢》。後用「紙上談兵」比喻不切實際的議論。', '在文字上談論用兵的策略。典出《史記．卷八一．廉頗藺相如列傳．趙奢》。後用「紙上談兵」比喻不切實際的議論。 △「紙上空談」', '比喻不切實際的議論。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些想法都只是紙上談兵，真正實施必有困難。', '這些想法都只是紙上談兵，真正實施必有困難。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"384"}'::jsonb)
  ,('active', '破鏡重圓', 'ㄆㄛˋ ㄐㄧㄥˋ ㄔㄨㄥˊ ㄩㄢˊ', '成語', 3, '破成兩半的鏡子再次復合。指南朝陳徐德言與妻樂昌公主於戰亂離散時各執半鏡，作為他日相見的信物，後果因此得以相聚。典出唐．孟棨《本事詩．情感》。後用「破鏡重圓」比喻夫妻離散或感情決裂後重新團圓合好。', '破成兩半的鏡子再次復合。指南朝陳徐德言與妻樂昌公主於戰亂離散時各執半鏡，作為他日相見的信物，後果因此得以相聚。典出唐．孟棨《本事詩．情感》。後用「破鏡重圓」比喻夫妻離散或感情決裂後重新團圓合好。', '比喻夫妻離散或情感決裂後重新團圓合好。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在離散二十年後，他們夫妻終於破鏡重圓。', '在離散二十年後，他們夫妻終於破鏡重圓。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"385"}'::jsonb)
  ,('active', '打草驚蛇', 'ㄉㄚˇ ㄘㄠˇ ㄐㄧㄥ ㄕㄜˊ', '成語', 3, '擊打草叢以嚇走蛇。比喻某甲受到懲戒，而使某乙、丙等知所警惕。※＃語或本宋．鄭文寶《南唐近事》卷二。後用「打草驚蛇」比喻對付敵人時，行事不密，致使對方有所警覺，而預先防備。', '擊打草叢以嚇走蛇。比喻某甲受到懲戒，而使某乙、丙等知所警惕。※＃語或本宋．鄭文寶《南唐近事》卷二。後用「打草驚蛇」比喻對付敵人時，行事不密，致使對方有所警覺，而預先防備。', '擊打草叢以嚇走蛇。＆比喻行事不密，致使對方有所警覺，而預先防備。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在野外要進入草叢時，切記要先打草驚蛇。', '在野外要進入草叢時，切記要先打草驚蛇。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"386"}'::jsonb)
  ,('active', '揠苗助長', 'ㄧㄚˋ ㄇㄧㄠˊ ㄓㄨˋ ㄓㄤˇ', '成語', 3, '揠，拔起。「揠苗助長」指拔苗以助其成長，反而讓苗枯死了。比喻使用不當的手段以求速成，結果不但無益，反而有害。典出《孟子．公孫丑上》。', '揠，拔起。「揠苗助長」指拔苗以助其成長，反而讓苗枯死了。比喻使用不當的手段以求速成，結果不但無益，反而有害。典出《孟子．公孫丑上》。', '比喻為用不當的手段以求速成，結果不但無益，反而有害。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '學習須漸進有功，一味跳級求深，無異於揠苗助長。', '學習須漸進有功，一味跳級求深，無異於揠苗助長。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"387"}'::jsonb)
  ,('active', '一鳴驚人', 'ㄧ ㄇㄧㄥˊ ㄐㄧㄥ ㄖㄣˊ', '成語', 3, '一出聲就令人吃驚。比喻平時默默無聞，而後卻突然有驚人的表現。＃典出《韓非子．喻老》。', '一出聲就令人吃驚。比喻平時默默無聞，而後卻突然有驚人的表現。＃典出《韓非子．喻老》。', '比喻平時默默無聞，而後卻突然有驚人的表現。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他果然具有實力，首次公演便一鳴驚人。', '他果然具有實力，首次公演便一鳴驚人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"388"}'::jsonb)
  ,('active', '死灰復燃', 'ㄙˇ ㄏㄨㄟ ㄈㄨˋ ㄖㄢˊ', '成語', 3, '「死灰復燃」之「燃」，典源作「然」。「然」同「燃」。「死灰復燃」是將已經熄滅的灰燼，又重新燃燒起來，比喻失勢者重新得勢。語本《史記．卷一○八．韓長孺列傳》。後亦用「死灰復燃」比喻已經平息的事物，又重新活動起來。', '「死灰復燃」之「燃」，典源作「然」。「然」同「燃」。「死灰復燃」是將已經熄滅的灰燼，又重新燃燒起來，比喻失勢者重新得勢。語本《史記．卷一○八．韓長孺列傳》。後亦用「死灰復燃」比喻已經平息的事物，又重新活動起來。', '比喻失勢者重新得勢。＆比喻已經平息的事物，又重新活動起來。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位總理本已失勢，現在死灰復燃，重新掌大權了。', '這位總理本已失勢，現在死灰復燃，重新掌大權了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"389"}'::jsonb)
  ,('active', '出奇制勝', 'ㄔㄨ ㄑㄧˊ ㄓˋ ㄕㄥˋ', '成語', 3, '發奇兵或用奇計制敵而獲勝。語本《孫子．勢篇》。後用「出奇制勝」比喻用奇特、創新的方法取得好效果。', '發奇兵或用奇計制敵而獲勝。語本《孫子．勢篇》。後用「出奇制勝」比喻用奇特、創新的方法取得好效果。', '發奇兵或用奇計制敵而獲勝。褒義。＆比喻用奇特、創新的方法取得好效果。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他打仗善於出奇制勝，難怪敵人聞風喪膽。', '他打仗善於出奇制勝，難怪敵人聞風喪膽。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"390"}'::jsonb)
  ,('active', '食古不化', 'ㄕˊ ㄍㄨˇ ㄅㄨˋ ㄏㄨㄚˋ', '成語', 3, '「食古不化」之「古」，原或作「生」。學了古代知識而不能充分理解、應用，如同吃了東西不能消化一樣。比喻一味守舊而不知變通。※語或本清．閻爾梅〈破山和尚語錄序〉。', '「食古不化」之「古」，原或作「生」。學了古代知識而不能充分理解、應用，如同吃了東西不能消化一樣。比喻一味守舊而不知變通。※語或本清．閻爾梅〈破山和尚語錄序〉。', '比喻一味守舊而不知變通。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '食古不化的人很難適應快速變化的環境。', '食古不化的人很難適應快速變化的環境。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"391"}'::jsonb)
  ,('active', '一日千里', 'ㄧ ㄖˋ ㄑㄧㄢ ㄌㄧˇ', '成語', 3, '一日能行千里之遠。形容良馬跑得很快。＃語本《莊子．秋水》。後亦用「一日千里」形容速度極快。亦用於比喻進步極快或進展迅速。或比喻人才出眾。', '一日能行千里之遠。形容良馬跑得很快。＃語本《莊子．秋水》。後亦用「一日千里」形容速度極快。亦用於比喻進步極快或進展迅速。或比喻人才出眾。', '形容速度很快。＆比喻進步極快或進展迅速。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '《水滸傳》有位神行太保，走路速度一日千里。', '《水滸傳》有位神行太保，走路速度一日千里。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"392"}'::jsonb)
  ,('active', '一諾千金', 'ㄧ ㄋㄨㄛˋ ㄑㄧㄢ ㄐㄧㄣ', '成語', 3, '一句諾言值千斤黃金。語本《史記．卷一○○．季布欒布列傳．季布》。後用「一諾千金」形容信守承諾，說話算數。', '一句諾言值千斤黃金。語本《史記．卷一○○．季布欒布列傳．季布》。後用「一諾千金」形容信守承諾，說話算數。', '形容信守承諾，說話算數。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他向來一諾千金，很講信用。', '他向來一諾千金，很講信用。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"393"}'::jsonb)
  ,('active', '騎虎難下', 'ㄑㄧˊ ㄏㄨˇ ㄋㄢˊ ㄒㄧㄚˋ', '成語', 3, '騎著老虎，害怕被咬而不敢下來。比喻事情迫於情勢，無法中止，只好繼續做下去。＃語本南朝宋．何法盛〈晉中興書〉。', '騎著老虎，害怕被咬而不敢下來。比喻事情迫於情勢，無法中止，只好繼續做下去。＃語本南朝宋．何法盛〈晉中興書〉。', '比喻事情迫於情勢，無法中止，只好繼續做下去。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我這套計謀目的在引敵深入，讓他們騎虎難下。', '我這套計謀目的在引敵深入，讓他們騎虎難下。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"394"}'::jsonb)
  ,('active', '投鼠忌器', 'ㄊㄡˊ ㄕㄨˇ ㄐㄧˋ ㄑㄧˋ', '成語', 3, '想投擊老鼠，卻怕擊中老鼠身旁的器物而不敢下手。比喻想要除害，但因有所顧忌而不敢下手。語出《漢書．卷四八．賈誼傳》。', '想投擊老鼠，卻怕擊中老鼠身旁的器物而不敢下手。比喻想要除害，但因有所顧忌而不敢下手。語出《漢書．卷四八．賈誼傳》。', '比喻想要除害，但因有所顧忌而不敢下手。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這件事牽涉層面太廣，處理起來總有投鼠忌器之感。', '這件事牽涉層面太廣，處理起來總有投鼠忌器之感。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"395"}'::jsonb)
  ,('active', '坐井觀天', 'ㄗㄨㄛˋ ㄐㄧㄥˇ ㄍㄨㄢ ㄊㄧㄢ', '成語', 3, '坐在井底仰望天空。比喻人眼界狹小，見識不廣。語出唐．韓愈〈原道〉。', '坐在井底仰望天空。比喻人眼界狹小，見識不廣。語出唐．韓愈〈原道〉。', '比喻人眼界狹小，見識不廣。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這是坐井觀天的看法，不值得重視。', '這是坐井觀天的看法，不值得重視。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"396"}'::jsonb)
  ,('active', '門可羅雀', 'ㄇㄣˊ ㄎㄜˇ ㄌㄨㄛˊ ㄑㄩㄝˋ', '成語', 3, '門前冷清，空曠得可張網捕雀。形容做官的人失勢後賓客稀少的景況。語本《史記．卷一二○．汲鄭列傳》。後亦用「門可羅雀」泛指一般來客稀少、門庭冷清的景況。', '門前冷清，空曠得可張網捕雀。形容做官的人失勢後賓客稀少的景況。語本《史記．卷一二○．汲鄭列傳》。後亦用「門可羅雀」泛指一般來客稀少、門庭冷清的景況。', '形容做官的人失勢後賓客稀少的景況。＆泛指一般來客稀少、門庭冷清的景況。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我現在無官一身輕，門可羅雀添情趣。', '我現在無官一身輕，門可羅雀添情趣。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"397"}'::jsonb)
  ,('active', '攀龍附鳳', 'ㄆㄢ ㄌㄨㄥˊ ㄈㄨˋ ㄈㄥˋ', '成語', 3, '攀附著龍或鳳。比喻依仗有聲望的人。語本漢．揚雄《法言．淵騫》。後用「攀龍附鳳」比喻巴結權貴，以求晉升。', '攀附著龍或鳳。比喻依仗有聲望的人。語本漢．揚雄《法言．淵騫》。後用「攀龍附鳳」比喻巴結權貴，以求晉升。 △「趨炎附勢」、「攀龍附驥」', '比喻巴結權貴，以求晉升。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他能有今天的局面，就是攀龍附鳳得來的。', '他能有今天的局面，就是攀龍附鳳得來的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"398"}'::jsonb)
  ,('active', '易如反掌', 'ㄧˋ ㄖㄨˊ ㄈㄢˇ ㄓㄤˇ', '成語', 3, '像翻轉手掌一般的容易。比喻事情非常容易做到。語本《孟子．公孫丑上》。', '像翻轉手掌一般的容易。比喻事情非常容易做到。語本《孟子．公孫丑上》。 △「易若轉圜」', '比喻事情非常容易做到。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '搬桌子？易如反掌，我來幫忙吧！', '搬桌子？易如反掌，我來幫忙吧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"399"}'::jsonb)
  ,('active', '膾炙人口', 'ㄎㄨㄞˋ ㄓˋ ㄖㄣˊ ㄎㄡˇ', '成語', 3, '膾，細切肉；炙，烤肉。膾、炙皆人間美味，「膾炙人口」指美味的食物人人愛吃，或比喻美妙的詩文為人所讚賞、傳誦。語出唐．林嵩〈周朴詩集序〉。後亦用「膾炙人口」比喻事物精妙而備受稱誦。', '膾，細切肉；炙，烤肉。膾、炙皆人間美味，「膾炙人口」指美味的食物人人愛吃，或比喻美妙的詩文為人所讚賞、傳誦。語出唐．林嵩〈周朴詩集序〉。後亦用「膾炙人口」比喻事物精妙而備受稱誦。', '美味的食物人人愛吃。＆比喻美妙的詩文為人所讚賞、傳誦。褒義。＆比喻事物精妙而備受稱誦。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '桌上擺滿了膾炙人口的佳肴，令人垂涎欲滴。', '桌上擺滿了膾炙人口的佳肴，令人垂涎欲滴。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"400"}'::jsonb)
  ,('active', '趾高氣揚', 'ㄓˇ ㄍㄠ ㄑㄧˋ ㄧㄤˊ', '成語', 3, '走路時腳抬得很高，樣子顯得十分神氣。形容人驕傲自滿、得意忘形。＃語本《戰國策．齊策三》。', '走路時腳抬得很高，樣子顯得十分神氣。形容人驕傲自滿、得意忘形。＃語本《戰國策．齊策三》。', '形容人驕傲自滿、得意忘形。多具貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他那趾高氣揚的態度，實在令人看不慣。', '他那趾高氣揚的態度，實在令人看不慣。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"401"}'::jsonb)
  ,('active', '唾面自乾', 'ㄊㄨㄛˋ ㄇㄧㄢˋ ㄗˋ ㄍㄢ', '成語', 3, '當別人吐口水在臉上時，不擦拭而讓它自己乾掉的故事。比喻逆來順受，寬容忍讓。＃典出唐．劉餗《隋唐嘉話》卷下。', '當別人吐口水在臉上時，不擦拭而讓它自己乾掉的故事。比喻逆來順受，寬容忍讓。＃典出唐．劉餗《隋唐嘉話》卷下。', '比喻逆來順受，寬容忍讓。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種唾面自乾的作法過於懦弱，我不欣賞。', '這種唾面自乾的作法過於懦弱，我不欣賞。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"402"}'::jsonb)
  ,('active', '推心置腹', 'ㄊㄨㄟ ㄒㄧㄣ ㄓˋ ㄈㄨˋ', '成語', 3, '把赤忱之心推到人家肚子裡。比喻以至誠待人。＃語本《東觀漢記．卷一．光武帝紀》。', '把赤忱之心推到人家肚子裡。比喻以至誠待人。＃語本《東觀漢記．卷一．光武帝紀》。', '比喻以至誠待人。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他對朋友向來推心置腹，坦誠相待。', '他對朋友向來推心置腹，坦誠相待。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"403"}'::jsonb)
  ,('active', '病入膏肓', 'ㄅㄧㄥˋ ㄖㄨˋ ㄍㄠ ㄏㄨㄤ', '成語', 3, '膏，心下脂肪；肓，心臟和橫膈膜之間。中醫之「膏肓」即指心之下，膈之上的部位。膏肓相傳是身體內藥力所不及的地方。「病入膏肓」原指病位深隱難治，病情危重，無藥可救。典出《左傳．成公十年》。後用「病入膏肓」比喻人、事已到無可挽回的程度。', '膏，心下脂肪；肓，心臟和橫膈膜之間。中醫之「膏肓」即指心之下，膈之上的部位。膏肓相傳是身體內藥力所不及的地方。「病入膏肓」原指病位深隱難治，病情危重，無藥可救。典出《左傳．成公十年》。後用「病入膏肓」比喻人、事已到無可挽回的程度。', '指人病重，無藥可救。 ＆比喻人、事已到無可挽回的程度。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '患病就得就醫，難道要等到病入膏肓嗎？', '患病就得就醫，難道要等到病入膏肓嗎？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"404"}'::jsonb)
  ,('active', '蕭規曹隨', 'ㄒㄧㄠ ㄍㄨㄟ ㄘㄠˊ ㄙㄨㄟˊ', '成語', 3, '漢代曹參繼蕭何為相國，舉事皆無所變更。＃典出《史記．卷五四．曹相國世家》。後用「蕭規曹隨」比喻後人依循前人所訂的規章辦事。', '漢代曹參繼蕭何為相國，舉事皆無所變更。＃典出《史記．卷五四．曹相國世家》。後用「蕭規曹隨」比喻後人依循前人所訂的規章辦事。 △「率由舊章」', '比喻後人依循前人所訂的規章辦事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '自他上任以來，一切行事都依照舊章，蕭規曹隨。', '自他上任以來，一切行事都依照舊章，蕭規曹隨。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"405"}'::jsonb)
  ,('active', '庸人自擾', 'ㄩㄥ ㄖㄣˊ ㄗˋ ㄖㄠˇ', '成語', 3, '庸碌的人無端自尋煩惱。語本《舊唐書．卷八八．陸元方列傳》。', '庸碌的人無端自尋煩惱。語本《舊唐書．卷八八．陸元方列傳》。 △「杞人憂天」。', '比喻庸碌的人無端自尋煩惱。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你所擔心的事，在我看來皆為庸人自擾。', '你所擔心的事，在我看來皆為庸人自擾。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"406"}'::jsonb)
  ,('active', '緣木求魚', 'ㄩㄢˊ ㄇㄨˋ ㄑㄧㄡˊ ㄩˊ', '成語', 3, '爬到樹上去抓魚。比喻用錯方法，徒勞無功。語出《孟子．梁惠王上》。', '爬到樹上去抓魚。比喻用錯方法，徒勞無功。語出《孟子．梁惠王上》。', '比喻用錯方法，徒勞無功。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '不努力卻想發財，無異是緣木求魚！', '不努力卻想發財，無異是緣木求魚！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"407"}'::jsonb)
  ,('active', '雙管齊下', 'ㄕㄨㄤ ㄍㄨㄢˇ ㄑㄧˊ ㄒㄧㄚˋ', '成語', 3, '手握雙管同時作畫。＃語本唐．朱景玄《唐朝名畫錄．神品下．張藻》。後用「雙管齊下」比喻同時採用兩種辦法來做事。', '手握雙管同時作畫。＃語本唐．朱景玄《唐朝名畫錄．神品下．張藻》。後用「雙管齊下」比喻同時採用兩種辦法來做事。', '比喻同時採用兩種辦法來做事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '學習語文應該聽與寫雙管齊下，收效才快。', '學習語文應該聽與寫雙管齊下，收效才快。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"408"}'::jsonb)
  ,('active', '一言九鼎', 'ㄧ ㄧㄢˊ ㄐㄧㄡˇ ㄉㄧㄥˇ', '成語', 3, '九鼎，傳說中夏禹的傳國寶器。「一言九鼎」形容說話很有分量。語本《史記．卷七六．平原君虞卿列傳．平原君》。後亦用「一言九鼎」形容說話很有信用。', '九鼎，傳說中夏禹的傳國寶器。「一言九鼎」形容說話很有分量。語本《史記．卷七六．平原君虞卿列傳．平原君》。後亦用「一言九鼎」形容說話很有信用。 △「三寸不爛之舌」', '形容說話很有分量。＆形容說話很有信用。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他是會中大老，向來一言九鼎。', '他是會中大老，向來一言九鼎。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"409"}'::jsonb)
  ,('active', '自相矛盾', 'ㄗˋ ㄒㄧㄤ ㄇㄠˊ ㄉㄨㄣˋ', '成語', 3, '比喻言語或行事前後無法呼應，互相牴觸。◎典出《韓非子．難一》。', '比喻言語或行事前後無法呼應，互相牴觸。◎典出《韓非子．難一》。', '比喻言語或行事前後無法呼應，互相牴觸。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你的論點根本自相矛盾，如何說服他人？', '你的論點根本自相矛盾，如何說服他人？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"410"}'::jsonb)
  ,('active', '舉案齊眉', 'ㄐㄩˇ ㄢˋ ㄑㄧˊ ㄇㄟˊ', '成語', 3, '將放置飯菜的木盤高舉，與眉平齊，為東漢孟光對其夫梁鴻敬愛的表示。＃典出《東觀漢記．卷一八．梁鴻列傳》。後用「舉案齊眉」比喻夫妻相敬如賓。', '將放置飯菜的木盤高舉，與眉平齊，為東漢孟光對其夫梁鴻敬愛的表示。＃典出《東觀漢記．卷一八．梁鴻列傳》。後用「舉案齊眉」比喻夫妻相敬如賓。', '比喻夫妻相敬如賓。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '夫妻之間能舉案齊眉，更見一份親密。', '夫妻之間能舉案齊眉，更見一份親密。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"411"}'::jsonb)
  ,('active', '閉門造車', 'ㄅㄧˋ ㄇㄣˊ ㄗㄠˋ ㄐㄩ', '成語', 3, '關起門來，按照一定的規格在家裡造車。比喻依循著一定的原則行事。＃語出《祖堂集．卷二○．五冠山瑞雲寺和尚》。後用「閉門造車」比喻凡事只憑主觀辦事，不問是否切合實際。', '關起門來，按照一定的規格在家裡造車。比喻依循著一定的原則行事。＃語出《祖堂集．卷二○．五冠山瑞雲寺和尚》。後用「閉門造車」比喻凡事只憑主觀辦事，不問是否切合實際。 △「閉門造車，出門合轍」', '比喻凡事只憑主觀辦事，不問是否切合實際。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這些閉門造車的產品，根本不符市場需要。', '這些閉門造車的產品，根本不符市場需要。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"412"}'::jsonb)
  ,('active', '歧路亡羊', 'ㄑㄧˊ ㄌㄨˋ ㄨㄤˊ ㄧㄤˊ', '成語', 3, '岔路很多，因此而走失了一隻羊。比喻事理繁雜多變，求道者誤入迷途，而終無所成。典出《列子．說符》。', '岔路很多，因此而走失了一隻羊。比喻事理繁雜多變，求道者誤入迷途，而終無所成。典出《列子．說符》。', '比喻事理繁雜多變，求道者誤入迷途，而終無所成。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '討論這麼複雜的問題，假如不能掌握要點，就會歧路亡羊。', '討論這麼複雜的問題，假如不能掌握要點，就會歧路亡羊。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"413"}'::jsonb)
  ,('active', '車水馬龍', 'ㄔㄜ ㄕㄨㄟˇ ㄇㄚˇ ㄌㄨㄥˊ', '成語', 3, '門前車馬往來不絕。＃語本《東觀漢記．卷六．外戚列傳．明德馬皇后》。後用「車水馬龍」形容繁華熱鬧的景象。', '門前車馬往來不絕。＃語本《東觀漢記．卷六．外戚列傳．明德馬皇后》。後用「車水馬龍」形容繁華熱鬧的景象。', '形容繁華熱鬧的景象。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我喜歡鄉下的寧靜，勝過於都市的車水馬龍。', '我喜歡鄉下的寧靜，勝過於都市的車水馬龍。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"414"}'::jsonb)
  ,('active', '先發制人', 'ㄒㄧㄢ ㄈㄚ ㄓˋ ㄖㄣˊ', '成語', 3, '凡事先下手取得先機，才能制伏對方。＃語本《史記．卷七．項羽本紀》。', '凡事先下手取得先機，才能制伏對方。＃語本《史記．卷七．項羽本紀》。', '凡事先下手取得先機，才能制伏對方。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在戰場上對決，要先發制人，搶得先機。', '在戰場上對決，要先發制人，搶得先機。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"415"}'::jsonb)
  ,('active', '洛陽紙貴', 'ㄌㄨㄛˋ ㄧㄤˊ ㄓˇ ㄍㄨㄟˋ', '成語', 3, '由於左思的〈三都賦〉，時人競相傳寫，因而洛陽為之紙貴。典出《晉書．卷九二．文苑列傳．左思》。後用「洛陽紙貴」形容著作風行一時，流傳甚廣。', '由於左思的〈三都賦〉，時人競相傳寫，因而洛陽為之紙貴。典出《晉書．卷九二．文苑列傳．左思》。後用「洛陽紙貴」形容著作風行一時，流傳甚廣。 △「都城紙貴」', '形容作品風行一時，流傳甚廣。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這部作品印行後，一時洛陽紙貴。', '這部作品印行後，一時洛陽紙貴。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"416"}'::jsonb)
  ,('active', '孤陋寡聞', 'ㄍㄨ ㄌㄡˋ ㄍㄨㄚˇ ㄨㄣˊ', '成語', 3, '寡，少。形容學識淺薄，見聞不廣。語出《禮記．學記》。', '寡，少。形容學識淺薄，見聞不廣。語出《禮記．學記》。', '形容學識淺薄，見聞不廣。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '關於電腦，我孤陋寡聞，得多向你請教。', '關於電腦，我孤陋寡聞，得多向你請教。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"417"}'::jsonb)
  ,('active', '滿腹經綸', 'ㄇㄢˇ ㄈㄨˋ ㄐㄧㄥ ㄌㄨㄣˊ', '成語', 3, '經綸，整理絲線，引申為規劃、治理。「滿腹經綸」形容才識豐富，具有處理大事的才能。※語或本《易經．屯卦．象》。', '經綸，整理絲線，引申為規劃、治理。「滿腹經綸」形容才識豐富，具有處理大事的才能。※語或本《易經．屯卦．象》。 △「滿腹經籍」', '形容才識豐富，具有處理大事的才能。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '歷史上不知有多少滿腹經綸的人才被埋沒了。', '歷史上不知有多少滿腹經綸的人才被埋沒了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"418"}'::jsonb)
  ,('active', '飲鴆止渴', 'ㄧㄣˇ ㄓㄣˋ ㄓˇ ㄎㄜˇ', '成語', 3, '「飲鴆止渴」之「鴆」，典源作「酖」。「酖」通「鴆」。鴆，以鴆鳥羽毛浸製而成的毒酒。「飲鴆止渴」指飲毒酒以解渴。比喻只求解決眼前困難，而不顧將來更大的禍患。語本《後漢書．卷四八．楊李翟應霍爰徐列傳．霍諝》。', '「飲鴆止渴」之「鴆」，典源作「酖」。「酖」通「鴆」。鴆，以鴆鳥羽毛浸製而成的毒酒。「飲鴆止渴」指飲毒酒以解渴。比喻只求解決眼前困難，而不顧將來更大的禍患。語本《後漢書．卷四八．楊李翟應霍爰徐列傳．霍諝》。', '比喻只求解決眼前困難，而不顧將來更大的禍患。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你老是靠喝酒來逃避現實，無異於飲鴆止渴。', '你老是靠喝酒來逃避現實，無異於飲鴆止渴。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"419"}'::jsonb)
  ,('active', '退避三舍', 'ㄊㄨㄟˋ ㄅㄧˋ ㄙㄢ ㄕㄜˋ', '成語', 3, '舍，古人以三十里為一舍。「退避三舍」指作戰時，將部隊往後撤退九十里。◎語本《左傳．僖公二十三年》。後用「退避三舍」比喻主動退讓，不與人相爭。', '舍，古人以三十里為一舍。「退避三舍」指作戰時，將部隊往後撤退九十里。◎語本《左傳．僖公二十三年》。後用「退避三舍」比喻主動退讓，不與人相爭。', '比喻主動退讓，不與人相爭。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '惹他做啥？先退避三舍吧！', '惹他做啥？先退避三舍吧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"420"}'::jsonb)
  ,('active', '世外桃源', 'ㄕˋ ㄨㄞˋ ㄊㄠˊ ㄩㄢˊ', '成語', 3, '與世隔絕，開滿桃花的安樂土。典出晉．陶潛〈桃花源記〉。後用「世外桃源」比喻風景優美而人跡罕至的地方。亦用於比喻心目中理想的世界。', '與世隔絕，開滿桃花的安樂土。典出晉．陶潛〈桃花源記〉。後用「世外桃源」比喻風景優美而人跡罕至的地方。亦用於比喻心目中理想的世界。 △「豁然開朗」', '比喻風景優美而人跡罕至的地方。＆比喻心目中理想的世界。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '香格里拉是傳說中的世外桃源。', '香格里拉是傳說中的世外桃源。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"421"}'::jsonb)
  ,('active', '水深火熱', 'ㄕㄨㄟˇ ㄕㄣ ㄏㄨㄛˇ ㄖㄜˋ', '成語', 3, '處在深水熱火中。比喻處境非常艱困、痛苦。語本《孟子．梁惠王下》。', '處在深水熱火中。比喻處境非常艱困、痛苦。語本《孟子．梁惠王下》。 △「火熱湯沸」、「簞食壺漿」', '比喻處境非常艱困、痛苦。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '農民生活已水深火熱了，還要對他們怎樣？', '農民生活已水深火熱了，還要對他們怎樣？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"422"}'::jsonb)
  ,('active', '假公濟私', 'ㄐㄧㄚˇ ㄍㄨㄥ ㄐㄧˋ ㄙ', '成語', 3, '假借公家的名義以謀取個人的私利。＃語本《漢書．卷六○．杜周傳》。', '假借公家的名義以謀取個人的私利。＃語本《漢書．卷六○．杜周傳》。', '假借公家的名義以謀取個人的私利。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我們公司不能容納這種假公濟私的人。', '我們公司不能容納這種假公濟私的人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"423"}'::jsonb)
  ,('active', '孤掌難鳴', 'ㄍㄨ ㄓㄤˇ ㄋㄢˊ ㄇㄧㄥˊ', '成語', 3, '一個巴掌難以拍出聲響。比喻人孤立無助，不能成事。語本《韓非子．功名》。', '一個巴掌難以拍出聲響。比喻人孤立無助，不能成事。語本《韓非子．功名》。', '比喻人孤立無助，不能成事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你就算再能幹，若旁邊沒人協助，也是孤掌難鳴。', '你就算再能幹，若旁邊沒人協助，也是孤掌難鳴。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"424"}'::jsonb)
  ,('active', '偃旗息鼓', 'ㄧㄢˇ ㄑㄧˊ ㄒㄧˊ ㄍㄨˇ', '成語', 3, '軍隊放倒旌旗，停止戰鼓。形容不露行蹤。語出《雲別傳》。後亦用「偃旗息鼓」比喻事情中斷或聲勢減弱。', '軍隊放倒旌旗，停止戰鼓。形容不露行蹤。語出《雲別傳》。後亦用「偃旗息鼓」比喻事情中斷或聲勢減弱。 △「偃兵息甲」、「鳴金收兵」', '軍隊放倒旌旗，停止戰鼓。形容不露行蹤。＆比喻事情中斷或聲勢減弱。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '此行既是偷襲，當然得偃旗息鼓，隱密行蹤。', '此行既是偷襲，當然得偃旗息鼓，隱密行蹤。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"425"}'::jsonb)
  ,('active', '妄自尊大', 'ㄨㄤˋ ㄗˋ ㄗㄨㄣ ㄉㄚˋ', '成語', 3, '狂妄地自尊自大。語出《後漢書．卷二四．馬援列傳》。', '狂妄地自尊自大。語出《後漢書．卷二四．馬援列傳》。 △「不修邊幅」、「夜郎自大」', '狂妄地自尊自大。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '稍有成就就妄自尊大的人，難成大器。', '稍有成就就妄自尊大的人，難成大器。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"426"}'::jsonb)
  ,('active', '得心應手', 'ㄉㄜˊ ㄒㄧㄣ ㄧㄥˋ ㄕㄡˇ', '成語', 3, '心裡怎麼想，手便能怎麼做。比喻技藝熟練，運用自如。＃語本《莊子．天道》。 後亦用「得心應手」比喻做事順利。', '心裡怎麼想，手便能怎麼做。比喻技藝熟練，運用自如。＃語本《莊子．天道》。 後亦用「得心應手」比喻做事順利。', '比喻技藝熟練，運用自如。＆比喻做事順利。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這把菜刀雖舊，但使來得心應手。', '這把菜刀雖舊，但使來得心應手。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"427"}'::jsonb)
  ,('active', '乘風破浪', 'ㄔㄥˊ ㄈㄥ ㄆㄛˋ ㄌㄤˋ', '成語', 3, '順著風，破浪前進。＃語本《宋書．卷七六．列傳．宗慤》。後亦用「乘風破浪」比喻人志向遠大，不畏艱難，奮勇前進。', '順著風，破浪前進。＃語本《宋書．卷七六．列傳．宗慤》。後亦用「乘風破浪」比喻人志向遠大，不畏艱難，奮勇前進。 △「披荊斬棘」', '順著風，破浪前進。＆比喻人志向遠大，不畏艱難，奮勇前進。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我矗立船首，張開雙臂，體會一下乘風破浪的感覺。', '我矗立船首，張開雙臂，體會一下乘風破浪的感覺。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"428"}'::jsonb)
  ,('active', '滿城風雨', 'ㄇㄢˇ ㄔㄥˊ ㄈㄥ ㄩˇ', '成語', 3, '滿城，到處都颳風下雨的景象。本指自然現象，這種現象多出現在重陽或晚春時節。※語或出宋．釋惠洪《冷齋夜話．卷四．滿城風雨近重陽》。後「滿城風雨」語義一轉，也用來指事情一經傳出，便流言四起，到處議論紛紛。', '滿城，到處都颳風下雨的景象。本指自然現象，這種現象多出現在重陽或晚春時節。※語或出宋．釋惠洪《冷齋夜話．卷四．滿城風雨近重陽》。後「滿城風雨」語義一轉，也用來指事情一經傳出，便流言四起，到處議論紛紛。', '形容到處颳風下雨的景象。＆指事情一經傳出，便流言四起，到處議論紛紛。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '臺北現在滿城風雨，整座都市正被颱風肆虐著。', '臺北現在滿城風雨，整座都市正被颱風肆虐著。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"429"}'::jsonb)
  ,('active', '敝帚自珍', 'ㄅㄧˋ ㄓㄡˇ ㄗˋ ㄓㄣ', '成語', 3, '自家的破舊掃把，卻珍愛如寶。比喻東西雖不好，卻因為是自己所擁有，故非常珍視。語本《東觀漢記．卷一．光武帝紀》。', '自家的破舊掃把，卻珍愛如寶。比喻東西雖不好，卻因為是自己所擁有，故非常珍視。語本《東觀漢記．卷一．光武帝紀》。', '比喻東西雖不好，卻因為是自己所擁有，故非常珍視。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '文章總是自己的好，敝帚自珍，人之常情。', '文章總是自己的好，敝帚自珍，人之常情。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"430"}'::jsonb)
  ,('active', '兔死狗烹', 'ㄊㄨˋ ㄙˇ ㄍㄡˇ ㄆㄥ', '成語', 3, '兔子死盡了，用來捕兔的獵狗因為失去了作用而被烹食。比喻事成之後，有功之人即遭到殺戮或見棄的命運。＃語本《淮南子．說林》。', '兔子死盡了，用來捕兔的獵狗因為失去了作用而被烹食。比喻事成之後，有功之人即遭到殺戮或見棄的命運。＃語本《淮南子．說林》。 △「鳥盡弓藏」、「鳥盡弓藏，兔死狗烹」', '比喻事成之後，有功之人即遭到殺戮或見棄的命運。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '你要小心別跟錯人了，免得到時候兔死狗烹。', '你要小心別跟錯人了，免得到時候兔死狗烹。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"431"}'::jsonb)
  ,('active', '拋磚引玉', 'ㄆㄠ ㄓㄨㄢ ㄧㄣˇ ㄩˋ', '成語', 3, '將磚拋出，引回玉來。※＃語或出《景德傳燈錄．卷一○．趙州觀音院從諗禪師》。後用「拋磚引玉」比喻自己先發表粗陋的詩文或不成熟的意見，以引出別人的佳作或高論，多用作自謙之詞。亦用於比喻以身作則，引發眾人響應。', '將磚拋出，引回玉來。※＃語或出《景德傳燈錄．卷一○．趙州觀音院從諗禪師》。後用「拋磚引玉」比喻自己先發表粗陋的詩文或不成熟的意見，以引出別人的佳作或高論，多用作自謙之詞。亦用於比喻以身作則，引發眾人響應。', '比喻自己先發表粗陋的詩文或不成熟的意見，以引出別人的佳作或高論。多用作自謙之詞。＆比喻以身作則，引發眾人響應。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我藉著這段話拋磚引玉，希望各位能有許多精彩的論見。', '我藉著這段話拋磚引玉，希望各位能有許多精彩的論見。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"432"}'::jsonb)
  ,('active', '門庭若市', 'ㄇㄣˊ ㄊㄧㄥˊ ㄖㄨㄛˋ ㄕˋ', '成語', 3, '門庭間來往的人很多，像市集一般熱鬧。比喻上門來的人很多。語出《戰國策．齊策一》。', '門庭間來往的人很多，像市集一般熱鬧。比喻上門來的人很多。語出《戰國策．齊策一》。', '比喻上門來的人很多。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '祝你的飯店高朋滿座，門庭若市。', '祝你的飯店高朋滿座，門庭若市。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"433"}'::jsonb)
  ,('active', '殺身成仁', 'ㄕㄚ ㄕㄣ ㄔㄥˊ ㄖㄣˊ', '成語', 3, '為了成全仁德而犧牲生命。語出《論語．衛靈公》。後用「殺身成仁」指為正義或崇高的理想而犧牲生命。', '為了成全仁德而犧牲生命。語出《論語．衛靈公》。後用「殺身成仁」指為正義或崇高的理想而犧牲生命。 △「捨生取義」', '指為正義或崇高的理想而犧牲生命。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他殺身成仁的典範，將永留人間。', '他殺身成仁的典範，將永留人間。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"434"}'::jsonb)
  ,('active', '一視同仁', 'ㄧ ㄕˋ ㄊㄨㄥˊ ㄖㄣˊ', '成語', 3, '同樣以博愛的仁心，對待所有的人及禽獸。語出唐．韓愈〈原人〉。後用「一視同仁」指平等待人，不分親疏厚薄。', '同樣以博愛的仁心，對待所有的人及禽獸。語出唐．韓愈〈原人〉。後用「一視同仁」指平等待人，不分親疏厚薄。', '指平等待人，不分親疏厚薄。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '老師對待學生應該一視同仁，無所偏愛。', '老師對待學生應該一視同仁，無所偏愛。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"435"}'::jsonb)
  ,('active', '雪中送炭', 'ㄒㄩㄝˇ ㄓㄨㄥ ㄙㄨㄥˋ ㄊㄢˋ', '成語', 3, '在下雪天送炭給人取暖。比喻在人艱困危急之時，給予適時的援助。※語或本唐．釋德行《四字經．甲乙》。', '在下雪天送炭給人取暖。比喻在人艱困危急之時，給予適時的援助。※語或本唐．釋德行《四字經．甲乙》。', '比喻在人艱困危急之時，給予適時的援助。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '讓人最受用的是雪中送炭，而不是錦上添花。', '讓人最受用的是雪中送炭，而不是錦上添花。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"436"}'::jsonb)
  ,('active', '甘拜下風', 'ㄍㄢ ㄅㄞˋ ㄒㄧㄚˋ ㄈㄥ', '成語', 3, '下風，風所吹向的那方。「甘拜下風」指待在下邊，聽候吩咐。＃語本《左傳．僖公十五年》。後用「甘拜下風」表示自認不如，由衷佩服。', '下風，風所吹向的那方。「甘拜下風」指待在下邊，聽候吩咐。＃語本《左傳．僖公十五年》。後用「甘拜下風」表示自認不如，由衷佩服。', '表示自認不如，由衷佩服。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '既然對方已甘拜下風，比試就到此為止。', '既然對方已甘拜下風，比試就到此為止。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"437"}'::jsonb)
  ,('active', '無地自容', 'ㄨˊ ㄉㄧˋ ㄗˋ ㄖㄨㄥˊ', '成語', 3, '沒地方可以藏身。形容羞愧至極。語本《史記．卷七七．魏公子列傳》。', '沒地方可以藏身。形容羞愧至極。語本《史記．卷七七．魏公子列傳》。 △「容身無地」', '形容羞愧至極。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '被當面指出所犯的錯誤時，他直羞得無地自容。', '被當面指出所犯的錯誤時，他直羞得無地自容。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"438"}'::jsonb)
  ,('active', '過河拆橋', 'ㄍㄨㄛˋ ㄏㄜˊ ㄔㄞ ㄑㄧㄠˊ', '成語', 3, '渡過了河就把橋拆掉。比喻不念舊情，忘恩負義。語出《元史．卷一四二．徹里帖木兒列傳》。', '渡過了河就把橋拆掉。比喻不念舊情，忘恩負義。語出《元史．卷一四二．徹里帖木兒列傳》。', '比喻不念舊情，忘恩負義。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種過河拆橋、忘恩負義的人，不必理他！', '這種過河拆橋、忘恩負義的人，不必理他！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"439"}'::jsonb)
  ,('active', '前倨後恭', 'ㄑㄧㄢˊ ㄐㄩˋ ㄏㄡˋ ㄍㄨㄥ', '成語', 3, '先前傲慢無禮，後又謙卑恭敬。比喻待人勢利，態度轉變迅速。＃語出《戰國策．秦策一》。', '先前傲慢無禮，後又謙卑恭敬。比喻待人勢利，態度轉變迅速。＃語出《戰國策．秦策一》。 △「引錐刺股」、「今恭昔慢」', '比喻待人勢利，態度轉變迅速。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種前倨後恭的勢利小人，不可深交！', '這種前倨後恭的勢利小人，不可深交！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"440"}'::jsonb)
  ,('active', '弄巧成拙', 'ㄋㄨㄥˋ ㄑㄧㄠˇ ㄔㄥˊ ㄓㄨㄛˊ', '成語', 3, '本想賣弄才能、聰明，卻反而做了蠢事。比喻枉費心機。※語或出《五燈會元．卷三．江西馬祖道一禪師》。', '本想賣弄才能、聰明，卻反而做了蠢事。比喻枉費心機。※語或出《五燈會元．卷三．江西馬祖道一禪師》。', '比喻枉費心機。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '讀書沒有捷徑，投機取巧，必然弄巧成拙。', '讀書沒有捷徑，投機取巧，必然弄巧成拙。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"441"}'::jsonb)
  ,('active', '噤若寒蟬', 'ㄐㄧㄣˋ ㄖㄨㄛˋ ㄏㄢˊ ㄔㄢˊ', '成語', 3, '噤，閉口不作聲。「噤若寒蟬」指像寒冷季節時的蟬，一聲不響。比喻不敢說話。語本《後漢書．卷六七．黨錮列傳．杜密》。', '噤，閉口不作聲。「噤若寒蟬」指像寒冷季節時的蟬，一聲不響。比喻不敢說話。語本《後漢書．卷六七．黨錮列傳．杜密》。', '比喻不敢說話。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '道不行則隱，莫怪我噤若寒蟬，不談國事。', '道不行則隱，莫怪我噤若寒蟬，不談國事。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"442"}'::jsonb)
  ,('active', '瓜田李下', 'ㄍㄨㄚ ㄊㄧㄢˊ ㄌㄧˇ ㄒㄧㄚˋ', '成語', 3, '在瓜田裡不彎身穿鞋，在李樹下不舉手整理帽子。語本無名氏〈君子行〉。後用「瓜田李下」比喻容易引起懷疑的場合。', '在瓜田裡不彎身穿鞋，在李樹下不舉手整理帽子。語本無名氏〈君子行〉。後用「瓜田李下」比喻容易引起懷疑的場合。', '比喻容易引起懷疑的場合。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '考試時東張西望，就難免有瓜田李下的作弊嫌疑。', '考試時東張西望，就難免有瓜田李下的作弊嫌疑。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"443"}'::jsonb)
  ,('active', '望塵莫及', 'ㄨㄤˋ ㄔㄣˊ ㄇㄛˋ ㄐㄧˊ', '成語', 3, '只能遠望前面車馬揚起的塵土，而無法趕得上。比喻遠遠落在他人之後。＃語本《莊子．田子方》。', '只能遠望前面車馬揚起的塵土，而無法趕得上。比喻遠遠落在他人之後。＃語本《莊子．田子方》。 △「失之交臂」、「亦步亦趨」、「奔逸絕塵」、「瞠乎其後」', '比喻遠遠落在他人之後。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他能力太強了，讓我們望塵莫及。', '他能力太強了，讓我們望塵莫及。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"444"}'::jsonb)
  ,('active', '半途而廢', 'ㄅㄢˋ ㄊㄨˊ ㄦˊ ㄈㄟˋ', '成語', 3, '「半途而廢」之「途」，典源作「塗」。事情沒做成功就停止。比喻做事情有始無終。語本《禮記．中庸》。', '「半途而廢」之「途」，典源作「塗」。事情沒做成功就停止。比喻做事情有始無終。語本《禮記．中庸》。 △「中道而廢」', '比喻做事情有始無終。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '一個人做事情老是半途而廢，怎能有成？', '一個人做事情老是半途而廢，怎能有成？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"445"}'::jsonb)
  ,('active', '一籌莫展', 'ㄧ ㄔㄡˊ ㄇㄛˋ ㄓㄢˇ', '成語', 3, '籌，計策、計謀。「一籌莫展」指一點計策也施展不出來。比喻毫無辦法。語本《宋史．卷四三四．儒林列傳．蔡幼學》。', '籌，計策、計謀。「一籌莫展」指一點計策也施展不出來。比喻毫無辦法。語本《宋史．卷四三四．儒林列傳．蔡幼學》。', '比喻毫無辦法。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他聳聳肩，攤攤手，表示一籌莫展。', '他聳聳肩，攤攤手，表示一籌莫展。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"446"}'::jsonb)
  ,('active', '抱薪救火', 'ㄅㄠˋ ㄒㄧㄣ ㄐㄧㄡˋ ㄏㄨㄛˇ', '成語', 3, '抱著木柴去救火，比喻處理事情的方法錯誤，既無法達成目的，反而情勢更為惡劣。比喻用錯方法，而致禍害加深。＃語出《戰國策．魏策三》。', '抱著木柴去救火，比喻處理事情的方法錯誤，既無法達成目的，反而情勢更為惡劣。比喻用錯方法，而致禍害加深。＃語出《戰國策．魏策三》。 △「潑油救火」', '比喻用錯方法，而致禍害加深。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '對方需索無度，如果一味應了他，那我們豈不是在抱薪救火？', '對方需索無度，如果一味應了他，那我們豈不是在抱薪救火？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"447"}'::jsonb)
  ,('active', '大器晚成', 'ㄉㄚˋ ㄑㄧˋ ㄨㄢˇ ㄔㄥˊ', '成語', 3, '貴重的器物需要長時間才能完成。＃語出《老子》第四一章。後用「大器晚成」比喻卓越的人才往往成就較晚。', '貴重的器物需要長時間才能完成。＃語出《老子》第四一章。後用「大器晚成」比喻卓越的人才往往成就較晚。', '比喻卓越的人才往往成就較晚。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這位畫家大器晚成，年輕時毫無名氣。', '這位畫家大器晚成，年輕時毫無名氣。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"448"}'::jsonb)
  ,('active', '莫逆之交', 'ㄇㄛˋ ㄋㄧˋ ㄓ ㄐㄧㄠ', '成語', 3, '莫逆，相契而無所違逆。「莫逆之友」指心意相投的朋友。語本《莊子．大宗師》。', '莫逆，相契而無所違逆。「莫逆之友」指心意相投的朋友。語本《莊子．大宗師》。', '心意相投的朋友。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我看他們倆都不夠真誠，算不上是莫逆之交。', '我看他們倆都不夠真誠，算不上是莫逆之交。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"449"}'::jsonb)
  ,('active', '按圖索驥', 'ㄢˋ ㄊㄨˊ ㄙㄨㄛˇ ㄐㄧˋ', '成語', 3, '按照前人所畫的圖象，去尋求當代的良馬。比喻做事拘泥成規，呆板不知變通。語本《漢書．卷六七．楊胡米梅云傳．梅福》。後亦用「按圖索驥」比喻按照所掌握的線索辦事。', '按照前人所畫的圖象，去尋求當代的良馬。比喻做事拘泥成規，呆板不知變通。語本《漢書．卷六七．楊胡米梅云傳．梅福》。後亦用「按圖索驥」比喻按照所掌握的線索辦事。', '比喻做事拘泥成法，呆板不知變通。 ＆比喻按照所掌握的線索辦事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '古書知識要活用，假如只會死守經典，按圖索驥而不知變通是不行的。', '古書知識要活用，假如只會死守經典，按圖索驥而不知變通是不行的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"450"}'::jsonb)
  ,('active', '強弩之末', 'ㄑㄧㄤˊ ㄋㄨˇ ㄓ ㄇㄛˋ', '成語', 3, '「強弩之末」之「強」，典源作「彊」。「彊」同「強」。強勁弓弩所射出的箭，到射程盡頭，已經沒有力道。比喻原本強大的力量已經衰竭，不能再發揮效用。＃語本《史記．卷一○八．韓長孺列傳》。', '「強弩之末」之「強」，典源作「彊」。「彊」同「強」。強勁弓弩所射出的箭，到射程盡頭，已經沒有力道。比喻原本強大的力量已經衰竭，不能再發揮效用。＃語本《史記．卷一○八．韓長孺列傳》。', '比喻原本強大的力量已經衰竭，不能再發揮效用。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '敵人氣勢衰竭，看來已是強弩之末，我軍勝利在望。', '敵人氣勢衰竭，看來已是強弩之末，我軍勝利在望。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"451"}'::jsonb)
  ,('active', '一網打盡', 'ㄧ ㄨㄤˇ ㄉㄚˇ ㄐㄧㄣˋ', '成語', 3, '用網子全部抓住。典出《呂氏春秋．孟冬紀．異用》。後用「一網打盡」比喻排斥異己，不留孑遺。', '用網子全部抓住。典出《呂氏春秋．孟冬紀．異用》。後用「一網打盡」比喻排斥異己，不留孑遺。 △「網開一面」', '用網子全部抓住。＆比喻排斥異己，不留孑遺。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為預防病媒蚊肆虐，一定要設法將牠們一網打盡。', '為預防病媒蚊肆虐，一定要設法將牠們一網打盡。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"452"}'::jsonb)
  ,('active', '蜀犬吠日', 'ㄕㄨˇ ㄑㄩㄢˇ ㄈㄟˋ ㄖˋ', '成語', 3, '蜀地的狗看見了日出，便對著太陽狂叫。＃語本唐．岑參〈招北客文〉。後用「蜀犬吠日」形容人少見多怪。', '蜀地的狗看見了日出，便對著太陽狂叫。＃語本唐．岑參〈招北客文〉。後用「蜀犬吠日」形容人少見多怪。 △「蜀日越雪」、「粵犬吠雪」', '形容人少見多怪。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '對不起！是我們少見多怪，您老就當我們是蜀犬吠日好了。', '對不起！是我們少見多怪，您老就當我們是蜀犬吠日好了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"453"}'::jsonb)
  ,('active', '曲突徙薪', 'ㄑㄩ ㄊㄨˊ ㄒㄧˇ ㄒㄧㄣ', '成語', 3, '將煙囪改彎，把柴薪移走。＃典出漢．劉向《說苑．卷一三．權謀》。後用「曲突徙薪」比喻事先採取措施，以防止危險發生。', '將煙囪改彎，把柴薪移走。＃典出漢．劉向《說苑．卷一三．權謀》。後用「曲突徙薪」比喻事先採取措施，以防止危險發生。 △「有備無患」', '比喻事先採取措施，以防止危險發生。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '不要將易燃物置於火源之旁，曲突徙薪，以策安全。', '不要將易燃物置於火源之旁，曲突徙薪，以策安全。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"454"}'::jsonb)
  ,('active', '矯枉過正', 'ㄐㄧㄠˇ ㄨㄤˇ ㄍㄨㄛˋ ㄓㄥˋ', '成語', 3, '糾正偏差超過適切程度，反而不符合中庸之道。＃語本《越絕書．卷一五．越絕篇敘外傳記十九》。', '糾正偏差超過適切程度，反而不符合中庸之道。＃語本《越絕書．卷一五．越絕篇敘外傳記十九》。', '糾正偏差超過適切程度，反而不符合中庸之道。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '醫生要她減肥，結果她連水都不敢喝，真是矯枉過正。', '醫生要她減肥，結果她連水都不敢喝，真是矯枉過正。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"455"}'::jsonb)
  ,('active', '吳牛喘月', 'ㄨˊ ㄋㄧㄡˊ ㄔㄨㄢˇ ㄩㄝˋ', '成語', 3, '吳地的水牛見到月亮以為是太陽，因此便自以為熱，氣喘不已。＃語本漢．應劭《風俗通義．佚文》。後來也用「吳牛喘月」轉而比喻人見到曾受其害的類似事物，而過分驚懼害怕。也用來形容天氣酷熱。', '吳地的水牛見到月亮以為是太陽，因此便自以為熱，氣喘不已。＃語本漢．應劭《風俗通義．佚文》。後來也用「吳牛喘月」轉而比喻人見到曾受其害的類似事物，而過分驚懼害怕。也用來形容天氣酷熱。', '比喻人見到曾受其害的類似事物而過分驚懼害怕。＆形容天氣酷熱。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '地震一來，大家臉色都變了。你也別笑別人是吳牛喘月，其實你也差不多！', '地震一來，大家臉色都變了。你也別笑別人是吳牛喘月，其實你也差不多！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"456"}'::jsonb)
  ,('active', '居安思危', 'ㄐㄩ ㄢ ㄙ ㄨㄟˊ', '成語', 3, '處於安樂的時候，要想到危險可能會隨時出現。語出《左傳．襄公十一年》所引之《書》。', '處於安樂的時候，要想到危險可能會隨時出現。語出《左傳．襄公十一年》所引之《書》。', '處於安樂的時候，要想到危險可能隨時出現。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在安樂時居安思危，才能防患於未然。', '在安樂時居安思危，才能防患於未然。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"457"}'::jsonb)
  ,('active', '賓至如歸', 'ㄅㄧㄣ ㄓˋ ㄖㄨˊ ㄍㄨㄟ', '成語', 3, '客人來到這裡就好像回到自己的家裡。語出《左傳．襄公三十一年》。後用「賓至如歸」形容主人招待周到親切，使客人感到滿意。', '客人來到這裡就好像回到自己的家裡。語出《左傳．襄公三十一年》。後用「賓至如歸」形容主人招待周到親切，使客人感到滿意。', '形容主人招待周到親切，使客人感到滿意。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這家旅館標榜賓至如歸，果然名不虛傳。', '這家旅館標榜賓至如歸，果然名不虛傳。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"458"}'::jsonb)
  ,('active', '不恥下問', 'ㄅㄨˋ ㄔˇ ㄒㄧㄚˋ ㄨㄣˋ', '成語', 3, '不以向身分較低微或是學問較自己淺陋的人求教為羞恥。語出《論語．公冶長》。', '不以向身分較低微或是學問較自己淺陋的人求教為羞恥。語出《論語．公冶長》。 △「不媿下學」、「無惡下問」', '不以向身分較低微或是學問較自己淺陋的人求教為羞恥。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他的成功就在於他能不恥下問，虛心受教。', '他的成功就在於他能不恥下問，虛心受教。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"459"}'::jsonb)
  ,('active', '不可救藥', 'ㄅㄨˋ ㄎㄜˇ ㄐㄧㄡˋ ㄧㄠˋ', '成語', 3, '病重無藥可醫治。比喻到了無法挽救的地步。語出《詩經．大雅．板》。', '病重無藥可醫治。比喻到了無法挽救的地步。語出《詩經．大雅．板》。', '病重無藥可醫治。＆比喻到了無法挽救的地步。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這病來得好猛，一下子就被宣布不可救藥了。', '他這病來得好猛，一下子就被宣布不可救藥了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"460"}'::jsonb)
  ,('active', '河東獅吼', 'ㄏㄜˊ ㄉㄨㄥ ㄕ ㄏㄡˇ', '成語', 3, '比喻妻子凶悍發威。＃語出宋．蘇軾〈寄吳德仁兼簡陳季常〉詩。', '比喻妻子凶悍發威。＃語出宋．蘇軾〈寄吳德仁兼簡陳季常〉詩。 △「季常之癖」', '比喻妻子凶悍發威。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他居然妄想金屋藏嬌，怎麼能怪河東獅吼呢？', '他居然妄想金屋藏嬌，怎麼能怪河東獅吼呢？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"461"}'::jsonb)
  ,('active', '手舞足蹈', 'ㄕㄡˇ ㄨˇ ㄗㄨˊ ㄉㄠˋ', '成語', 3, '揮手舉足，舞動跳躍。＃語本《詩經．大序》。後亦用「手舞足蹈」形容高興到了極點。', '揮手舉足，舞動跳躍。＃語本《詩經．大序》。後亦用「手舞足蹈」形容高興到了極點。', '揮手舉足，舞動跳躍。＆形容高興到了極點。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '小孩子往往會邊看著電視，邊學著歌星手舞足蹈。', '小孩子往往會邊看著電視，邊學著歌星手舞足蹈。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"462"}'::jsonb)
  ,('active', '愛屋及烏', 'ㄞˋ ㄨ ㄐㄧˊ ㄨ', '成語', 3, '因愛一個人，連帶地也愛護停留在他屋上的烏鴉。比喻愛一個人也連帶地關愛與他有關的一切。＃語本《尚書大傳．卷三．大戰篇》。', '因愛一個人，連帶地也愛護停留在他屋上的烏鴉。比喻愛一個人也連帶地關愛與他有關的一切。＃語本《尚書大傳．卷三．大戰篇》。', '比喻愛一個人也連帶地關愛與他有關的一切。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '因為哥哥是傑出校友，老師愛屋及烏，對我也特別好。', '因為哥哥是傑出校友，老師愛屋及烏，對我也特別好。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"463"}'::jsonb)
  ,('active', '不脛而走', 'ㄅㄨˋ ㄐㄧㄥˋ ㄦˊ ㄗㄡˇ', '成語', 3, '「不脛而走」之「脛」，典源作「足」。脛，小腿。「不脛而走」指沒有腿也能去。＃語本《韓詩外傳》卷六。後用「不脛而走」比喻事物不用推廣，也能迅速傳播。', '「不脛而走」之「脛」，典源作「足」。脛，小腿。「不脛而走」指沒有腿也能去。＃語本《韓詩外傳》卷六。後用「不脛而走」比喻事物不用推廣，也能迅速傳播。 △「不翼而飛」', '比喻事物不用推廣，也能迅速傳播。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '公司財務危機的消息不脛而走，弄得人心惶惶。', '公司財務危機的消息不脛而走，弄得人心惶惶。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"464"}'::jsonb)
  ,('active', '大義滅親', 'ㄉㄚˋ ㄧˋ ㄇㄧㄝˋ ㄑㄧㄣ', '成語', 3, '指為了維護公理正義，不徇私情，滅了犯罪的親人，或讓他們接受法律制裁。語出《左傳．隱公四年》', '指為了維護公理正義，不徇私情，滅了犯罪的親人，或讓他們接受法律制裁。語出《左傳．隱公四年》', '比喻為了維護公理正義，不徇私情，滅了犯罪的親人，或讓他們接受法律制裁。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '歷史上那些能大義滅親的人物，都是令人敬佩的。', '歷史上那些能大義滅親的人物，都是令人敬佩的。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"465"}'::jsonb)
  ,('active', '越俎代庖', 'ㄩㄝˋ ㄗㄨˇ ㄉㄞˋ ㄆㄠˊ', '成語', 3, '俎，禮器。「越俎代庖」本指擔任主祭的人，超越職責，代替廚師下廚。用來比喻踰越職分代人辦事。語本《莊子．逍遙遊》。', '俎，禮器。「越俎代庖」本指擔任主祭的人，超越職責，代替廚師下廚。用來比喻踰越職分代人辦事。語本《莊子．逍遙遊》。', '比喻踰越職分代人辦事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '管理金庫非我職責，我怎能越俎代庖呢？', '管理金庫非我職責，我怎能越俎代庖呢？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"466"}'::jsonb)
  ,('active', '水滴石穿', 'ㄕㄨㄟˇ ㄉㄧ ㄕˊ ㄔㄨㄢ', '成語', 3, '滴水久了可使石穿。比喻持之以恆，事必有成。語本《尸子》。後亦用「水滴石穿」比喻小問題日積月累也會成為大問題。', '滴水久了可使石穿。比喻持之以恆，事必有成。語本《尸子》。後亦用「水滴石穿」比喻小問題日積月累也會成為大問題。 △「繩鋸木斷」', '滴水久了可使石穿。＆比喻持之以恆，事必有成。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '各位看簷下這塊石板都被雨水滴出洞來了，真是水滴石穿的最佳印證。', '各位看簷下這塊石板都被雨水滴出洞來了，真是水滴石穿的最佳印證。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"467"}'::jsonb)
  ,('active', '炙手可熱', 'ㄓˋ ㄕㄡˇ ㄎㄜˇ ㄖㄜˋ', '成語', 3, '手一靠近就覺得很熱。比喻地位尊貴，勢燄熾盛。＃語出唐．裴庭裕《東觀奏記》卷中。後亦用「炙手可熱」比喻廣受歡迎，名聲極盛。', '手一靠近就覺得很熱。比喻地位尊貴，勢燄熾盛。＃語出唐．裴庭裕《東觀奏記》卷中。後亦用「炙手可熱」比喻廣受歡迎，名聲極盛。', '比喻地位尊貴，勢燄熾盛。＆比喻廣受歡迎，名聲極盛。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '當年他在老總跟前真是紅到炙手可熱，誰敢得罪他？', '當年他在老總跟前真是紅到炙手可熱，誰敢得罪他？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"468"}'::jsonb)
  ,('active', '因噎廢食', 'ㄧㄣ ㄧㄝ ㄈㄟˋ ㄕˊ', '成語', 3, '「因噎廢食」之「噎」，典源作「饐」。「饐」同「噎」。因為怕噎死，而不再吃東西。比喻曾經出過差錯，唯恐再錯而不去做該做的事。語本《呂氏春秋．孟秋紀．蕩兵》。', '「因噎廢食」之「噎」，典源作「饐」。「饐」同「噎」。因為怕噎死，而不再吃東西。比喻曾經出過差錯，唯恐再錯而不去做該做的事。語本《呂氏春秋．孟秋紀．蕩兵》。', '比喻曾經出過差錯，唯恐再錯而不去做該做的事。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '因害怕摔飛機而不敢出國，簡直是因噎廢食。', '因害怕摔飛機而不敢出國，簡直是因噎廢食。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"469"}'::jsonb)
  ,('active', '草菅人命', 'ㄘㄠˇ ㄐㄧㄢ ㄖㄣˊ ㄇㄧㄥˋ', '成語', 3, '菅，一種多年生的野草。「草菅人命」比喻輕視人命，任意加以殘害。＃語本《大戴禮記．保傅》。', '菅，一種多年生的野草。「草菅人命」比喻輕視人命，任意加以殘害。＃語本《大戴禮記．保傅》。', '比喻輕視人命，任意加以殘害。貶義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '民主時代一切依法行事，豈可草菅人命？', '民主時代一切依法行事，豈可草菅人命？', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"470"}'::jsonb)
  ,('active', '排難解紛', 'ㄆㄞˊ ㄋㄢˋ ㄐㄧㄝˇ ㄈㄣ', '成語', 3, '排除危難，解決紛爭。語本《戰國策．趙策三》。', '排除危難，解決紛爭。語本《戰國策．趙策三》。', '指排除危難，解決紛爭。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為人排難解紛必須客觀公正，才能使當事人折服。', '為人排難解紛必須客觀公正，才能使當事人折服。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"471"}'::jsonb)
  ,('active', '如魚得水', 'ㄖㄨˊ ㄩˊ ㄉㄜˊ ㄕㄨㄟˇ', '成語', 3, '（一）像魚得游於水。如魚游水之姿，比喻筆法的靈活。語本秦．李斯〈用筆法〉。 （二）像魚得游於水。如魚得水之樂，比喻得到志同道合的人或適合於自己發展的環境。語本《三國志．卷三五．蜀書．諸葛亮傳》。 （三）像魚得游於水。如魚和水之親密，比喻兩人', '（一）像魚得游於水。如魚游水之姿，比喻筆法的靈活。語本秦．李斯〈用筆法〉。 （二）像魚得游於水。如魚得水之樂，比喻得到志同道合的人或適合於自己發展的環境。語本《三國志．卷三五．蜀書．諸葛亮傳》。 （三）像魚得游於水。如魚和水之親密，比喻兩人間情愛親密。※語或出《喻世明言．卷三．新橋市韓五賣春情》。', '比喻得到與自己志同道合的人或適合於自己發展的環境。＆比喻兩人間情愛親密。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '把他安排到研發部門，真是讓他如魚得水，一展長才。', '把他安排到研發部門，真是讓他如魚得水，一展長才。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"472"}'::jsonb)
  ,('active', '流芳百世', 'ㄌㄧㄡˊ ㄈㄤ ㄅㄞˇ ㄕˋ', '成語', 3, '美名流傳後世、為人所稱頌。※＃語或本《三國志．卷五．魏書．后妃傳．文德郭皇后傳》。', '美名流傳後世、為人所稱頌。※＃語或本《三國志．卷五．魏書．后妃傳．文德郭皇后傳》。 △「千載流芳」、「垂芳千載」、「萬古流芳」', '美名流傳後世為人所稱頌。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '連橫以他的歷史巨著《臺灣通史》流芳百世。', '連橫以他的歷史巨著《臺灣通史》流芳百世。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"473"}'::jsonb)
  ,('active', '眾志成城', 'ㄓㄨㄥˋ ㄓˋ ㄔㄥˊ ㄔㄥˊ', '成語', 3, '眾人同心，力量堅固如城。比喻團結一致，同心協力。語本《國語．周語下》。', '眾人同心，力量堅固如城。比喻團結一致，同心協力。語本《國語．周語下》。 △「眾口鑠金」', '比喻團結一致，同心協力。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '軍民團結，眾志成城，是國家安全的最佳保障。', '軍民團結，眾志成城，是國家安全的最佳保障。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"474"}'::jsonb)
  ,('active', '管中窺豹', 'ㄍㄨㄢˇ ㄓㄨㄥ ㄎㄨㄟ ㄅㄠˋ', '成語', 3, '從管中只看見豹的一小部分。比喻所見甚小，未得全貌。※＃語或本南朝宋．劉義慶《世說新語．方正》。', '從管中只看見豹的一小部分。比喻所見甚小，未得全貌。※＃語或本南朝宋．劉義慶《世說新語．方正》。 △「以管窺天」、「管窺蠡測」', '比喻所見甚小，未得全貌。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這是管中窺豹之見，不足為憑。', '他這是管中窺豹之見，不足為憑。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"475"}'::jsonb)
  ,('active', '南柯一夢', 'ㄋㄢˊ ㄎㄜ ㄧ ㄇㄥˋ', '成語', 3, '淳于棼夢中出任南柯太守，歷盡人生窮通榮辱，醒來才知道是一場夢。典出唐．李公佐《南柯太守傳》。後用「南柯一夢」比喻人生如夢，富貴得失無常。', '淳于棼夢中出任南柯太守，歷盡人生窮通榮辱，醒來才知道是一場夢。典出唐．李公佐《南柯太守傳》。後用「南柯一夢」比喻人生如夢，富貴得失無常。', '比喻人生如夢，富貴得失無常。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '人生得又何嘆，失又何怨，恰似南柯一夢罷了。', '人生得又何嘆，失又何怨，恰似南柯一夢罷了。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"476"}'::jsonb)
  ,('active', '束之高閣', 'ㄕㄨˋ ㄓ ㄍㄠ ㄍㄜˊ', '成語', 3, '把東西捆起來，放置於閣樓上。比喻棄置不用。＃語出晉．習鑿齒《漢晉春秋》。', '把東西捆起來，放置於閣樓上。比喻棄置不用。＃語出晉．習鑿齒《漢晉春秋》。', '比喻棄置不用。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '書買回來後，就是要看，而不是把它們束之高閣。', '書買回來後，就是要看，而不是把它們束之高閣。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"477"}'::jsonb)
  ,('active', '忍辱負重', 'ㄖㄣˇ ㄖㄨˋ ㄈㄨˋ ㄓㄨㄥˋ', '成語', 3, '忍受屈辱怨謗而承擔重任。語出《三國志．卷五八．吳書．陸遜傳》。', '忍受屈辱怨謗而承擔重任。語出《三國志．卷五八．吳書．陸遜傳》。', '忍受屈辱怨謗而承擔重任。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '當年句踐為了復國，忍辱負重，歷盡艱辛。', '當年句踐為了復國，忍辱負重，歷盡艱辛。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"478"}'::jsonb)
  ,('active', '臥薪嘗膽', 'ㄨㄛˋ ㄒㄧㄣ ㄔㄤˊ ㄉㄢˇ', '成語', 3, '越王句踐躺臥在柴薪上，不時舔嘗苦膽，以警惕自己不忘所受的屈辱。比喻刻苦自勵，發奮圖強。典出《史記．卷四一．越王句踐世家》。', '越王句踐躺臥在柴薪上，不時舔嘗苦膽，以警惕自己不忘所受的屈辱。比喻刻苦自勵，發奮圖強。典出《史記．卷四一．越王句踐世家》。', '比喻刻苦自勵，發奮圖強。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '在報仇雪恥前，我決定先過臥薪嘗膽的生活。', '在報仇雪恥前，我決定先過臥薪嘗膽的生活。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"479"}'::jsonb)
  ,('active', '買櫝還珠', 'ㄇㄞˇ ㄉㄨˊ ㄏㄨㄢˊ ㄓㄨ', '成語', 3, '買了裝珍珠的盒子，而把珍珠退還。典出《韓非子．外儲說左上》。後用「買櫝還珠」比喻捨本逐末，取捨失當。', '買了裝珍珠的盒子，而把珍珠退還。典出《韓非子．外儲說左上》。後用「買櫝還珠」比喻捨本逐末，取捨失當。', '比喻捨本逐末，取捨失當。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '先把採購資訊和標的掌握好，免得受買櫝還珠的譏諷。', '先把採購資訊和標的掌握好，免得受買櫝還珠的譏諷。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"480"}'::jsonb)
  ,('active', '不求甚解', 'ㄅㄨˋ ㄑㄧㄡˊ ㄕㄣˋ ㄐㄧㄝˇ', '成語', 3, '讀書著重理解義理，而不過度鑽研字句上的解釋。＃語出晉．陶潛〈五柳先生傳〉。後亦用「不求甚解」形容學習或工作的態度不認真，只求略懂皮毛而不深入理解。', '讀書著重理解義理，而不過度鑽研字句上的解釋。＃語出晉．陶潛〈五柳先生傳〉。後亦用「不求甚解」形容學習或工作的態度不認真，只求略懂皮毛而不深入理解。', '讀書著重理解義理，而不過度鑽研字句上的解釋。＆形容學習或工作的態度不認真，只求略懂皮毛而不深入理解。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '讀書要先分類，有些書須精讀，有些因屬參考性質，不求甚解亦無妨。', '讀書要先分類，有些書須精讀，有些因屬參考性質，不求甚解亦無妨。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"481"}'::jsonb)
  ,('active', '青黃不接', 'ㄑㄧㄥ ㄏㄨㄤˊ ㄅㄨˋ ㄐㄧㄝ', '成語', 3, '青，指還沒成熟的綠色禾苗；黃，指舊有的黃熟穀物。「青黃不接」指新穀還沒成熟，存糧又已吃完。※語或本宋．歐陽修〈言青苗錢第二劄子〉。後用「青黃不接」比喻有所匱乏，一時難以為繼。', '青，指還沒成熟的綠色禾苗；黃，指舊有的黃熟穀物。「青黃不接」指新穀還沒成熟，存糧又已吃完。※語或本宋．歐陽修〈言青苗錢第二劄子〉。後用「青黃不接」比喻有所匱乏，一時難以為繼。', '指新穀還沒成熟，存糧又已吃完。＆比喻有所匱乏，一時難以為繼。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '當地農民每到青黃不接的時期，都要靠借高利貸維生，景況讓人同情。', '當地農民每到青黃不接的時期，都要靠借高利貸維生，景況讓人同情。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"482"}'::jsonb)
  ,('active', '自慚形穢', 'ㄗˋ ㄘㄢˊ ㄒㄧㄥˊ ㄏㄨㄟˋ', '成語', 3, '因容貌儀態不如別人而感覺羞愧。語本南朝宋．劉義慶《世說新語．容止》。後用「自慚形穢」泛指與人相比自愧不如。', '因容貌儀態不如別人而感覺羞愧。語本南朝宋．劉義慶《世說新語．容止》。後用「自慚形穢」泛指與人相比自愧不如。', '泛指與人相比自愧不如。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '是我覺得自慚形穢，不敢邀你到我家來。', '是我覺得自慚形穢，不敢邀你到我家來。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"483"}'::jsonb)
  ,('active', '急如星火', 'ㄐㄧˊ ㄖㄨˊ ㄒㄧㄥ ㄏㄨㄛˇ', '成語', 3, '如流星的光那樣急速，形容情勢急迫。＃語本晉．李密〈陳情表〉。', '如流星的光那樣急速，形容情勢急迫。＃語本晉．李密〈陳情表〉。', '形容情勢急迫。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這件公事急如星火，你得快點辦！', '這件公事急如星火，你得快點辦！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"484"}'::jsonb)
  ,('active', '背道而馳', 'ㄅㄟˋ ㄉㄠˋ ㄦˊ ㄔˊ', '成語', 3, '行為不合情理，做事違反正道。※＃語或本唐．白居易〈為人上宰相書〉。後用「背道而馳」比喻彼此的目標或理想完全相反。', '行為不合情理，做事違反正道。※＃語或本唐．白居易〈為人上宰相書〉。後用「背道而馳」比喻彼此的目標或理想完全相反。 △「南轅北轍」', '比喻彼此的目標或理想完全相反。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這種老是和規定背道而馳的人，令我很頭痛。', '這種老是和規定背道而馳的人，令我很頭痛。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"485"}'::jsonb)
  ,('active', '同舟共濟', 'ㄊㄨㄥˊ ㄓㄡ ㄍㄨㄥˋ ㄐㄧˋ', '成語', 3, '同乘一條船渡河，比喻同心協力，戰勝困難。語本《孫子．九地》。', '同乘一條船渡河，比喻同心協力，戰勝困難。語本《孫子．九地》。 △「風雨同舟」', '比喻同心協力，戰勝困難。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '如今國難當前，全國人民要同舟共濟，奮發圖強。', '如今國難當前，全國人民要同舟共濟，奮發圖強。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"486"}'::jsonb)
  ,('active', '披星戴月', 'ㄆㄧ ㄒㄧㄥ ㄉㄞˋ ㄩㄝˋ', '成語', 3, '「披星戴月」之「戴」，典源作「帶」。頂著星月而走，形容早出晚歸、連夜趕路或工作備極勞累。語本唐．呂巖〈七言〉詩其四四。', '「披星戴月」之「戴」，典源作「帶」。頂著星月而走，形容早出晚歸、連夜趕路或工作備極勞累。語本唐．呂巖〈七言〉詩其四四。', '形容早出晚歸、連夜趕路或工作備極勞累。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '為了完成任務，他披星戴月，兼程趕往前線。', '為了完成任務，他披星戴月，兼程趕往前線。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"487"}'::jsonb)
  ,('active', '相敬如賓', 'ㄒㄧㄤ ㄐㄧㄥˋ ㄖㄨˊ ㄅㄧㄣ', '成語', 3, '形容夫妻間相處融洽，互相敬愛。＃語本《左傳．僖公三十三年》。', '形容夫妻間相處融洽，互相敬愛。＃語本《左傳．僖公三十三年》。', '形容夫妻間相處融洽，互相敬愛。褒義。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '賢伉儷相敬如賓，真是令人羨慕。', '賢伉儷相敬如賓，真是令人羨慕。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"488"}'::jsonb)
  ,('active', '鶴立雞群', 'ㄏㄜˋ ㄌㄧˋ ㄐㄧ ㄑㄩㄣˊ', '成語', 3, '鶴站在雞群之中，非常突出。比喻人的儀表才能超群脫凡。＃語本晉．戴逵〈竹林七賢論〉。後亦用「鶴立雞群」比喻事物的不平凡。', '鶴站在雞群之中，非常突出。比喻人的儀表才能超群脫凡。＃語本晉．戴逵〈竹林七賢論〉。後亦用「鶴立雞群」比喻事物的不平凡。', '比喻人的儀表才能超群脫凡。褒義。＆比喻事物的不平凡。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他的數學能力一直在班上鶴立雞群，獨占鰲頭。', '他的數學能力一直在班上鶴立雞群，獨占鰲頭。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"489"}'::jsonb)
  ,('active', '格格不入', 'ㄍㄜˊ ㄍㄜˊ ㄅㄨˋ ㄖㄨˋ', '成語', 3, '格格，阻礙，隔閡。比喻抵觸阻隔而不相合。語本宋．陸九淵〈與徐子宜書〉其二。', '格格，阻礙，隔閡。比喻抵觸阻隔而不相合。語本宋．陸九淵〈與徐子宜書〉其二。 △「方枘圓鑿」', '比喻抵觸阻隔而不相合。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他倆就像方枘圓鑿，自是格格不入。', '他倆就像方枘圓鑿，自是格格不入。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"490"}'::jsonb)
  ,('active', '山窮水盡', 'ㄕㄢ ㄑㄩㄥˊ ㄕㄨㄟˇ ㄐㄧㄣˋ', '成語', 3, '指水陸交通阻斷，無法通行。※語或本北周．庾信〈周兗州刺史廣饒公宇文公神道碑〉。後用「山窮水盡」比喻走投無路，陷入絕境。', '指水陸交通阻斷，無法通行。※語或本北周．庾信〈周兗州刺史廣饒公宇文公神道碑〉。後用「山窮水盡」比喻走投無路，陷入絕境。', '水陸交通阻斷，無法通行。＆比喻走投無路，陷入絕境。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '想不到在這山窮水盡之地，有這麼一座世外桃源。', '想不到在這山窮水盡之地，有這麼一座世外桃源。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"491"}'::jsonb)
  ,('active', '功敗垂成', 'ㄍㄨㄥ ㄅㄞˋ ㄔㄨㄟˊ ㄔㄥˊ', '成語', 3, '指事情在即將成功時卻失敗了。原語如加「於」和「之時」三字，成為「功敗（於）垂成（之時）」，意義就很容易理解。垂，「將近」之意。語出《晉書．卷七九．謝安列傳》。', '指事情在即將成功時卻失敗了。原語如加「於」和「之時」三字，成為「功敗（於）垂成（之時）」，意義就很容易理解。垂，「將近」之意。語出《晉書．卷七九．謝安列傳》。', '指事情在即將成功時卻失敗了。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '這座橋梁本就要完工了，一場大地震卻讓它功敗垂成。', '這座橋梁本就要完工了，一場大地震卻讓它功敗垂成。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"492"}'::jsonb)
  ,('active', '旁若無人', 'ㄆㄤˊ ㄖㄨㄛˋ ㄨˊ ㄖㄣˊ', '成語', 3, '對身旁的人視若無睹，形容說話舉動毫無顧忌。語出《史記．卷八六．刺客列傳．荊軻》。後亦用「旁若無人」形容態度高傲。', '對身旁的人視若無睹，形容說話舉動毫無顧忌。語出《史記．卷八六．刺客列傳．荊軻》。後亦用「旁若無人」形容態度高傲。 △「目中無人」、「目空一切」', '形容說話舉動毫無顧忌。＆形容態度高傲。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '門一打開就看他走了進來，昂首闊步，旁若無人。', '門一打開就看他走了進來，昂首闊步，旁若無人。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"493"}'::jsonb)
  ,('active', '青梅竹馬', 'ㄑㄧㄥ ㄇㄟˊ ㄓㄨˊ ㄇㄚˇ', '成語', 3, '竹馬，小孩夾在胯下當成馬騎的竹竿，有時會加上一個馬頭模型。「青梅竹馬」形容小兒女天真無邪的結伴嬉戲。語本唐．李白〈長干行〉二首之一。後用「青梅竹馬」比喻從小就相識的同伴。', '竹馬，小孩夾在胯下當成馬騎的竹竿，有時會加上一個馬頭模型。「青梅竹馬」形容小兒女天真無邪的結伴嬉戲。語本唐．李白〈長干行〉二首之一。後用「青梅竹馬」比喻從小就相識的同伴。 △「兩小無猜」', '指從小就相識的同伴。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他們以前是青梅竹馬，現在是終身的伴侶。', '他們以前是青梅竹馬，現在是終身的伴侶。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"494"}'::jsonb)
  ,('active', '五體投地', 'ㄨˇ ㄊㄧˇ ㄊㄡˊ ㄉㄧˋ', '成語', 3, '本為古印度最恭敬的致敬儀式，指雙膝雙肘及頭五處著地，佛教徒沿用以禮敬三寶（佛、法、僧）。※語出《大佛頂首楞嚴經》卷一。後用「五體投地」比喻非常欽佩對方。', '本為古印度最恭敬的致敬儀式，指雙膝雙肘及頭五處著地，佛教徒沿用以禮敬三寶（佛、法、僧）。※語出《大佛頂首楞嚴經》卷一。後用「五體投地」比喻非常欽佩對方。', '致敬儀式，指雙膝雙肘及頭五處著地，佛教徒沿用以禮敬三寶。＆比喻非常欽佩。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '一進佛堂，就看到師姑五體投地跪拜在佛像前。', '一進佛堂，就看到師姑五體投地跪拜在佛像前。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"495"}'::jsonb)
  ,('active', '強詞奪理', 'ㄑㄧㄤˇ ㄘˊ ㄉㄨㄛˊ ㄌㄧˇ', '成語', 3, '「強詞奪理」之「奪」，典源作「昧」。形容沒有道理卻強為狡辯，硬說成有理。語本唐．神清《北山錄．卷三．合霸王》。', '「強詞奪理」之「奪」，典源作「昧」。形容沒有道理卻強為狡辯，硬說成有理。語本唐．神清《北山錄．卷三．合霸王》。', '比喻人沒有道理卻強自狡辯。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '誠實為上策，我不願強詞奪理，掩過飾非。', '誠實為上策，我不願強詞奪理，掩過飾非。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"496"}'::jsonb)
  ,('active', '投鞭斷流', 'ㄊㄡˊ ㄅㄧㄢ ㄉㄨㄢˋ ㄌㄧㄡˊ', '成語', 3, '把兵士的馬鞭都投到江裡，就能截斷水流。比喻軍旅眾多，兵力強大。＃語本北魏．崔鴻《前秦錄》。', '把兵士的馬鞭都投到江裡，就能截斷水流。比喻軍旅眾多，兵力強大。＃語本北魏．崔鴻《前秦錄》。', '比喻軍旅眾多，兵力強大。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我今揮軍出征，兵多將廣，具有投鞭斷流的氣概，何敵不摧！', '我今揮軍出征，兵多將廣，具有投鞭斷流的氣概，何敵不摧！', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"497"}'::jsonb)
  ,('active', '天花亂墜', 'ㄊㄧㄢ ㄏㄨㄚ ㄌㄨㄢˋ ㄓㄨㄟˋ', '成語', 3, '「天花亂墜」之「花」，典源作「華」。「華」同「花」。傳說佛祖講經說法，感動了天神，把各色香花從空中紛紛撒下。＃典出《心地觀經．卷一．序品偈》。後亦用「天花亂墜」形容說話動聽，但多浮誇不切實際。', '「天花亂墜」之「花」，典源作「華」。「華」同「花」。傳說佛祖講經說法，感動了天神，把各色香花從空中紛紛撒下。＃典出《心地觀經．卷一．序品偈》。後亦用「天花亂墜」形容說話動聽，但多浮誇不切實際。', '形容說話動聽，或浮誇不切實際。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '他這番高論，真可使頑石點頭，天花亂墜。', '他這番高論，真可使頑石點頭，天花亂墜。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"498"}'::jsonb)
  ,('active', '不速之客', 'ㄅㄨˋ ㄙㄨˋ ㄓ ㄎㄜˋ', '成語', 3, '速，邀請。「不速之客」指沒有邀請就自己來的客人。語出《易經．需卦》', '速，邀請。「不速之客」指沒有邀請就自己來的客人。語出《易經．需卦》', '沒有邀請就自己來的客人。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '拜訪他人應該事先撥個電話，不宜當不速之客。', '拜訪他人應該事先撥個電話，不宜當不速之客。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"499"}'::jsonb)
  ,('active', '勢不兩立', 'ㄕˋ ㄅㄨˋ ㄌㄧㄤˇ ㄌㄧˋ', '成語', 3, '依形勢是不能並存的。比喻敵對的雙方不能同時並存。＃◎語出《戰國策．楚策一》。', '依形勢是不能並存的。比喻敵對的雙方不能同時並存。＃◎語出《戰國策．楚策一》。 △「不共戴天」', '比喻敵對的雙方不能同時並存。', 'literary', '成語', array['成語','教育部成語典','字耕詞庫']::text[], '我與他有不共戴天之仇，勢不兩立。', '我與他有不共戴天之仇，勢不兩立。', '{"kind":"moe-idioms","license":"CC BY-ND 3.0 TW","attribution":"中華民國教育部《成語典》","id":"500"}'::jsonb)
) as v(status, term, zhuyin, part_of_speech, difficulty, short_def, long_def, usage_context, register, category, tags, daily_example, literary_example, source)
where not exists (
  select 1 from public.zg_vocabulary_cards c where c.term = v.term
);

