)
select * from (values
  ('active'::text, '學而時習之，不亦說乎？', '學而時習之，不亦說乎？', 'zh-classical', '孔子', '', '論語·學而', '學習', null, null, null, 'verified_secondary', 'public_domain', 3, array['學習','教育']::text[], '把學習與複習連在一起，快樂來自反覆確認自己真的懂了。', '「時習」強調節奏：不是一次背完，而是依時溫習。寫作也可同理——草稿要留時間回看。', '儒家入門語，談學習態度。', '', '若只重複而不思考，時習會變成空轉。', '把「複習」寫成場面：燈下重讀舊稿、刪掉昨夜自以為巧妙的句子。', '["你最近哪一次複習，真的改變了理解？"]'::jsonb, '用現代場景寫一句「學而時習」的對應。', array['古典','公有領域','學習','教育']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '知之者不如好之者，好之者不如樂之者。', '知之者不如好之者，好之者不如樂之者。', 'zh-classical', '孔子', '', '論語·雍也', '學習', null, null, null, 'verified_secondary', 'public_domain', 3, array['學習','動機']::text[], '程度由「知道」上升到「喜歡」再到「樂在其中」。', '三層動機對寫作者極有用：為交稿而寫、為喜歡而寫、為寫本身而寫，產出與語氣都不同。', '論求學境界。', '', '「樂之」也可能變成自我耽溺，需要外在標準校正。', '檢查角色動機落在哪一層，對話自然會變。', '["你寫作時比較常停在哪一層？"]'::jsonb, '寫三句獨白，分別對應知／好／樂。', array['古典','公有領域','學習','動機']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '路漫漫其修遠兮，吾將上下而求索。', '路漫漫其修遠兮，吾將上下而求索。', 'zh-classical', '屈原', '', '離騷', '堅持', null, null, null, 'verified_secondary', 'public_domain', 3, array['堅持','孤獨','理想']::text[], '路途漫長，仍要上下求索——把堅持寫成空間動作。', '「上下」不是抽象努力，而是可感的攀爬與俯就。長篇小說的中段最需要這種意象。', '楚辭抒情傳統。', '', '求索也可能迷失；可對照「知其不可而為之」。', '用路程意象取代「我很努力」的宣告。', '["你故事裡的「路」具體是什麼？"]'::jsonb, '寫一段主角在長路上求索，但不出現「努力」二字。', array['古典','公有領域','堅持','孤獨','理想']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '人生天地之間，若白駒之過隙，忽然而已。', '人生天地之間，若白駒之過隙，忽然而已。', 'zh-classical', '莊子', '', '莊子·知北遊', '時間', null, null, null, 'verified_secondary', 'public_domain', 3, array['時間','自然','死亡']::text[], '時間像白馬掠過縫隙，強調短暫與倏忽。', '莊子用動物與縫隙把抽象時間變成視覺。短篇收束常用這種「忽然」。', '道家時間觀。', '', '強調倏忽也可能取消責任與計畫的重量。', '找一個具體快速動作，承載時間流逝。', '["你作品裡哪一場戲最需要「忽然」？"]'::jsonb, '不用「時光飛逝」，改寫一個白駒過隙式比喻。', array['古典','公有領域','時間','自然','死亡']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '窮則獨善其身，達則兼善天下。', '窮則獨善其身，達則兼善天下。', 'zh-classical', '孟子', '', '孟子·盡心上', '政治', null, null, null, 'verified_secondary', 'public_domain', 3, array['政治','道德','自我']::text[], '處境不同，責任尺度不同。', '角色倫理可以隨權力變化：無權時守身，有權時擴張善意——也可寫其虛偽版本。', '儒家出處進退。', '', '誰定義「窮／達」？常被權力挪用。', '給對手一個「達」時的合理自辯。', '["你故事中的權力如何改寫道德語言？"]'::jsonb, '寫同一人在窮與達兩種處境的不同選擇。', array['古典','公有領域','政治','道德','自我']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '不積跬步，無以至千里；不積小流，無以成江海。', '不積跬步，無以至千里；不積小流，無以成江海。', 'zh-classical', '荀子', '', '荀子·勸學', '學習', null, null, null, 'verified_secondary', 'public_domain', 3, array['學習','堅持']::text[], '大成來自微小累積。', '適合寫長篇進度與日常練習：不是爆肝一夜，而是跬步。', '勸學名句。', '', '只積累方向錯誤，會走得更遠地錯。', '用「小流」細節寫出角色的長期改變。', '["你現在的跬步是什麼？"]'::jsonb, '寫一週的跬步清單，再寫成一段敘事。', array['古典','公有領域','學習','堅持']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '桃李不言，下自成蹊。', '桃李不言，下自成蹊。', 'zh-classical', '司馬遷', '', '史記·李將軍列傳', '品格', null, null, null, 'verified_secondary', 'public_domain', 3, array['品格','沉默']::text[], '不必自誇，實質會吸引路徑。', '用結果（蹊徑）證明品格，而不是自我介紹。寫人物時極好用。', '贊李廣。', '', '沉默也可能被時代淹沒，需要見證者。', '刪掉角色自誇，改寫別人如何走近他。', '["你主角最有說服力的「不言」是什麼？"]'::jsonb, '寫一個「不言」卻被眾人靠近的場面。', array['古典','公有領域','品格','沉默']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '夕陽無限好，只是近黃昏。', '夕陽無限好，只是近黃昏。', 'zh-classical', '李商隱', '', '登樂遊原', '時間', null, null, null, 'verified_secondary', 'public_domain', 3, array['時間','美','遺憾']::text[], '美與將逝並置，產生張力。', '上句讚美，下句轉折；對比製造餘味。短詩與短篇結尾常用。', '晚唐七絕。', '', '過度感傷會變成套語。', '先給極美，再輕輕揭示代價或時限。', '["你最近看見的「近黃昏」是什麼？"]'::jsonb, '寫一個「極好／將逝」的現代場景。', array['古典','公有領域','時間','美','遺憾']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '山重水複疑無路，柳暗花明又一村。', '山重水複疑無路，柳暗花明又一村。', 'zh-classical', '陸遊', '', '遊山西村', '希望', null, null, null, 'verified_secondary', 'public_domain', 3, array['希望','旅行','轉折']::text[], '絕境後忽見開朗——情節轉折的經典句式。', '先把路堵死（疑無路），再給意外出口。讀者需要前面的「重／複」才吃到「又一村」。', '南宋紀遊詩。', '', '若每次都柳暗花明，張力會疲乏。', '轉折前務必寫足困局，不要突然開掛。', '["你小說中段的「無路」夠不夠真？"]'::jsonb, '寫一段山重水複，再寫一個不落俗套的出口。', array['古典','公有領域','希望','旅行','轉折']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '紙上得來終覺淺，絕知此事要躬行。', '紙上得來終覺淺，絕知此事要躬行。', 'zh-classical', '陸遊', '', '冬夜讀書示子聿', '學習', null, null, null, 'verified_secondary', 'public_domain', 3, array['學習','實踐']::text[], '書本知識淺，真懂靠親身去做。', '對寫作者：只讀寫作書不夠，要寫；只讀人生書不夠，要經驗與觀察。', '教子讀書。', '', '躬行而無反思，也可能重複錯誤。', '讓角色「躬行」一次，再回頭改他的理論口吻。', '["你哪句寫作教條還沒躬行過？"]'::jsonb, '寫角色把書上句子用到現實後碰壁。', array['古典','公有領域','學習','實踐']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '寄蜉蝣於天地，渺滄海之一粟。', '寄蜉蝣於天地，渺滄海之一粟。', 'zh-classical', '蘇軾', '', '赤壁賦', '自然', null, null, null, 'verified_secondary', 'public_domain', 3, array['自然','自我','時間']::text[], '以蜉蝣、滄海對照人的渺小。', '賦體善用對偶與尺度對比。寫風景時可借尺度變化產生哲學感。', '前後赤壁賦之一。', '', '過度渺小化可能取消行動意義。', '先寫極大，再寫極小，讓情緒自己出現。', '["你的敘事聲音站在蜉蝣還是滄海？"]'::jsonb, '用一組大小對比寫夜景，不出現「渺小」。', array['古典','公有領域','自然','自我','時間']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '人生如逆旅，我亦是行人。', '人生如逆旅，我亦是行人。', 'zh-classical', '蘇軾', '', '臨江仙·送錢穆父', '旅行', null, null, null, 'verified_secondary', 'public_domain', 3, array['旅行','友情','時間']::text[], '人生是旅舍，自己也是過客。', '把存在寫成短暫投宿，送別詩因此不黏膩。', '送別。', '', '過客意識也可能變成不負責任。', '寫離別時，讓雙方都承認自己是行人。', '["故事裡誰把人生當家，誰當逆旅？"]'::jsonb, '寫車站送别，核心意象是逆旅。', array['古典','公有領域','旅行','友情','時間']::text[], '{"kind":"curated-classical","license":"public domain"}'::jsonb)
  ,('active', '把句子寫短，把意思寫深。', null, 'zh', '字耕', '字耕寫作課原創提示。', '寫作箴言', '密度', null, null, null, 'verified_secondary', 'original', 2, array['寫作','密度']::text[], '寫作主題「密度」的實用提示。', '字耕原創，非名人語錄。', '寫作練習用。', '', '任何技法都有適用邊界。', '把句子寫短，把意思寫深。', '["如何把「密度」練成一篇三百字練習？"]'::jsonb, '用「密度」寫一段 120 字練習。', array['字耕','寫作箴言','密度']::text[], '{"kind":"zi-geng-original"}'::jsonb)
  ,('active', '細節比形容詞更靠近真實。', null, 'zh', '字耕', '字耕寫作課原創提示。', '寫作箴言', '細節', null, null, null, 'verified_secondary', 'original', 2, array['寫作','細節']::text[], '寫作主題「細節」的實用提示。', '字耕原創，非名人語錄。', '寫作練習用。', '', '任何技法都有適用邊界。', '細節比形容詞更靠近真實。', '["如何把「細節」練成一篇三百字練習？"]'::jsonb, '用「細節」寫一段 120 字練習。', array['字耕','寫作箴言','細節']::text[], '{"kind":"zi-geng-original"}'::jsonb)
  ,('active', '先寫清楚，再寫漂亮。', null, 'zh', '字耕', '字耕寫作課原創提示。', '寫作箴言', '清楚', null, null, null, 'verified_secondary', 'original', 2, array['寫作','清楚']::text[], '寫作主題「清楚」的實用提示。', '字耕原創，非名人語錄。', '寫作練習用。', '', '任何技法都有適用邊界。', '先寫清楚，再寫漂亮。', '["如何把「清楚」練成一篇三百字練習？"]'::jsonb, '用「清楚」寫一段 120 字練習。', array['字耕','寫作箴言','清楚']::text[], '{"kind":"zi-geng-original"}'::jsonb)
  ,('active', '信任讀者，少把潛台詞講破。', null, 'zh', '字耕', '字耕寫作課原創提示。', '寫作箴言', '潛台詞', null, null, null, 'verified_secondary', 'original', 2, array['寫作','潛台詞']::text[], '寫作主題「潛台詞」的實用提示。', '字耕原創，非名人語錄。', '寫作練習用。', '', '任何技法都有適用邊界。', '信任讀者，少把潛台詞講破。', '["如何把「潛台詞」練成一篇三百字練習？"]'::jsonb, '用「潛台詞」寫一段 120 字練習。', array['字耕','寫作箴言','潛台詞']::text[], '{"kind":"zi-geng-original"}'::jsonb)
