  ,('active', '一個好結尾，常是最後一個未說出口的字。', null, 'zh', '字耕', '字耕寫作課原創提示。', '寫作箴言', '結尾', null, null, null, 'verified_secondary', 'original', 2, array['寫作','結尾']::text[], '寫作主題「結尾」的實用提示。', '字耕原創，非名人語錄。', '寫作練習用。', '', '任何技法都有適用邊界。', '一個好結尾，常是最後一個未說出口的字。', '["如何把「結尾」練成一篇三百字練習？"]'::jsonb, '用「結尾」寫一段 120 字練習。', array['字耕','寫作箴言','結尾']::text[], '{"kind":"zi-geng-original"}'::jsonb)
